/* 申论常用名言1000句 · 按主题（一、XXX篇）归类 · window.ESSAY_QUOTES_THEMED */
window.ESSAY_QUOTES_THEMED = {"中国精神篇":[{"id":"q-00-0000","t":"深入实施红色基因传承工程，大力弘扬以爱国主义为核心的民族精神、以改革创新为核心的时代精神，不断增强对中华民族的认同感和自豪感，振奋各族人民奋进新征程、建功新时代的精气神。","author":"习近平"},{"id":"q-00-0001","t":"人无精神则不立，国无精神则不强。唯有精神上站得住、站得稳，一个民族才能在历史洪流中屹立不倒、挺立潮头。","author":"习近平"},{"id":"q-00-0002","t":"保护好、运用好红色资源，加强革命传统和爱国主义教育，引导广大干部群众发扬优良传统、赓续红色血脉，践行社会主义核心价值观，培育时代新风新貌。","author":"习近平"},{"id":"q-00-0003","t":"中国人民在长期奋斗中培育、继承、发展起来的伟大民族精神，为中国发展和人类文明进步提供了强大精神动力。","author":"习近平"},{"id":"q-00-0004","t":"有这样伟大的人民，有这样伟大的民族，有这样的伟大民族精神，是我们的骄傲，是我们坚定中国特色社会主义道路自信、理论自信、制度自信、文化自信的底气，也是我们风雨无阻、高歌行进的根本力量！","author":"习近平"},{"id":"q-00-0005","t":"人生自古谁无死，留取丹心照汗青。","author":"宋·文天祥《过零丁洋》"},{"id":"q-00-0006","t":"天行健，君子以自强不息；地势坤，君子以厚德载物。","author":"《周易》"},{"id":"q-00-0007","t":"惟有民魂是值得宝贵的，惟有他发扬起来，中国才有真进步。","author":"鲁迅"},{"id":"q-00-0008","t":"天下兴亡，匹夫有责。","author":"明·顾炎武《日知录·正始》"},{"id":"q-00-0009","t":"爱国主义就是千百年来巩固起来的对自己祖国的一种最深厚的感情。","author":"列宁"},{"id":"q-00-0010","t":"爱国是文明人的首要美德。","author":"拿破仑"},{"id":"q-00-0011","t":"虚荣的人注视着自己的名字，光荣的人注视着祖国的事业。","author":"何塞·马蒂"},{"id":"q-00-0012","t":"科学成就离不开精神支撑。科学家精神是科技工作者在长期科学实践中积累的宝贵精神财富。","author":"习近平"},{"id":"q-00-0013","t":"学术道德、严谨治学的表率，甘为人梯、奖掖后学的表率。","author":"习近平"},{"id":"q-00-0014","t":"希望广大科技工作者不忘初心、牢记使命，秉持国家利益和人民利益至上，继承和发扬老一辈科学家胸怀祖国、服务人民的优秀品质，弘扬“两弹一星”精神，主动肩负起历史重任，把自己的科学追求融入建设社会主义现代化国家的伟大事业中去。","author":"习近平"},{"id":"q-00-0015","t":"广大科技工作者要树立敢于创造的雄心壮志，敢于提出新理论、开辟新领域、探索新路径，在独创独有上下功夫。","author":"习近平"},{"id":"q-00-0016","t":"具有强烈的爱国情怀，是对我国科技人员第一位的要求。科学没有国界，科学家有祖国。","author":"习近平"},{"id":"q-00-0017","t":"要持续营造尊重劳动、尊重知识、尊重人才、尊重创造的社会氛围，大力弘扬科学家精神，激励广大科研人员志存高远、爱国奉献、矢志创新。","author":"习近平"},{"id":"q-00-0018","t":"我国几代科技工作者通过接续奋斗铸就的“两弹一星”精神、西迁精神、载人航天精神、科学家精神、探月精神、新时代北斗精神等，共同塑造了中国特色创新生态，成为支撑基础研究发展的不竭动力。","author":"习近平"},{"id":"q-00-0019","t":"我作为一名中国的科技工作者，活着的目的就是为人民服务。如果人民最后对我的一生所做的工作表示满意的话，那才是最高的奖赏。","author":"钱学森"},{"id":"q-00-0020","t":"我们的科研队伍要精，专业研究要深。不能空想，不能脱离实际，一切都是从实际中来的。","author":"程开甲"},{"id":"q-00-0021","t":"科学是实事求是的学问，来不得半点虚假。","author":"华罗庚"},{"id":"q-00-0022","t":"科学工作千万不能固执己见。缺乏勇于认错的精神，是会吃大亏的。","author":"钱学森"},{"id":"q-00-0023","t":"党中央号召，全国科技工作者要向国家最高科学技术奖获奖者及全体获奖人员学习，更加紧密团结在以习近平同志为核心的党中央周围，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，锚定科技强国建设目标，坚持“四个面向”，大力弘扬爱国、创新、求实、奉献、协同、育人的科学家精神，加强基础研究和应用基础研究，打好关键核心技术攻坚战，加快实现高水平科技自立自强，以科技创新支撑高质量发展、保障高水平安全，培育发展新质生产力，为以中国式现代化全面推进强国建设、民族复兴伟业作出新的更大贡献。","author":"《中共中央国务院关于2023年度国家科学技术奖励的决定》"},{"id":"q-00-0024","t":"人才，激励引导青年科技人才大力弘扬科学家精神，传承“两弹一星”精神，继承和发扬老一代科学家科技报国的优秀品质，坚持“四个面向”，坚定敢为人先的创新自信，坚守科研诚信、科技伦理、学术规范，担当作为、求实创新、潜心研究，在实现高水平科技自立自强和建设科技强国、人才强国实践中建功立业，在以中国式现代化全面推进中华民族伟大复兴进程中奉献青春和智慧。","author":"《关于进一步加强青年科技人才培养和使用的若干措施》"},{"id":"q-00-0025","t":"大力弘扬勇攀高峰、敢为人先的创新精神。坚定敢为天下先的自信和勇气，面向世界科技前沿，面向国民经济主战场，面向国家重大战略需求，抢占科技竞争和未来发展制高点。敢于提出新理论、开辟新领域、探寻新路径，不畏挫折、敢于试错，在独创独有上下功夫，在解决受制于人的重大瓶颈问题上强化担当作为。","author":"《关于进一步弘扬科学家精神加强作风和学风建设的意见》"},{"id":"q-00-0026","t":"大力弘扬追求真理、严谨治学的求实精神。把热爱科学、探求真理作为毕生追求，始终保持对科学的好奇心。坚持解放思想、独立思辨、理性质疑，大胆假设、认真求证，不迷信学术权威。坚持立德为先、诚信为本，在践行社会主义核心价值观、引领社会良好风尚中率先垂范。","author":"《关于进一步弘扬科学家精神加强作风和学风建设的意见》"},{"id":"q-00-0027","t":"中国人民在抗日战争的壮阔进程中孕育出伟大抗战精神，向世界展示了天下兴亡、匹夫有责的爱国情怀，视死如归、宁死不屈的民族气节，不畏强暴、血战到底的英雄气概，百折不挠、坚忍不拔的必胜信念。","author":"习近平"},{"id":"q-00-0028","t":"我们要弘扬伟大抗战精神，以压倒一切困难而不为困难所压倒的决心和勇气，敢于斗争，善于创造，锲而不舍为实现中华民族伟大复兴而奋斗，直至取得最后的胜利。","author":"习近平"},{"id":"q-00-0029","t":"无论条件多么艰苦、形势多么险恶、战争多么残酷，中国共产党始终坚持抗战、反对投降，坚持团结、反对分裂，坚持进步、反对倒退，同各爱国党派团体和广大人民一起，共同维护团结抗战大局。","author":"习近平"},{"id":"q-00-0030","t":"伟大抗战精神，是中国人民弥足珍贵的精神财富，将永远激励中国人民克服一切艰难险阻、为实现中华民族伟大复兴而奋斗。","author":"习近平"},{"id":"q-00-0031","t":"我们要不忘联合国宪章初心，牢记守护和平使命。","author":"习近平"},{"id":"q-00-0032","t":"宁为战死鬼，不作亡国奴。","author":"宋哲元"},{"id":"q-00-0033","t":"我死国生，我死犹荣，身虽死精神长生，成功成仁，实现大同。","author":"赵博生"},{"id":"q-00-0034","t":"举世不知何足怪，力行无顾是豪雄。","author":"宋·曾巩《圣贤》"},{"id":"q-00-0035","t":"生为百夫雄，死为壮士规。","author":"魏晋·王粲《咏史诗》"},{"id":"q-00-0036","t":"国外名言为祖国而死，那是最美的命运啊！","author":"大仲马"},{"id":"q-00-0037","t":"在长期实践中，我们培育形成了爱岗敬业、争创一流、艰苦奋斗、勇于创新、淡泊名利、甘于奉献的劳模精神，崇尚劳动、热爱劳动、辛勤劳动、诚实劳动的劳动精神，执着专注、精益求精、一丝不苟、追求卓越的工匠精神。","author":"习近平"},{"id":"q-00-0038","t":"要大力弘扬劳模精神、劳动精神、工匠精神，发挥好劳模工匠示范引领作用，激励广大职工在辛勤劳动、诚实劳动、创造性劳动中成就梦想。","author":"习近平"},{"id":"q-00-0039","t":"光荣属于劳动者，幸福属于劳动者。我国工人阶级和广大劳动群众要更加紧密地团结在党中央周围，勤于创造、勇于奋斗，努力在全面建设社会主义现代化国家新征程上创造新的时代辉煌、铸就新的历史伟业。","author":"习近平"},{"id":"q-00-0040","t":"全社会要崇尚劳动、见贤思齐，加大对劳动模范和先进工作者的宣传力度，讲好劳模故事、讲好劳动故事、讲好工匠故事，弘扬劳动最光荣、劳动最崇高、劳动最伟大、劳动最美丽的社会风尚。","author":"习近平"},{"id":"q-00-0041","t":"牛吃草，马吃料，牛的享受最少，出力最大，所以还是当一头黄牛最好，我甘愿为党、为人民当一辈子老黄牛。","author":"王进喜"},{"id":"q-00-0042","t":"百尺竿头立不难，一勤天下无难事。","author":"钱德苍《解人颐·勤懒歌》"},{"id":"q-00-0043","t":"劳动永远是人类生活的基础，是创造人类生活和文化幸福的基础。","author":"马卡连柯"},{"id":"q-00-0044","t":"荣誉在于劳动的双手。","author":"达·芬奇"},{"id":"q-00-0045","t":"劳动是世界上一切欢乐和一切美好事情的源泉。","author":"高尔基"},{"id":"q-00-0046","t":"人的幸福存在于生活之中，生活存在于劳动之中。","author":"列夫·托尔斯泰"},{"id":"q-00-0047","t":"中华民族是英雄辈出的民族，新时代是成就英雄的时代。全党全社会要崇尚英雄、学习英雄、关爱英雄，大力弘扬英雄精神，汇聚实现中华民族伟大复兴的磅礴力量。","author":"习近平"},{"id":"q-00-0048","t":"一个有希望的民族不能没有英雄，一个有前途的国家不能没有先锋。","author":"习近平"},{"id":"q-00-0049","t":"今天，中国正在发生日新月异的变化，我们比历史上任何时期都更加接近实现中华民族伟大复兴的目标。实现我们的目标，需要英雄，需要英雄精神。","author":"习近平"},{"id":"q-00-0050","t":"中华民族是崇尚英雄、成就英雄、英雄辈出的民族，和平年代同样需要英雄情怀。","author":"习近平"},{"id":"q-00-0051","t":"红色江山来之不易，守好江山责任重大。要讲好党的故事、革命的故事、英雄的故事，把红色基因传承下去，确保红色江山后继有人、代代相传。","author":"习近平"},{"id":"q-00-0052","t":"我们的红色江山是千千万万革命烈士用鲜血和生命换来的。江山就是人民，人民就是江山。我们决不允许江山变色，人民也绝不答应。吃水不忘挖井人。","author":"习近平"},{"id":"q-00-0053","t":"英雄者，国之干，庶民者，国之本。","author":"《三略·上略》"},{"id":"q-00-0054","t":"男儿志兮天下事，但有进兮不有止，言志已酬便无志。","author":"清·梁启超《志未酬》"},{"id":"q-00-0055","t":"天地英雄气，千秋尚凛然。","author":"唐·刘禹锡《蜀先主庙》"},{"id":"q-00-0056","t":"出师未捷身先死，长使英雄泪沾襟。","author":"杜甫《蜀相》"},{"id":"q-00-0057","t":"英雄就是这样一个人，他在决定性关头做了为人类社会的利益所需要的事。","author":"伏契克"},{"id":"q-00-0058","t":"英雄就是对任何事都全力以赴，自始至终，心无旁骛的人。","author":"波德莱尔"},{"id":"q-00-0060","t":"要围绕深入实施科教兴国战略、人才强国战略、创新驱动发展战略，深化产业工人队伍建设改革，加快建设一支知识型、技能型、创新型产业工人大军，培养造就更多大国工匠和高技能人才。","author":"习近平"},{"id":"q-00-0061","t":"文物保护修复是一项长期任务，要加大国家支持力度，加强人才队伍建设，发扬严谨细致的工匠精神，一件一件来，久久为功，做出更大成绩。","author":"习近平"},{"id":"q-00-0062","t":"新形势下，我国工人阶级和广大劳动群众要继续学先进赶先进，自觉践行社会主义核心价值观，用劳动模范和先进工作者的崇高精神和高尚品格鞭策自己，焕发劳动热情，厚植工匠文化，恪守职业道德，将辛勤劳动、诚实劳动、创造性劳动作为自觉行为。","author":"习近平"},{"id":"q-00-0063","t":"不矜细行，终累大德。","author":"《尚书·周书·旅獒》"},{"id":"q-00-0064","t":"千里之缪，不容秋毫。","author":"唐•刘禹锡《董氏武陵集纪》"},{"id":"q-00-0065","t":"不一则不专，不专则不能。","author":"宋•苏轼《应制举上两制书》"},{"id":"q-00-0066","t":"全面提升能力。因地制宜、因材施教，将工匠个体培训和工匠队伍培育相结合，畅通工匠学习、晋级渠道，激发内生动力，促进工匠职业技能与综合素质同步提升。","author":"《住房城乡建设部人力资源社会保障部关于加强乡村建设工匠培训和管理的指导意见》"},{"id":"q-00-0067","t":"加强工匠职业和相关政策法规的宣传，充分利用各类媒体，宣传工匠先进典型和优秀工程案例，营造全社会尊重工匠、尊重劳动的社会氛围。","author":"《住房城乡建设部人力资源社会保障部关于加强乡村建设工匠培训和管理的指导意见》"},{"id":"q-00-0068","t":"各地要积极总结提炼乡村工匠“双百双千”培育工程典型经验，充分利用各类媒体平台，宣传乡村工匠名师、大师典型案例，传播技能文化，弘扬工匠精神，在全社会营造尊重劳动、尊重人才、尊重创造的良好氛围。","author":"《乡村工匠“双百双千”培育工程实施方案》"},{"id":"q-00-0069","t":"加快建设国家战略人才力量，努力培养造就更多大师、战略科学家、一流科技领军人才和创新团队、青年科技人才、卓越工程师、大国工匠、高技能人才。","author":"中国共产党第二十次全国代表大会"},{"id":"q-00-0070","t":"雷锋是时代的楷模，雷锋精神是永恒的。实现中华民族伟大复兴，需要更多时代楷模。","author":"习近平"},{"id":"q-00-0071","t":"雷锋精神，人人可学；奉献爱心，处处可为。","author":"习近平"},{"id":"q-00-0072","t":"我们要见贤思齐，把雷锋精神代代传承下去。学习雷锋精神，就要把崇高的理想信念和道德品质追求融入日常的工作生活，在自己岗位上做一颗永不生锈的螺丝钉。","author":"习近平"},{"id":"q-00-0073","t":"新征程上，要深刻把握雷锋精神的时代内涵，更好发挥党员、干部模范带头作用，加强志愿服务保障和支持，不断发展壮大学雷锋志愿服务队伍，让学雷锋在人民群众特别是青少年中蔚然成风，让学雷锋活动融入日常、化作经常，让雷锋精神在新时代绽放更加璀璨的光芒，为全面建设社会主义现代化国家、全面推进中华民族伟大复兴凝聚强大力量。","author":"习近平"},{"id":"q-00-0074","t":"实践证明，无论时代如何变迁，雷锋精神永不过时。","author":"习近平"},{"id":"q-00-0075","t":"我就是长着一个心眼，我一心向着党，向着社会主义，向着共产主义。","author":"雷锋"},{"id":"q-00-0076","t":"人的生命是有限的，可是，为人民服务是无限的，我要把有限的生命，投入到无限的为人民服务之中去。","author":"雷锋"},{"id":"q-00-0077","t":"当祖国和人民处在最危急的关头，我就挺身而出，不怕牺牲。","author":"雷锋"},{"id":"q-00-0078","t":"我愿在暴风雨中，艰苦的斗争中锻炼自己，不愿在平平静静的日子里度过自己的一生。","author":"雷锋"},{"id":"q-00-0079","t":"不经风雨，长不成大树；不受百炼，难以成钢。","author":"雷锋"},{"id":"q-00-0080","t":"我们要弘扬中华体育精神，弘扬体育道德风尚，推动群众体育、竞技体育、体育产业协调发展，加快建设体育强国。","author":"习近平"},{"id":"q-00-0081","t":"我国广大运动员、教练员以实际行动落实拿道德金牌、风格金牌、干净金牌的要求，诠释了奥林匹克精神和中华体育精神，实现了运动成绩和精神文明双丰收，为党和人民赢得了荣誉！","author":"习近平"},{"id":"q-00-0082","t":"起来，把弘扬中华体育精神同坚定文化自信结合起来，坚持举国体制和市场机制相结合，不忘初心，持之以恒，努力开创新时代我国体育事业新局面。","author":"习近平"},{"id":"q-00-0083","t":"加快建设体育强国，就要弘扬中华体育精神，弘扬体育道德风尚，坚定自信，奋力拼搏，提高竞技体育综合实力，更好发挥举国体制作用，把竞技体育搞得更好、更快、更高、更强，提高为国争光能力，让体育为社会提供强大正能量。","author":"习近平"},{"id":"q-00-0084","t":"引导广大青少年继续弘扬奥林匹克精神，积极参与体育健身运动，强健体魄、砥砺意志，凝聚和焕发青春力量，为中华民族伟大复兴作出应有贡献。","author":"习近平"},{"id":"q-00-0085","t":"发展体育运动，增强人民体质。","author":"毛泽东"},{"id":"q-00-0086","t":"努力发展体育事业，把我们的国民锻炼成为身体健康精神愉快的人。","author":"朱德"},{"id":"q-00-0087","t":"弘扬中华体育精神，推广中华传统体育项目，形成“一校一品”、“一校多品”的学校体育发展新局面。","author":"《关于全面加强和改进新时代学校体育工作的意见》"},{"id":"q-00-0088","t":"开展全民健身志愿服务活动优秀案例征集暨交流展示活动，选取典型优秀案例进行品牌培育并进行深入宣传推广，通过志愿服务弘扬中华体育精神，讲好中国故事体育篇章。","author":"《2024年群众体育工作要点》"},{"id":"q-00-0089","t":"延安精神培育了一代代中国共产党人，是我们党的宝贵精神财富。要坚持不懈用延安精神教育广大党员、干部，用以滋养初心、淬炼灵魂，从中汲取信仰的力量、查找党性的差距、校准前进的方向。","author":"习近平"},{"id":"q-00-0090","t":"伟大的延安精神滋养了几代中国共产党人，始终是凝聚人心、战胜困难、开拓前进的强大精神力量。","author":"习近平"},{"id":"q-00-0091","t":"要继续挖掘延安精神这个宝藏，教育各级领导干部始终保持和发展共产党人的先进性。","author":"习近平"},{"id":"q-00-0092","t":"老一辈革命家和老一代共产党人在延安时期留下的优良传统和作风，培育形成的以坚定正确的政治方向、解放思想实事求是的思想路线、全心全意为人民服务的根本宗旨、自力更生艰苦奋斗的创业精神为主要内容的延安精神，是我们党的宝贵精神财富。","author":"习近平"},{"id":"q-00-0093","t":"自力更生、艰苦奋斗是我们共产党人的品质，是我们立党立国的根基，也是党员、干部立身立业的根基。","author":"习近平"},{"id":"q-00-0094","t":"人类要在竞争中求生存，更要奋斗。","author":"孙中山"},{"id":"q-00-0095","t":"锲而不舍，金石可镂。","author":"荀况《劝学篇》"},{"id":"q-00-0096","t":"名必有实，事必有功。","author":"荀悦《申鉴》"},{"id":"q-00-0097","t":"伟大的事业是根源于坚韧不断的工作，以全副精神去从事，不避艰苦。","author":"罗素"},{"id":"q-00-0098","t":"顽强的毅力可以征服世界上任何一座高峰。","author":"狄更斯"},{"id":"q-00-0099","t":"不靠猜想，而要根据事实。","author":"拉瓦锡"},{"id":"q-00-0100","t":"广大青年要继承和发扬五四精神，坚定不移听党话、跟党走，争做有理想、敢担当、能吃苦、肯奋斗的新时代好青年，在推进强国建设、民族复兴伟业中展现青春作为、彰显青春风采、贡献青春力量，奋力书写为中国式现代化挺膺担当的青春篇章。","author":"习近平"},{"id":"q-00-0101","t":"新时代新征程上，全国各族青年听从党和人民的召唤，在科技创新、乡村振兴、绿色发展、社会服务、卫国戍边等各领域各方面勇当排头兵和生力军，展现出自信自强、刚健有为的精神风貌。党中央对广大青年充分信任、寄予厚望！","author":"习近平"},{"id":"q-00-0102","t":"新时代中国青年要继承和发扬五四精神，坚定理想信念，站稳人民立场，练就过硬本领，投身强国伟业，始终保持艰苦奋斗的前进姿态，同亿万人民一道，在实现中华民族伟大复兴中国梦的新长征路上奋勇搏击。","author":"习近平"},{"id":"q-00-0103","t":"今天，新时代中国青年处在中华民族发展的最好时期，既面临着难得的建功立业的人生际遇，也面临着“天将降大任于斯人”的时代使命。新时代中国青年要继续发扬五四精神，以实现中华民族伟大复兴为己任，不辜负党的期望、人民期待、民族重托，不辜负我们这个伟大时代。","author":"习近平"},{"id":"q-00-0104","t":"五四运动标识了中国青年运动的正确方向，我们要从实现中华民族伟大复兴的中国梦中更加自觉地坚持党对青年的政治引领。","author":"李强"},{"id":"q-00-0105","t":"年前爆发的五四运动，是我国近现代史上具有里程碑意义的重大事件，其意义随着历史演进愈发彰显其光芒。","author":"李强"},{"id":"q-00-0106","t":"今天我们纪念五四运动、发扬五四精神，必须提高政治站位，把握这一重大事件的历史意义、时代价值和深远影响，让伟大的五四精神在新的伟大实践中放射出更加夺目的时代光芒。","author":"李强"},{"id":"q-00-0107","t":"五四运动促进了马克思主义在中国的广泛传播，我们要从马克思主义中国化的历史进程中更加自觉地坚持这一指导思想。","author":"李强"},{"id":"q-00-0108","t":"五四运动开启了寻找适合中国发展道路的新探索，我们要从时代风云的变幻中更加自觉地坚持中国特色社会主义道路。","author":"李强"},{"id":"q-00-0109","t":"青年之于社会，犹新鲜活泼细胞之在身。","author":"陈独秀"},{"id":"q-00-0110","t":"独立之精神，自由之思想。","author":"陈寅恪"},{"id":"q-00-0111","t":"少年智则国智，少年富则国富，少年强则国强。","author":"梁启超"},{"id":"q-00-0112","t":"企业家要带领企业战胜当前的困难，走向更辉煌的未来，就要弘扬企业家精神，在爱国、创新、诚信、社会责任和国际视野等方面不断提升自己。","author":"习近平"},{"id":"q-00-0113","t":"优秀企业家必须对国家、对民族怀有崇高使命感和强烈责任感，把企业发展同国家繁荣、民族兴盛、人民幸福紧密结合在一起，主动为国担当、为国分忧，正所谓“利于国者爱之，害于国者恶之”。","author":"习近平"},{"id":"q-00-0114","t":"企业家要立足中国，放眼世界，提高把握国际市场动向和需求特点的能力，提高把握国际规则能力，提高国际市场开拓能力，提高防范国际市场风险能力，带动企业在更高水平的对外开放中实现更好发展，促进国内国际双循环。","author":"习近平"},{"id":"q-00-0115","t":"希望广大民营经济人士切实贯彻新发展理念，大力弘扬企业家精神，争做爱国敬业、守法经营、创业创新、回报社会的典范为全面建设社会主义现代化国、家全面推进中华民族伟大复兴贡献力量。","author":"习近平"},{"id":"q-00-0116","t":"民营企业和民营企业家要筑牢依法合规经营底线，弘扬优秀企业家精神，做爱国敬业、守法经营、创业创新、回报社会的典范。","author":"习近平"},{"id":"q-00-0117","t":"根深叶茂，主根要扎稳，这是一种企业家精神的体现。","author":"习近平"},{"id":"q-00-0118","t":"民营企业家要增强家国情怀，自觉践行以人民为中心的发展思想，增强先富带后富、促进共同富裕的责任感和使命感。","author":"习近平"},{"id":"q-00-0119","t":"弘扬企业家精神，提高企业家科学素质，引导企业家在爱国、创新、诚信、社会责任和国际视野等方面不断提升，做创新发展的探索者、组织者、引领者和提升产业工人科学素质的推动者。","author":"《全民科学素质行动规划纲要（2021—2035年）》"},{"id":"q-00-0120","t":"弘扬企业家精神，实施年轻一代民营企业家健康成长促进计划。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"}],"经济发展篇":[{"id":"q-01-0000","t":"全面贯彻信任、团结、服务、引导、教育的方针，用务实举措稳定人心、鼓舞人心、凝聚人心，引导民营经济人士弘扬企业家精神。","author":"《中共中央国务院关于促进民营经济发展壮大的意见》"},{"id":"q-01-0001","t":"高质量发展不只是一个经济要求，而是对经济社会发展方方面面的总要求；不是只对经济发达地区的要求，而是所有地区发展都必须贯彻的要求；不是一时一事的要求，而是必须长期坚持的要求。","author":"习近平"},{"id":"q-01-0002","t":"要牢牢把握高质量发展这个首要任务，因地制宜发展新质生产力。","author":"习近平"},{"id":"q-01-0003","t":"要始终把最广大人民根本利益放在心上，坚定不移增进民生福祉，把高质量发展同满足人民美好生活需要紧密结合起来，推动坚持生态优先、推动高质量发展、创造高品质生活有机结合、相得益彰。","author":"习近平"},{"id":"q-01-0004","t":"立足新发展阶段、贯彻新发展理念、构建新发展格局，推动高质量发展，是当前和今后一个时期全党全国必须抓紧抓好的工作。","author":"习近平"},{"id":"q-01-0005","t":"党的十八大以来，我们实施了一系列区域协调发展战略、区域重大战略、主体功能区战略等，为构建新发展格局、推动高质量发展发挥了重要支撑作用。","author":"习近平"},{"id":"q-01-0006","t":"无欲速，无见小利。欲速则不达，见小利则大事不成。","author":"《论语》"},{"id":"q-01-0007","t":"天下难事，必作于易，天下大事，必作于细。是以圣人终不为大，故能成其大。","author":"春秋·老子《道德经》"},{"id":"q-01-0008","t":"高水平科技自立自强、推动高质量发展的重要举措，压实主体责任，精心组织实施。","author":"《促进创业投资高质量发展的若干政策措施》"},{"id":"q-01-0009","t":"民营经济是高质量发展的重要基础，是推动我区实现闯新路、进中游目标的生力军，是以铸牢中华民族共同体意识为工作主线奋力书写中国式现代化内蒙古新篇章的重要力量。","author":"《内蒙古自治区党委自治区人民政府关于支持民营经济高质量发展的意见》"},{"id":"q-01-0010","t":"要围绕产业链部署创新链、围绕创新链布局产业链，推动经济高质量发展迈出更大步伐。","author":"习近平"},{"id":"q-01-0011","t":"要有序推进产业结构优化升级，加快发展优势产业，着力筑牢产业基础，推动产业链现代化。","author":"习近平"},{"id":"q-01-0012","t":"一手抓传统产业转型升级，一手抓战略性新兴产业发展壮大，推动制造业加速向数字化、网络化、智能化发展，提高产业链供应链稳定性和现代化水平。","author":"习近平"},{"id":"q-01-0013","t":"要围绕产业链部署创新链、围绕创新链布局产业链，前瞻布局战略性新兴产业，培育发展未来产业，发展数字经济。","author":"习近平"},{"id":"q-01-0014","t":"产业链环环相扣，一个环节阻滞，上下游企业都无法运转。","author":"习近平"},{"id":"q-01-0015","t":"为保障我国产业安全和国家安全，要着力打造自主可控、安全可靠的产业链、供应链，力争重要产品和供应渠道都至少有一个替代来源，形成必要的产业备份系统。","author":"习近平"},{"id":"q-01-0016","t":"当前，全球产业体系和产业链供应链呈现多元化布局、区域化合作、绿色化转型、数字化加速的态势，这是经济发展规律和历史大趋势，不以人的意志为转移。我们要继续把发展经济的着力点放在实体经济上，扎实推进新型工业化，加快建设制造强国、质量强国、网络强国、数字中国，打造具有国际竞争力的数字产业集群。顺应产业发展大势，从时空两方面统筹抓好产业升级和产业转移。","author":"习近平"},{"id":"q-01-0017","t":"亚太发展的经验告诉我们，开放则兴，封闭则衰。我们要维护自由开放的贸易投资，支持并加强以世界贸易组织为核心的多边贸易体制，维护全球产业链供应链稳定畅通，反对将经贸问题政治化、武器化、泛安全化。","author":"习近平"},{"id":"q-01-0018","t":"量发展各方面、全过程，一起谋划、一起部署。强化计量、标准、检验检测、认证认可等质量要素协同，构建质量提升生态圈，赋能产业链供应链质量全方位升级。","author":"《关于质量基础设施助力产业链供应链质量联动提升的指导意见》"},{"id":"q-01-0019","t":"坚持把发展经济着力点放在实体经济上，坚定不移建设制造强国、质量强国、网络强国、数字中国，推进产业基础高级化、产业链现代化，提高经济质量效益和核心竞争力。","author":"《中共中央关于制定国民经济和社会发展第十四个五年规划和二〇三五年远景目标的建议》"},{"id":"q-01-0020","t":"当前，互联网、大数据、云计算、人工智能、区块链等新技术深刻演变，产业数字化、智能化、绿色化转型不断加速，智能产业、数字经济蓬勃发展，极大改变全球要素资源配置方式、产业发展模式和人民生活方式。","author":"习近平"},{"id":"q-01-0021","t":"要把发展特色优势产业和战略性新兴产业作为主攻方向，加快改造提升传统产业，前瞻部署未来产业，促进数字经济与实体经济深度融合，构建富有四川特色和优势的现代化产业体系。","author":"习近平"},{"id":"q-01-0022","t":"中国高度重视数字经济发展，持续促进数字技术和实体经济深度融合，协同推进数字产业化和产业数字化，加快建设网络强国、数字中国。","author":"习近平"},{"id":"q-01-0023","t":"要坚持科技创新和产业创新一起抓，加强科创园区建设，促进数字经济与实体经济深度融合，推动制造业高端化、智能化、绿色化发展。","author":"习近平"},{"id":"q-01-0024","t":"要大力发展数字经济，促进数字经济和实体经济深度融合，打造具有国际竞争力的数字产业集群。","author":"习近平"},{"id":"q-01-0025","t":"我们要继续把发展经济的着力点放在实体经济上，扎实推进新型工业化，加快建设制造强国、质量强国、网络强国、数字中国，打造具有国际竞争力的数字产业集群。","author":"习近平"},{"id":"q-01-0026","t":"加快数字中国建设，就是要适应我国发展新的历史方位，全面贯彻新发展理念，以信息化培育新动能，用新动能推动新发展，以新发展创造新辉煌。","author":"习近平"},{"id":"q-01-0027","t":"数字商务是数字经济发展最迅速、创新最活跃、应用最丰富的重要组成，是数字经济在商务领域的具体实践，也是商务各领域数字化发展的实施路径。","author":"《数字商务三年"},{"id":"q-01-0028","t":"数字经济有利于加快生产要素高效流动、推动优质资源共享、推进基本公共服务均等化，是推动实现共同富裕的重要力量。","author":"《数字经济促进共同富裕实施方案》"},{"id":"q-01-0029","t":"强化政策宣传解读，充分利用各类媒体平台、宣传矩阵，大力宣传数字经济促进共同富裕理念和举措、进展和成效，加强政策影响力和号召力，提升各方积极性和参与度。","author":"《数字经济促进共同富裕实施方案》"},{"id":"q-01-0030","t":"推进产业互补，支持协作双方共建数字经济产业园区，推动产业向中西部、东北地区合理有序转移，强化以企业合作为载体的帮扶协作，动员东部企业发挥自身优势，到中西部、东北地区投资兴业。","author":"《数字经济促进共同富裕实施方案》"},{"id":"q-01-0031","t":"必须大力实施扩大内需战略，采取更加有力的措施，使社会再生产实现良性循环。","author":"习近平"},{"id":"q-01-0032","t":"面向未来，我们要把满足国内需求作为发展的出发点和落脚点，加快构建完整的内需体系。","author":"习近平"},{"id":"q-01-0033","t":"坚决贯彻落实扩大内需战略规划纲要，尽快形成完整内需体系，着力扩大有收入支撑的消费需求、有合理回报的投资需求、有本金和债务约束的金融需求。","author":"习近平"},{"id":"q-01-0034","t":"内需是中国经济发展的基本动力，也是满足人民日益增长的美好生活需要的必然要求。","author":"习近平"},{"id":"q-01-0035","t":"要统筹推进扩大内需和优化供给，打通两者结合的断点堵点卡点，发挥超大规模市场和强大生产能力的优势。","author":"习近平"},{"id":"q-01-0036","t":"我们要牢牢把握扩大内需这一战略基点，使生产、分配、流通、消费各环节更多依托国内市场实现良性循环，明确供给侧结构性改革的战略方向，促进总供给和总需求在更高水平上实现动态平衡。","author":"习近平"},{"id":"q-01-0037","t":"必须建立扩大内需的有效制度，加快培育完整内需体系，加强需求侧管理，建设强大国内市场。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-01-0038","t":"使之成为经济发展的重要推动力。","author":"《扩大内需战略规划纲要（2022-2035年）》"},{"id":"q-01-0039","t":"推动城乡区域协调发展是释放内需潜能、促进产业升级的重要举措，坚持全国一盘棋，全面实施乡村振兴战略，坚持实施区域重大战略、区域协调发展战略，增强发展的整体性、协调性，充分释放内需潜在势能。","author":"《扩大内需战略规划纲要（2022-2035年）》"},{"id":"q-01-0040","t":"把安全发展贯穿扩大内需工作各领域和全过程，着力提升粮食、能源和战略性矿产资源等领域供应保障能力，有效维护产业链供应链稳定，不断提高应对突发应急事件能力，为国内市场平稳发展提供坚强安全保障。","author":"《扩大内需战略规划纲要（2022-2035年）》"},{"id":"q-01-0041","t":"完善宏观经济治理，不断创新和完善宏观调控，强化宏观政策对实施扩大内需战略的统筹支持。","author":"《扩大内需战略规划纲要（2022-2035年）》"},{"id":"q-01-0042","t":"要切实解决扶贫农畜牧产品滞销问题，组织好产销对接，开展消费扶贫行动，利用互联网拓宽销售渠道，多渠道解决农产品卖难问题。","author":"习近平"},{"id":"q-01-0043","t":"建立和完善扩大居民消费的长效机制，使居民有稳定收入能消费、没有后顾之忧敢消费、消费环境优获得感强愿消费","author":"习近平"},{"id":"q-01-0044","t":"增强消费对经济发展的基础性作用，顺应消费升级趋势，提升传统消费，培育新型消费，适当增加公共消费。","author":"《中共中央关于制定国民经济和社会发展第十四个五年规划和二〇三五年远景目标的建议》"},{"id":"q-01-0045","t":"推动步行街改造提升，加快城市一刻钟便民生活圈建设，完善县域商业体系，健全城乡服务消费网络，丰富农村生活服务供给，提升服务供给能力和消费能级。","author":"国务院关于促进服务消费高质量发展的意见"},{"id":"q-01-0046","t":"鼓励社区、商场、景点、平台企业设立消费维权服务站，促进消费纠纷源头解决。","author":"国务院关于促进服务消费高质量发展的意见"},{"id":"q-01-0047","t":"制修订服务消费相关标准，完善文化、旅游、餐饮住宿、家政服务、养老托育、家居家装、商务服务等领域标准，研制数字消费、绿色消费、健康消费等新型消费标准。","author":"国务院关于促进服务消费高质量发展的意见"},{"id":"q-01-0048","t":"支持体育健身场所建设，丰富体育消费场景。","author":"《关于促进消费的若干措施》"},{"id":"q-01-0049","t":"集贸市场等商业设施改造升级给予资金补贴。","author":"《关于促进消费的若干措施》"},{"id":"q-01-0050","t":"支持发展便民经济和外摆经济，允许各地因地制宜设置临时性早市、夜市等生活性消费场所，使用具备条件的政府储备土地、空闲地开办临时便民市场。","author":"《关于促进消费的若干措施》"},{"id":"q-01-0051","t":"鼓励各地制作发布消费品以旧换新政策宣传小册子，组织协会、专家、媒体等开展“全国消费品以旧换新万里行”推广活动，加强宣传引导，扩大政策影响力和覆盖面。","author":"《推动消费品以旧换新行动方案》"},{"id":"q-01-0052","t":"只有充分尊重经济规律，发挥市场作用，扫除人为障碍，才能适应生产力发展要求，实现贸易畅通、百业兴旺。","author":"习近平"},{"id":"q-01-0053","t":"市场主体是经济的力量载体，保市场主体就是保社会生产力。","author":"习近平"},{"id":"q-01-0054","t":"持续建设市场化、法治化、国际化一流营商环境，塑造更高水平开放型经济新优势。","author":"习近平"},{"id":"q-01-0055","t":"深化要素市场化改革，完善产权保护、市场准入、公平竞争、社会信用等基础制度，完善跨区域、跨部门、跨层级的数据信息共享和流程互联互通，深化政务服务合作，优化营商环境。","author":"习近平"},{"id":"q-01-0056","t":"完善市场经济基础制度，积极融入全国统一大市场建设，持续推进国资国企改革，认真落实促进民营经济发展政策，优化营商环境，激发社会投资活力。","author":"习近平"},{"id":"q-01-0057","t":"中国将不断完善市场化、法治化、国际化的营商环境，放宽外资市场准入，继续缩减负面清单，完善投资促进和保护、信息报告等制度，完善知识产权保护法律体系。","author":"习近平"},{"id":"q-01-0058","t":"深化简政放权、放管结合、优化服务改革，全面实行政府权责清单制度，持续优化市场化法治化国际化营商环境。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-01-0059","t":"营商环境既是重要软实力，也是核心竞争力。","author":"《工业和信息化部关于创新信息通信行业管理优化营商环境的意见》"},{"id":"q-01-0060","t":"度型开放上迈出更大步伐，促进营商环境深层次改革，探索形成可复制可推广的制度创新成果。","author":"《粤港澳大湾区国际一流营商环境建设三年行动计划》"},{"id":"q-01-0061","t":"坚持互利共赢。注重做好改革系统集成，推动顶层设计和基层探索有机结合，充分发挥区域比较优势，深化粤港澳互利合作，增强发展的整体性协同性，推动粤港澳大湾区营商环境整体提升。","author":"《粤港澳大湾区国际一流营商环境建设三年行动计划》"},{"id":"q-01-0063","t":"制造业高质量发展是我国经济高质量发展的重中之重，建设社会主义现代化强国、发展壮大实体经济，都离不开制造业，要在推动产业优化升级上继续下功夫。","author":"习近平"},{"id":"q-01-0064","t":"深入实施制造业重大技术改造升级和大规模设备更新工程，推动制造业高端化、智能化、绿色化发展，让传统产业焕发新的生机活力。","author":"习近平"},{"id":"q-01-0065","t":"立足实体经济这个根基，做大做强先进制造业，积极推进新型工业化，改造提升传统产业，培育壮大新兴产业，超前布局建设未来产业，加快构建以先进制造业为支撑的现代化产业体系。","author":"习近平"},{"id":"q-01-0066","t":"聚焦优势产业，强化产业基础再造和重大技术装备攻关，继续做大做强先进制造业，推动产业高端化、智能化、绿色化发展，打造国家级产业集群。","author":"习近平"},{"id":"q-01-0067","t":"要以智能制造为主攻方向推动产业技术变革和优化升级，推动制造业产业模式和企业形态根本性转变，以“鼎新”带动“革故”，以增量带动存量，促进我国产业迈向全球价值链中高端。","author":"习近平"},{"id":"q-01-0068","t":"任何一个民族，如果被剥夺了工业，从而沦为单纯是庄稼汉的集合体，那是不能和其他民族在文明上并驾齐驱的。","author":"恩格斯"},{"id":"q-01-0069","t":"机器的生产方式是现代工业最本质的特征。","author":"拉法格"},{"id":"q-01-0070","t":"紧跟现代服务业与制造业深度融合的变革趋势，在绿色低碳领域深入推行服务型制造，构建优质高效的绿色制造服务体系。","author":"《工业和信息化部等七部门关于加快推动制造业绿色化发展的指导意见》"},{"id":"q-01-0071","t":"制造业是国民经济的主体，是立国之本、兴国之器、强国之基。","author":"《中国制造2025》"},{"id":"q-01-0072","t":"要强化企业的创新主体地位，形成一批有自主知识产权和国际竞争力的创新型领军企业。","author":"习近平"},{"id":"q-01-0073","t":"强化企业创新主体地位，构建上下游紧密合作的创新联合体，促进产学研融通创新，加快科技成果向现实生产力转化","author":"习近平"},{"id":"q-01-0074","t":"要深化科技体制改革，发挥新型举国体制优势，强化国家战略科技力量，强化企业科技创新主体地位，优化配置创新资源，努力突破关键核心技术，推动实现高水平科技自立自强","author":"习近平"},{"id":"q-01-0075","t":"有的人说加强企业党建和工会工作是要对民营企业进行控制，等等。这些说法是完全错误的，不符合党的大政方针。","author":"习近平"},{"id":"q-01-0076","t":"小微企业占整个经济的95％，它们的发展将使我们的经济大为改观。我们需要提高这些小微企业的雄心和信心，交给它们增长壮大的工具。","author":"戴维·杨"},{"id":"q-01-0077","t":"未来经济将朝数位化发展，对企业而言最重要的是速度。","author":"比尔·盖茨"},{"id":"q-01-0078","t":"通过中央财政资金引导和带动，深化上下联动、央地协同，增强政策实效性、培育系统性和服务精准性，提升专精特新中小企业补链强链作用，增强产业链配套能力。","author":"《关于进一步支持专精特新中小企业高质量发展的通知》"},{"id":"q-01-0079","t":"支持地方探索对专精特新中小企业培育赋能，不断夯实服务体系。即鼓励地方因地制宜、因企施策，推出针对性强、实用性高、精准有效的培育赋能举措，积极培育专精特新中小企业。","author":"《关于进一步支持专精特新中小企业高质量发展的通知》"},{"id":"q-01-0080","t":"畅通人才向民营企业流动渠道，健全人事管理、档案管理、社会保障等接续的政策机制。","author":"《中共中央国务院关于促进民营经济发展壮大的意见》"},{"id":"q-01-0081","t":"完善促进中小微企业和个体工商户发展的政策体系，加大税费优惠和信贷支持力度。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-01-0082","t":"要按照发展新质生产力要求，畅通教育、科技、人才的良性循环，完善人才培养、引进、使用、合理流动的工作机制。","author":"习近平"},{"id":"q-01-0083","t":"要围绕发展新质生产力布局产业链，提升产业链供应链韧性和安全水平，保证产业体系自主可控、安全可靠。","author":"习近平"},{"id":"q-01-0084","t":"要瞄准世界能源科技前沿，聚焦能源关键领域和重大需求，合理选择技术路线，发挥新型举国体制优势，加强关键核心技术联合攻关，强化科研成果转化运用，把能源技术及其关联产业培育成带动我国产业升级的新增长点，促进新质生产力发展。","author":"习近平"},{"id":"q-01-0085","t":"新质生产力既需要政府超前规划引导、科学政策支持，也需要市场机制调节、企业等微观主体不断创新，是政府“有形之手”和市场“无形之手”共同培育和驱动形成的。","author":"习近平"},{"id":"q-01-0086","t":"强化科技创新和产业创新融合，加大科技成果转化应用力度，促进传统产业转型升级，培育战略性新兴产业，因地制宜发展新质生产力。","author":"习近平"},{"id":"q-01-0087","t":"因地制宜发展新质生产力，改造提升传统产业，培育壮大新兴产业，布局建设未来产业，完善现代化产业体系，努力创造更多高质量就业岗位。","author":"习近平"},{"id":"q-01-0088","t":"深化科技体制、教育体制、人才体制等改革，打通束缚新质生产力发展的堵点卡点。","author":"习近平"},{"id":"q-01-0089","t":"必须加强科技创新特别是原创性、颠覆性科技创新，加快实现高水平科技自立自强，打好关键核心技术攻坚战，使原创性、颠覆性科技创新成果竞相涌现，培育发展新质生产力的新动能。","author":"习近平"},{"id":"q-01-0090","t":"未来产业由前沿技术驱动，当前处于孕育萌发阶段或产业化初期，是具有显著战略性、引领性、颠覆性和不确定性的前瞻性新兴产业。大力发展未来产业，是引领科技进步、带动产业升级、培育新质生产力的战略选择。","author":"《工业和信息化部等七部门关于推动未来产业创新发展的实施意见》"},{"id":"q-01-0091","t":"以“用”为导向搭建科创供应链平台、激活新质生产力核心要素，以供应链体系建设为抓手构建现代化产业体系、夯实新质生产力产业支撑，以深入实施流域综合治理为基础推动绿色低碳转型、擦亮新质生产力鲜明底色，以体制机制创新促进教育科技人才良性循环、塑造新质生产力良好生态。","author":"《湖北省人民政府办公厅关于加快培育新质生产力推动"},{"id":"q-01-0092","t":"坚持和落实“两个毫不动摇”，一手抓深化国企改革、培育一批核心竞争力强的国有企业，一手抓促进民营经济发展壮大、激发各类经营主体活力。","author":"习近平"},{"id":"q-01-0093","t":"我们要求领导干部同民营企业家打交道要守住底线、把好分寸，并不意味着领导干部可以对民营企业家的正当要求置若罔闻，对他们的合法权益不予保护，而是要积极主动为民营企业服务。","author":"习近平"},{"id":"q-01-0094","t":"要不断完善落实“两个毫不动摇”的体制机制，有效破除制约民营企业公平参与市场竞争的障碍，支持民营经济和民营企业发展壮大，激发各类经营主体的内生动力和创新活力。","author":"习近平"},{"id":"q-01-0095","t":"完善落实“两个毫不动摇”的体制机制，支持民营经济和民营企业发展壮大，激发各类经营主体的内生动力和创新活力。","author":"习近平"},{"id":"q-01-0096","t":"有能力、有条件的民营企业要加强自主创新，在推进科技自立自强和科技成果转化中发挥更大作用。","author":"习近平"},{"id":"q-01-0097","t":"促进民营企业发展壮大，在市场准入、要素获取、公平执法、权益保护等方面落实一批举措。","author":"中央经济工作会议"},{"id":"q-01-0098","t":"引导和支持民营经济履行社会责任，展现良好形象，更好与舆论互动，营造正确认识、充分尊重、积极关心民营经济的良好社会氛围。","author":"《中共中央国务院关于促进民营经济发展壮大的意见》"},{"id":"q-01-0099","t":"构建高水平社会主义市场经济体制，持续优化稳定公平透明可预期的发展环境，充分激发民营经济生机活力。","author":"《中共中央国务院关于促进民营经济发展壮大的意见》"},{"id":"q-01-0100","t":"大力推进校企合作、产教融合。推进民营经济产业工人队伍建设，优化职业发展环境。加强灵活就业和新就业形态劳动者权益保障，发挥平台企业在扩大就业方面的作用。","author":"《中共中央国务院关于促进民营经济发展壮大的意见》"},{"id":"q-01-0101","t":"充分发挥民营企业党组织作用，推动企业加强法治教育，营造诚信廉洁的企业文化氛围。","author":"《中共中央国务院关于促进民营经济发展壮大的意见》"},{"id":"q-01-0102","t":"式、调整产业结构、转换增长动力，坚守主业、做强实业，自觉走高质量发展之路。","author":"《中共中央国务院关于促进民营经济发展壮大的意见》"},{"id":"q-01-0103","t":"新业态虽是后来者，但依法规范不要姗姗来迟，要及时跟上研究，把法律短板及时补齐，在变化中不断完善。","author":"习近平"},{"id":"q-01-0104","t":"新时代陕西要有勇立潮头、争当时代弄潮儿的志向和气魄，既要抓住西部大开发、共建“一带一路”等重大机遇，又要善于从眼前的危机和挑战中抢抓和创造机遇，不断发展新模式、新业态、新技术、新产品，创造新的更大业绩，迈上新的台阶。","author":"习近平"},{"id":"q-01-0105","t":"要广泛运用先进科学技术，着力加强科技创新能力建设，加大科技成果转化力度，积极发展新业态、新模式，培育新增长点、形成新动能，把智能、绿色、创新打造成为雄安新区的亮丽名片。","author":"习近平"},{"id":"q-01-0106","t":"国外名言新经济时代，不是大鱼吃小鱼，而是快鱼吃慢鱼。","author":"思科公司总裁钱伯斯"},{"id":"q-01-0107","t":"及时跟进研究数字经济、互联网金融、人工智能、大数据、云计算等相关法律制度，抓紧补齐短板，以良法善治保障新业态新模式健康发展。","author":"中共中央、国务院印发《法治政府建设实施纲要（2021－2025年）》"},{"id":"q-01-0108","t":"引导金融机构优化信贷产品、提供差异化服务，按照风险可控、商业可持续原则，加大对服务消费重点领域信贷支持力度，增加适应共享经济等消费新业态发展需要的金融产品供给。","author":"《国务院关于促进服务消费高质量发展的意见》"},{"id":"q-01-0109","t":"推进商旅文体健融合发展，提升项目体验性、互动性，推出多种类型特色旅游产品，鼓励邮轮游艇、房车露营、低空飞行等新业态发展，支持“音乐+旅游”、“演出+旅游”、“赛事+旅游”等融合业态发展。","author":"《国务院关于促进服务消费高质量发展的意见》"}],"改革创新篇":[{"id":"q-02-0000","t":"更好满足人民高品质生活具有重要意义。","author":"《关于打造消费新场景培育消费新增长点的措施》"},{"id":"q-02-0001","t":"新时代属于每一个人，每一个人都是新时代的见证者、开创者、建设者。","author":"习近平"},{"id":"q-02-0002","t":"古往今来，人类从闭塞走向开放、从隔绝走向融合是不可阻挡的时代潮流。","author":"习近平"},{"id":"q-02-0003","t":"坚持用全面、辩证、长远的眼光分析当前经济形势，努力在危机中育新机、于变局中开新局。","author":"习近平"},{"id":"q-02-0004","t":"我们要顺应时代发展新趋势、实践发展新要求、人民群众新期待，以改革到底的坚强决心，动真格、敢碰硬，精准发力、协同发力、持续发力，坚决破除一切制约中国式现代化顺利推进的体制机制障碍。","author":"习近平"},{"id":"q-02-0005","t":"当前，世界格局在变，发展格局在变，各个政党都要顺应时代发展潮流、把握人类进步大势、顺应人民共同期待，把自身发展同国家、民族、人类的发展紧密结合在一起。","author":"习近平"},{"id":"q-02-0006","t":"只有顺应历史潮流，积极应变，主动求变，才能与时代同行。","author":"习近平"},{"id":"q-02-0007","t":"情况是在不断地变化，要使自己的思想适应新的情况，就得学习。","author":"毛泽东"},{"id":"q-02-0008","t":"识时务者在乎俊杰。","author":"晋·陈寿《三国志·蜀志·诸葛亮传》"},{"id":"q-02-0009","t":"智者顺时而谋，愚者逆时而动。","author":"《后汉书·列传·朱冯虞郑周列传》"},{"id":"q-02-0010","t":"重要的不是环境，而是对环境作出的反应。","author":"鲍勃·康克林"},{"id":"q-02-0011","t":"最高明的处世术不是妥协，而是适应。","author":"吉姆梅尔"},{"id":"q-02-0012","t":"开路，遇水架桥，敢于向顽瘴痼疾开刀，勇于突破利益固化藩篱，将改革进行到底。","author":"习近平"},{"id":"q-02-0013","t":"要深化经济体制、科技体制等改革，着力打通束缚新质生产力发展的堵点卡点，建立高标准市场体系，创新生产要素配置方式，让各类先进优质生产要素向发展新质生产力顺畅流动。","author":"习近平"},{"id":"q-02-0014","t":"进一步全面深化改革要突出问题导向，着力解决制约构建新发展格局和推动高质量发展的卡点堵点问题、发展环境和民生领域的痛点难点问题、有悖社会公平正义的焦点热点问题，有效防范化解重大风险，不断为经济社会发展增动力、添活力。","author":"习近平"},{"id":"q-02-0015","t":"要深化科技体制改革，发挥新型举国体制优势，强化国家战略科技力量，强化企业科技创新主体地位，优化配置创新资源，努力突破关键核心技术，推动实现高水平科技自立自强。","author":"习近平"},{"id":"q-02-0016","t":"深化要素市场化改革，完善市场经济基础制度，全面清理纠正地方保护行为，推动各种生产力要素跨区域合理流动和优化配置，更好参与全国统一大市场建设。","author":"习近平"},{"id":"q-02-0017","t":"要紧扣制约科技与经济深度融合的突出问题，围绕创新要干什么、谁来组织创新、如何支持激励保护创新，持续深化改革攻坚，加快建设全面创新的基础制度。","author":"习近平"},{"id":"q-02-0018","t":"进一步全面深化改革，要紧扣推进中国式现代化这个主题，突出改革重点，把牢价值取向，讲求方式方法，为完成中心任务、实现战略目标增添动力。","author":"习近平"},{"id":"q-02-0019","t":"改革要更加注重系统集成，坚持以全局观念和系统思维谋划推进，加强各项改革举措的协调配套，推动各领域各方面改革举措同向发力、形成合力，增强整体效能，防止和克服各行其是、相互掣肘的现象。","author":"习近平"},{"id":"q-02-0020","t":"改革是社会主义制度的自我完善和发展。","author":"邓小平"},{"id":"q-02-0021","t":"改革是全面的改革，包括经济体制改革、政治体制改革和相应的其他各个领域的改革。","author":"邓小平"},{"id":"q-02-0022","t":"一切事物的趋于完善，都是来自适当的改革。","author":"巴尔扎克"},{"id":"q-02-0023","t":"为政之道就是勇往直前，有进无退。","author":"拿破仑"},{"id":"q-02-0024","t":"要增强企业创新动力，发挥企业出题者作用，加快构建龙头企业牵头、高校院所支撑、各创新主体相互协同的创新联合体，提高科技成果转移转化成效。","author":"习近平"},{"id":"q-02-0025","t":"希望企业在科技创新上再接再厉、勇攀高峰，在支撑先进制造业发展方面迈出新的更大步伐。","author":"习近平"},{"id":"q-02-0026","t":"自主创新是企业的生命，是企业爬坡过坎、发展壮大的根本。","author":"习近平"},{"id":"q-02-0027","t":"要发挥企业技术创新主体作用，推动创新要素向企业集聚，促进产学研深度融合。","author":"习近平"},{"id":"q-02-0028","t":"要进一步激发和弘扬企业家精神，依法保护企业家合法权益，依法保护产权和知识产权，激励企业家干事创业。","author":"习近平"},{"id":"q-02-0029","t":"要发挥企业在技术创新中的主体作用，使企业成为创新要素集成、科技成果转化的生力军，打造科技、教育、产业、金融紧密融合的创新体系。","author":"习近平"},{"id":"q-02-0030","t":"要加强关键核心技术攻关，支持和引导平台企业加大研发投入，加强基础研究，夯实底层技术根基，扶持中小科技企业创新。","author":"习近平"},{"id":"q-02-0031","t":"掌握新技术，要善于学习，更要善于创新。","author":"邓小平"},{"id":"q-02-0032","t":"一些陈旧的、不结合实际的东西，不管那些东西是洋框框，还是土框框，都要大力地把它们打破，大胆地创造新的方法、新的理论，来解决我们的问题。","author":"李四光"},{"id":"q-02-0033","t":"没有创新，就不可能有合理的，尤其是有效的管理。","author":"阿法纳西耶夫"},{"id":"q-02-0034","t":"现在的一切美好事物，无一不是创新的结果。","author":"穆勒"},{"id":"q-02-0035","t":"把科技创新摆到更加突出的位置，深化教育科技人才综合改革，加强科教创新和产业创新融合，加强关键核心技术攻关，加大技术改造和产品升级力度。","author":"习近平"},{"id":"q-02-0036","t":"要持续整治滥发“帽子”、“牌子”之风，让科研人员心无旁骛、潜心钻研，切实减少为报项目、发论文、评奖励、争资源而分心伤神。","author":"习近平"},{"id":"q-02-0037","t":"要坚持“四个面向”，加快实施创新驱动发展战略，推动产学研深度合作，着力强化重大科技创新平台建设，支持顶尖科学家领衔进行原创性、引领性科技攻关，努力突破关键核心技术难题，在重点领域、关键环节实现自主可控。","author":"习近平"},{"id":"q-02-0038","t":"坚持推动教育科技人才良性循环，统筹实施科教兴国战略、人才强国战略、创新驱动发展战略，一体推进教育发展、科技创新、人才培养。","author":"习近平"},{"id":"q-02-0039","t":"科学研究工作，尤其富于创造性的意义，尤其是要依靠自力更生，当然，自力更生并不等于封锁自己。","author":"李四光"},{"id":"q-02-0040","t":"道在日新，艺亦须日新，新者生机也；不新则死。","author":"徐悲鸿"},{"id":"q-02-0041","t":"创新是科学房屋的生命力。","author":"阿西莫夫"},{"id":"q-02-0042","t":"如果学习只在模仿，那么我们就不会有科学，也不会有技术。","author":"高尔基"},{"id":"q-02-0043","t":"放眼全国遴选优势科研团队，充分发挥国家战略科技力量的骨干作用，开展协同攻关；突出企业科技创新主体作用，促进产学研用深度融合；营造良好科技创新环境，充分激发创新活力。","author":"《国家重点研发计划管理暂行办法》"},{"id":"q-02-0044","t":"加强对外资研发中心申请认定高新技术企业的指导和服务，组织开展政策培训，加强政策宣传与引导，鼓励和引导外商投资更多投向科技创新领域。","author":"关于进一步鼓励外商投资设立研发中心的若干措施"},{"id":"q-02-0045","t":"加强基础研究是科技自立自强的必然要求，是我们从未知到已知、从不确定性到确定性的必然选择。","author":"习近平"},{"id":"q-02-0046","t":"基础研究要勇于探索、突出原创，拓展认识自然的边界，开辟新的认知疆域。","author":"习近平"},{"id":"q-02-0047","t":"基础研究是整个科学体系的源头。","author":"习近平"},{"id":"q-02-0048","t":"创造有利于基础研究的良好科研生态，建立健全科学评价体系、激励机制，持续不断坚持下去。","author":"习近平"},{"id":"q-02-0049","t":"鼓励具备条件的高校积极设置基础研究、交叉学科相关学科专业，加强基础学科本科生培养，注重培养学生创新意识和创新能力。","author":"习近平"},{"id":"q-02-0050","t":"今日对基础研究投入的多少，直接决定国家能收获多少“未来”。","author":"王恩多"},{"id":"q-02-0051","t":"对中国基础研究的发展来说，投入是基础，人才是关键，文化是灵魂，制度是保障。","author":"裴钢院士"},{"id":"q-02-0052","t":"支持一批自然资源部高层次科技创新领军人才在自然资源重大基础研究与业务实践的融合中，担当领衔重点攻关任务，培养造就一批基础研究战略科学家。","author":"《关于加强自然资源领域基础研究的若干举措》"},{"id":"q-02-0053","t":"以基础研究重大任务为牵引，实施首席科学家负责制，发挥自然资源各创新平台和人才协同优势，统筹科研院所、高校、应用单位和高科技企业，组建开放、流动、包容、灵活、有弹性的任务协同攻关研究团队，开展有组织体系化的基础研究。","author":"《关于加强自然资源领域基础研究的若干举措》"},{"id":"q-02-0054","t":"遵循基础研究和人才成长规律，构建基础研究和人才培养评价体系，大力培养使用战略科学家，稳定一批在科技前沿最有活力的人，激发青年人才创新活力，提升基础研究人才培养质量，壮大基础研究后备力量。","author":"《关于加快推动北京高校基础研究高质量发展的意见》"},{"id":"q-02-0055","t":"坚持从教育抓起，潜心加强基础科学研究，对数学、物理等重点基础学科给予更多倾斜。","author":"《国务院关于全面加强基础科学研究的若干意见》"},{"id":"q-02-0056","t":"要发挥企业出题者作用，推进重点项目协同和研发活动一体化，加快构建龙头企业牵头、高校院所支撑、各创新主体相互协同的创新联合体，发展高效强大的共性技术供给体系，提高科技成果转移转化成效。","author":"习近平"},{"id":"q-02-0057","t":"科技成果应该造福全人类，而不应该成为限制、遏制其他国家发展的手段。","author":"习近平"},{"id":"q-02-0058","t":"要依托我国超大规模市场和完备产业体系，创造有利于新技术快速大规模应用和迭代升级的独特优势，加速科技成果向现实生产力转化，提升产业链水平，维护产业链安全。","author":"习近平"},{"id":"q-02-0059","t":"阶段整体考核，不再单独进行个案考核。","author":"《专利转化运用专项行动方案（2023—2025年）》"},{"id":"q-02-0060","t":"以供应链思维重构科技与产业供需对接生态，加快建设全国首个以“用”为导向、以需求为牵引、链接全球创新要素的科技创新供应链平台。","author":"《湖北省促进科技成果转化行动方案（2024-2026年）》"},{"id":"q-02-0061","t":"支持高校、科研院所将科技成果许可给中小微企业使用，许可双方可约定采取“零门槛费+阶段性支付+收入提成”或“延期支付”等方式支付许可费，支付时间由双方商定，或由被许可方基于此科技成果形成产品或提供服务产生收入之后支付。","author":"《湖北省促进科技成果转化行动方案（2024-2026年）》"},{"id":"q-02-0062","t":"支持科研事业单位建立成果转化“一张明白纸、一幅流程图、一批服务专员”制度，优化单位内部成果转化审批流程，提供线上或线下的成果转化“一门式”服务，推行成果转化“只进一扇门”、“审批一条龙”、“服务一站式”，全面提升成果转化效率。","author":"《天津市人民政府印发关于进一步推动科技成果转化创新改革若干措施的通知》"},{"id":"q-02-0063","t":"科研事业单位可根据成果转化价值建立梯度赋权或分配机制，将成果转化收益向科研人员倾斜。","author":"《天津市人民政府印发关于进一步推动科技成果转化创新改革若干措施的通知》"},{"id":"q-02-0064","t":"鼓励青年科技人才深入经济社会发展实践，结合实际需求凝练科学问题，开展原始创新、技术攻关、成果转化，把论文写在祖国大地上。","author":"《关于进一步加强青年科技人才培养和使用的若干措施》"},{"id":"q-02-0065","t":"围绕市场需求，打造区域性的成果转化数字平台，汇聚需求、技术、项目、人才、服务等专业数据，加强科技成果信息互联互通，建立成果转化典型案例库，加强多方宣传。","author":"《广州市人民政府办公厅关于印发广州市进一步促进科技成果转移转化若干措施的通知》"},{"id":"q-02-0066","t":"要深化知识产权审判领域改革创新，健全知识产权诉讼制度，完善技术类知识产权审判，抓紧落实知识产权侵权惩罚性赔偿制度。","author":"习近平"},{"id":"q-02-0067","t":"要加强知识产权信息化、智能化基础设施建设，强化人工智能、大数据等信息技术在知识产权审查和保护领域的应用，推动知识产权保护线上线下融合发展。","author":"习近平"},{"id":"q-02-0068","t":"围绕构建高水平社会主义市场经济体制，加快完善产权保护、市场准入、公平竞争、社会信用等市场经济基础制度。","author":"习近平"},{"id":"q-02-0069","t":"要加强产权和知识产权保护，建设高标准市场体系，完善公平竞争制度，激发市场主体发展活力，使一切有利于社会生产力发展的力量源泉充分涌流。","author":"习近平"},{"id":"q-02-0070","t":"知识产权保护工作关系国家治理体系和治理能力现代化，关系高质量发展，关系人民生活幸福，关系国家对外开放大局，关系国家安全。","author":"习近平"},{"id":"q-02-0071","t":"各级党委和政府要落实责任，强化知识产权工作相关协调机制，重视知识产权人才队伍建设，形成工作合力，坚决打击假冒侵权行为，坚决克服地方保护主义。","author":"习近平"},{"id":"q-02-0072","t":"设立知识产权制度的目的是保护和激励创新，而不是制造甚至扩大科技鸿沟。","author":"习近平"},{"id":"q-02-0073","t":"中国将保护外资企业合法权益，坚决依法惩处侵犯外商合法权益特别是侵犯知识产权行为，提高知识产权审查质量和审查效率，引入惩罚性赔偿制度，显著提高违法成本。","author":"习近平"},{"id":"q-02-0074","t":"建设知识产权保护体系是一项系统工程，要从知识产权保护全链条、全过程、全要素出发。","author":"《知识产权保护体系建设工程实施方案》"},{"id":"q-02-0075","t":"加强人工智能、基因技术、网络直播等知识产权保护规则研究。继续推动构建数据知识产权保护规则。","author":"《知识产权保护体系建设工程实施方案》"},{"id":"q-02-0076","t":"加强知识产权纠纷调解组织建设，研究制定知识产权纠纷调解员管理办法，提高调解员管理和培训标准化水平。","author":"《知识产权保护体系建设工程实施方案》"},{"id":"q-02-0077","t":"要坚持马克思主义立场、观点、方法，坚持从国情出发，充分反映实际情况，透过现象看本质，树立国际视野，使理论和政策创新充分体现先进性和科学性。","author":"习近平"},{"id":"q-02-0078","t":"中国式现代化为党的理论创新开辟了广阔前景，提出了新的更加艰巨繁重的任务。","author":"习近平"},{"id":"q-02-0079","t":"广大党员干部特别是各级领导干部要以科学的态度对待科学、以真理的精神追求真理，增强坚持真理的勇气、探索真理的劲头，开动脑筋、勤于思考，积极提出真知灼见，为党的理论创新贡献智慧和力量。","author":"习近平"},{"id":"q-02-0080","t":"我们要强化问题意识、时代意识、战略意识，用深邃的历史眼光、宽广的国际视野把握事物发展的本质和内在联系，紧密跟踪亿万人民的创造性实践，借鉴吸收人类一切优秀文明成果，不断回答时代和实践给我们提出的新的重大课题，让当代中国马克思主义放射出更加灿烂的真理光芒。","author":"习近平"},{"id":"q-02-0081","t":"我们党之所以能够历经考验磨难无往而不胜，关键就在于不断进行实践创新和理论创新。","author":"习近平"},{"id":"q-02-0082","t":"俗语训言指导我们思想的理论基础是马克思列宁主义。","author":"毛泽东"},{"id":"q-02-0083","t":"理论在变为实践，理论由实践赋予活力，由实践来修正，由实践来检验。","author":"列宁"},{"id":"q-02-0084","t":"理论在一个国家的实践程度，决定于理论满足于这个国家的需要的程度。","author":"马克思"},{"id":"q-02-0085","t":"一个民族要想登上科学的高峰，究竟是不能离开理论思维的。","author":"恩格斯"},{"id":"q-02-0086","t":"实践没有止境，理论创新也没有止境。","author":"中国共产党第二十次全国代表大会"},{"id":"q-02-0087","t":"继续推进实践基础上的理论创新，首先要把握好新时代中国特色社会主义思想的世界观和方法论，坚持好、运用好贯穿其中的立场观点方法。","author":"中国共产党第二十次全国代表大会"},{"id":"q-02-0088","t":"坚持走中国特色自主创新道路，立足自力更生、艰苦奋斗，发挥我国社会主义制度集中力量办大事的优势，推进高水平科技自立自强，把科技命脉和发展主动权牢牢掌握在自己手中。","author":"习近平"},{"id":"q-02-0089","t":"有能力、有条件的民营企业要加强自主创新，在推进科技自立自强和科技成果转化中发挥更大作用。","author":"习近平"},{"id":"q-02-0090","t":"要增强创新自信，坚持以我为主，从实际出发，大力推进自主创新、原始创新，打造新质生产力和新质战斗力增长极。","author":"习近平"},{"id":"q-02-0091","t":"的局面。","author":"习近平"},{"id":"q-02-0092","t":"创新是引领发展的第一动力，是国家综合国力和核心竞争力的最关键因素。重大科技创新成果是国之重器、国之利器，必须牢牢掌握在自己手上，必须依靠自力更生、自主创新。","author":"习近平"},{"id":"q-02-0093","t":"矢志不移自主创新，坚定创新信心，着力增强自主创新能力。只有自信的国家和民族，才能在通往未来的道路上行稳致远。","author":"习近平"},{"id":"q-02-0094","t":"树高叶茂，系于根深。自力更生是中华民族自立于世界民族之林的奋斗基点，自主创新是我们攀登世界科技高峰的必由之路。","author":"习近平"},{"id":"q-02-0095","t":"俗语训言自立自重，不可跟人脚迹，学人言语。","author":"陆九渊"},{"id":"q-02-0096","t":"加快武器装备现代化，聚力国防科技自主创新、原始创新，加速战略性前沿性颠覆性技术发展，加速武器装备升级换代和智能化武器装备发展。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-02-0097","t":"强化国家自主创新示范区、高新技术产业开发区、经济技术开发区等创新功能。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-02-0098","t":"我们要坚持德才兼备、以德为先、任人唯贤，着力培养忠诚干净担当的高素质干部队伍和宏大的人才队伍。","author":"习近平"},{"id":"q-02-0099","t":"人才是实现民族振兴、赢得国际竞争主动的战略资源。","author":"《习近平新时代中国特色社会主义思想学习纲要》"},{"id":"q-02-0100","t":"人才培养，关键在教师。广大教师要牢记为党育人、为国育才的初心使命，以人民教育家为榜样，以德立身、以德立学、以德施教。","author":"习近平"},{"id":"q-02-0101","t":"要根据科技发展新趋势，优化高等学校学科设置、人才培养模式，为发展新质生产力、推动高质量发展培养急需人才。","author":"习近平"},{"id":"q-02-0102","t":"要树立强烈的人才意识，寻觅人才求贤若渴，发现人才如获至宝，举荐人才不拘一格，使用人才各尽其能。","author":"习近平"},{"id":"q-02-0103","t":"治国经邦，人才为急。","author":"孙中山《上李鸿章书》"},{"id":"q-02-0104","t":"用人者，取人之长，辟人之短；教人者，成人之长，去人之短也。","author":"清·魏源《默觚下·治篇七》"},{"id":"q-02-0105","t":"凡南面之大务，莫急于知贤；知贤之近途，莫急于考功。功诚考则治乱暴而明，善恶信则直贤不得见障蔽，而佞巧不得窜其奸矣。","author":"汉·王符《潜夫论·考绩》"},{"id":"q-02-0106","t":"盖有非常之功，必待非常之人。","author":"汉·刘彻《武帝求茂才异等诏》"},{"id":"q-02-0107","t":"我劝天公重抖擞，不拘一格降人才。","author":"清·龚自珍《己亥杂诗·其一二五》"},{"id":"q-02-0108","t":"新发展理念是一个系统的理论体系，回答了关于发展的目的、动力、方式、路径等一系列理论和实践问题，阐明了我们党关于发展的政治立场、价值导向、发展模式、发展道路等重大政治问题，全党必须完整、准确、全面贯彻新发展理念。","author":"习近平"},{"id":"q-02-0109","t":"新发展理念是一个整体，无论是中央层面还是部门层面，无论是省级层面还是省以下各级层面，在贯彻落实中都要完整把握、准确理解、全面落实，把新发展理念贯彻到经济社会发展全过程和各领域。","author":"习近平"},{"id":"q-02-0110","t":"各部门既要按照自身职责抓好新发展理念涉及本部门的重点工作，也要综合考虑本部门工作对全党全国贯彻新发展理念的作用和影响，不能单打一，只管自己的一亩三分地。","author":"习近平"},{"id":"q-02-0111","t":"进入新发展阶段，完整、准确、全面贯彻新发展理念，必须更加注重共同富裕问题。","author":"习近平"},{"id":"q-02-0112","t":"完整、准确、全面贯彻新发展理念，既要以新发展理念指导引领全面深化改革，又要通过深化改革为完整、准确、全面贯彻新发展理念提供体制机制保障。","author":"习近平"},{"id":"q-02-0113","t":"完整、准确、全面贯彻新发展理念，必须坚持系统观念。","author":"习近平"},{"id":"q-02-0114","t":"完整、准确、全面贯彻新发展理念，是经济社会发展的工作要求，也是十分重要的政治要求。","author":"习近平"},{"id":"q-02-0115","t":"必须把坚持高质量发展作为新时代的硬道理，完整、准确、全面贯彻新发展理念，推动经济实现质的有效提升和量的合理增长。","author":"中央经济工作会议"},{"id":"q-02-0116","t":"动高质量发展激励约束机制，塑造发展新动能新优势。","author":"中国共产党第二十届中央委员会第三次全体会议"}],"三农发展篇":[{"id":"q-03-0000","t":"我们要增强问题意识，聚焦实践遇到的新问题、改革发展稳定存在的深层次问题、人民群众急难愁盼问题、国际变局中的重大问题、党的建设面临的突出问题，不断提出真正解决问题的新理念新思路新办法。","author":"中国共产党第二十次全国代表大会"},{"id":"q-03-0001","t":"没有农业农村现代化，就没有整个国家的现代化。","author":"习近平"},{"id":"q-03-0002","t":"要强化科技和改革双轮驱动，加大核心技术攻关力度，改革完善‘三农’工作体制机制，为农业现代化增动力、添活力。","author":"习近平"},{"id":"q-03-0003","t":"要坚持农业现代化和农村现代化一体设计、一体推进，推进公共服务向乡村延伸。","author":"习近平"},{"id":"q-03-0004","t":"坚持产业兴农、质量兴农、绿色兴农，加快构建粮经饲统筹、农林牧渔并举、产加销贯通、农文旅融合的现代乡村产业体系，把农业建成现代化大产业。","author":"习近平"},{"id":"q-03-0005","t":"全面建设社会主义现代化国家，既要有城市现代化，也要有农业农村现代化。","author":"习近平"},{"id":"q-03-0006","t":"农业现代化，种子是基础。","author":"李强"},{"id":"q-03-0007","t":"农，天下之大本。","author":"王祯"},{"id":"q-03-0008","t":"农业生产是我们经济建设工作的第一位。","author":"毛泽东"},{"id":"q-03-0009","t":"当前，我国已迈上全面建设社会主义现代化国家新征程，经济发展和城乡居民消费加快升级，食物消费需求日益多元，发展现代设施农业任务紧迫、意义重大。","author":"《全国现代设施农业建设规划（2023—2030年）》"},{"id":"q-03-0010","t":"推进农业现代化助力农业强国建设的现实需要。","author":"《全国现代设施农业建设规划（2023—2030年）》"},{"id":"q-03-0011","t":"要加快建设现代设施农业，促进设施农业集约化、标准化、机械化、绿色化、数字化发展，以基础设施现代化促进农业农村现代化，夯实农业强国建设基础。","author":"《全国现"},{"id":"q-03-0012","t":"实施乡村振兴战略不能光看农民口袋里票子有多少，更要看农民精神风貌怎么样。","author":"习近平"},{"id":"q-03-0013","t":"全面实施乡村振兴战略的深度、广度、难度都不亚于脱贫攻坚，要完善政策体系、工作体系、制度体系，以更有力的举措、汇聚更强大的力量，加快农业农村现代化步伐，促进农业高质高效、乡村宜居宜业、农民富裕富足。","author":"习近平"},{"id":"q-03-0014","t":"要坚持乡村全面振兴，抓重点、补短板、强弱项，实现乡村产业振兴、人才振兴、文化振兴、生态振兴、组织振兴，推动农业全面升级、农村全面进步、农民全面发展。","author":"习近平"},{"id":"q-03-0015","t":"乡村振兴不是坐享其成，等不来、也送不来，要靠广大农民奋斗。村党支部要成为帮助农民致富、维护农村稳定、推进乡村振兴的坚强战斗堡垒。","author":"习近平"},{"id":"q-03-0016","t":"乡村振兴，人才是关键。要积极培养本土人才，鼓励外出能人返乡创业，鼓励大学生村官扎根基层，为乡村振兴提供人才保障。","author":"习近平"},{"id":"q-03-0017","t":"要在推动乡村全面振兴上下更大功夫，推动乡村经济、乡村法治、乡村文化、乡村治理、乡村生态、乡村党建全面强起来，让乡亲们的生活芝麻开花节节高。","author":"习近平"},{"id":"q-03-0018","t":"要保障国家粮食安全，提高农业质量效益和竞争力，实施乡村建设行动，深化农村改革，实现巩固拓展脱贫攻坚成果同乡村振兴有效衔接。","author":"习近平"},{"id":"q-03-0019","t":"要推动城乡融合发展，推动乡村产业、人才、文化、生态、组织等全面振兴。","author":"习近平"},{"id":"q-03-0020","t":"加快推进种业振兴行动，完善联合研发和应用协作机制，加大种源关键核心技术攻关，加快选育推广生产急需的自主优良品种。","author":"《中共中央国务院关于学习运用“千村示范、万村整治”工程经验有力有效推进乡村全面振兴的意见》"},{"id":"q-03-0021","t":"实施乡村振兴人才支持计划，加大乡村本土人才培养，有序引导城市各类专业技术人才下乡服务，全面提高农民综合素质。","author":"《中共中央国务院关于学习运用“千村示范、万村整治”工程经验有力有效推进乡村全面振兴的意见》"},{"id":"q-03-0022","t":"要用好现代信息技术，创新乡村治理方式，提高乡村善治水平。","author":"习近平"},{"id":"q-03-0023","t":"当今世界，信息化发展很快，不进则退，慢进亦退。","author":"习近平"},{"id":"q-03-0024","t":"网信事业代表着新的生产力和新的发展方向。","author":"习近平"},{"id":"q-03-0025","t":"从社会发展史看，人类经历了农业革命、工业革命，正在经历信息革命。信息革命增强了人类脑力，带来生产力又一次质的飞跃。","author":"习近平"},{"id":"q-03-0026","t":"数字产业化滞后，数据整合共享不充分、开发利用不足，数字经济在农业中的占比远低于工业和服务业，成为数字中国建设的突出短板。","author":"《数字农业农村发展规划（2019—2025年）》"},{"id":"q-03-0027","t":"强化确保粮食安全数字化支撑。运用卫星遥感等现代信息技术，统筹开展全国耕地和永久基本农田“非农化”动态监测。","author":"《2024年数字乡村发展工作要点》"},{"id":"q-03-0028","t":"依托“万企兴万村”行动，引导民营企业参与并支持脱贫地区数字乡村建设。鼓励和引导直播平台和机构为脱贫地区、民族地区提供直播人才培训和流量扶持。","author":"《2024年数字乡村发展工作要点》"},{"id":"q-03-0029","t":"提升农业全产业链数字化水平。持续推进国家智慧农业项目建设，带动重点区域、重点品种产业数字化转型。","author":"《2024年数字乡村发展工作要点》"},{"id":"q-03-0030","t":"实施农民增收促进行动，利用数字技术促进乡村富民产业提质增效，完善联农带农益农机制，让农民更多分享产业增值收益。","author":"《2024年数字乡村发展工作要点》"},{"id":"q-03-0031","t":"实施国家文化数字化战略，依托中华优秀传统文化传承发展工程，加强乡村优秀传统文化保护传承和创新发展。","author":"《2024年数字乡村发展工作要点》"},{"id":"q-03-0032","t":"进一步改善农村基础设施，加强乡村环境整治，推进农业适度规模经营，促进一二三产业融合发展。","author":"习近平"},{"id":"q-03-0033","t":"实施乡村文旅深度融合工程，推进乡村旅游集聚区（村）建设，培育生态旅游、森林康养、休闲露营等新业态，推进乡村民宿规范发展、提升品质。","author":"习近平"},{"id":"q-03-0034","t":"把孩子教育培养好。","author":"习近平"},{"id":"q-03-0035","t":"要发展优势特色产业，发展适度规模经营，促进农牧业产业化、品牌化，并同发展文化旅游、乡村旅游结合起来，增加农牧民收入。","author":"习近平"},{"id":"q-03-0036","t":"要积极推进以县城为重要载体的新型城镇化建设，加快构建现代乡村产业体系，发展新型农村集体经济，深入实施乡村建设行动，促进共同富裕。","author":"习近平"},{"id":"q-03-0037","t":"发展县域经济，推动农村一二三产业融合发展，丰富乡村经济业态，拓展农民增收空间。","author":"《中共中央关于制定国民经济和社会发展第十四个五年规划和二〇三五年远景目标的建议》"},{"id":"q-03-0038","t":"产业兴旺是乡村振兴的重点，是解决农村一切问题的前提。","author":"《全国乡村产业发展规划（2020－2025年）》"},{"id":"q-03-0039","t":"乡村产业内涵丰富、类型多样，农产品加工业提升农业价值，乡村特色产业拓宽产业门类，休闲农业拓展农业功能，乡村新型服务业丰富业态类型，是提升农业、繁荣农村、富裕农民的产业。","author":"《全国乡村产业发展规划（2020－2025年）》"},{"id":"q-03-0040","t":"发展乡村产业，将现代工业标准理念和服务业人本理念引入农业农村，推进农业规模化、标准化、集约化，纵向延长产业链条，横向拓展产业形态，助力农业强、农村美、农民富。","author":"《全国乡村产业发展规划（2020－2025年）》"},{"id":"q-03-0041","t":"坚持立农为农。以农业农村资源为依托，发展优势明显、特色鲜明的乡村产业。把二三产业留在乡村，把就业创业机会和产业链增值收益更多留给农民。","author":"《全国乡村产业发展规划（2020－2025年）》"},{"id":"q-03-0042","t":"要巩固拓展脱贫攻坚成果，拓宽共同富裕路径，推动农业增效益、农民增收入、农村增活力。","author":"习近平"},{"id":"q-03-0043","t":"要确保不发生规模性返贫，抓好防止返贫监测，落实帮扶措施，增强内生动力，持续巩固拓展脱贫攻坚成果。","author":"习近平"},{"id":"q-03-0044","t":"要坚决守住脱贫攻坚成果，做好巩固拓展脱贫攻坚成果同乡村振兴有效衔接，工作不留空档，政策不留空白。","author":"习近平"},{"id":"q-03-0045","t":"文章，推动乡村产业、人才、文化、生态、组织等全面振兴。","author":"习近平"},{"id":"q-03-0046","t":"要在巩固脱贫成果方面下更大功夫、想更多办法、给予更多后续帮扶支持，同乡村振兴有效衔接，尤其是同日常生活息息相关的交通设施、就医就学、养老社保等要全覆盖。","author":"习近平"},{"id":"q-03-0047","t":"要健全防止返贫监测帮扶机制，继续对脱贫县、脱贫村、脱贫人口开展监测，持续跟踪收入变化和“两不愁三保障”巩固情况，定期核查，及时发现，及时帮扶，动态清零。","author":"习近平"},{"id":"q-03-0048","t":"支持脱贫地区培育绿色食品、有机农产品、地理标志农产品，打造区域公用品牌。继续大力实施消费帮扶。","author":"《中共中央国务院关于实现巩固拓展脱贫攻坚成果同乡村振兴有效衔接的意见》"},{"id":"q-03-0049","t":"打赢脱贫攻坚战、全面建成小康社会后，要进一步巩固拓展脱贫攻坚成果，接续推动脱贫地区发展和乡村全面振兴。","author":"《中共中央国务院关于实现巩固拓展脱贫攻坚成果同乡村振兴有效衔接的意见》"},{"id":"q-03-0050","t":"摘帽不摘责任，防止松劲懈怠；摘帽不摘政策，防止急刹车；摘帽不摘帮扶，防止一撤了之；摘帽不摘监管，防止贫困反弹。","author":"《中共中央国务院关于实现巩固拓展脱贫攻坚成果同乡村振兴有效衔接的意见》"},{"id":"q-03-0051","t":"就业是巩固拓展脱贫攻坚成果的基本措施。","author":"《人力资源社会保障部国家发展改革委农业农村部关于开展防止返贫就业攻坚行动的通知》"},{"id":"q-03-0052","t":"要完善东西部结对帮扶关系，拓展帮扶领域，健全帮扶机制，优化帮扶方式，加强产业合作、资源互补、劳务对接、人才交流，动员全社会参与，形成区域协调发展、协同发展、共同发展的良好局面。","author":"习近平"},{"id":"q-03-0053","t":"要坚持把强化区域协同融通作为着力点，沿江省市要坚持省际共商、生态共治、全域共建、发展共享，增强区域交通互联性、政策统一性、规则一致性、执行协同性，稳步推进生态共同体和利益共同体建设，促进区域协调发展。","author":"习近平"},{"id":"q-03-0054","t":"东北是我国向北开放的重要门户，在我国加强东北亚区域合作、联通国内国际双循环中的战略地位和作用日益凸显。","author":"习近平"},{"id":"q-03-0055","t":"深化要素市场化改革，完善市场经济基础制度，全面清理纠正地方保护行为，推动各种生产力要素跨区域合理流动和优化配置，更好参与全国统一大市场建设。","author":"习近平"},{"id":"q-03-0056","t":"建立健全城乡要素平等交换、双向流动政策体系，促进要素更多向乡村流动，增强农业农村发展活力。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-03-0057","t":"完善城乡融合消费网络，扩大电子商务进农村覆盖面，改善县域消费环境，推动农村消费梯次升级。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-03-0058","t":"拓展多种形式的跨区域产业合作。支持非对口帮扶协作关系的珠三角与粤东粤西粤北各市创新跨区域产业合作模式，按照协商自愿、共建共享的原则，建立市、县和园区等多层次共建关系，引导更多珠三角地区产业向粤东粤西粤北地区转移。","author":"中共广东省委、广东省人民政府印发《关于推动产业有序转移促进区域协调发展的若干措施》"},{"id":"q-03-0059","t":"充分发挥“一带一部”优势，以中部地区崛起和长江经济带发展战略实施为引领，积极对接“一带一路”建设、粤港澳大湾区建设、长江三角洲区域一体化发展和京津冀协同发展，推进重点区域加快发展。","author":"《湖南省人民政府办公厅印发〈关于建立更加有效的区域协调发展新机制的实施方案〉的通知》"},{"id":"q-03-0060","t":"促进资本跨区域有序自由流动，支持和推动中小微企业通过区域性股权市场登记托管、挂牌融资。","author":"《湖南省人民政府办公厅印发〈关于建立更加有效的区域协调发展新机制的实施方案〉的通知》"},{"id":"q-03-0061","t":"实行差别化的区域政策。提高区域政策的精准性和有效性，因地制宜培育和激发区域发展动能。","author":"《湖南省人民政府办公厅印发〈关于建立更加有效的区域协调发展新机制的实施方案〉的通知》"},{"id":"q-03-0062","t":"发展现代特色农业和文化旅游业，必须贯彻以人民为中心的发展思想，突出农民主体地位，把保障农民利益放在第一位。","author":"习近平"},{"id":"q-03-0063","t":"要充分尊重广大农民意愿，调动广大农民积极性、主动性、创造性，把广大农民对美好生活的向往化为推动乡村振兴的动力。","author":"习近平"},{"id":"q-03-0064","t":"一定要突出农民主体地位，始终把保障农民利益放在第一位。","author":"习近平"},{"id":"q-03-0065","t":"我们党成立以后，充分认识到中国革命的基本问题是农民问题，把为广大农民谋幸福作为重要使命。","author":"习近平"},{"id":"q-03-0066","t":"中国要强，农业必须强；中国要美，农村必须美；中国要富，农民必须富。","author":"习近平"},{"id":"q-03-0067","t":"民惟邦本，本固邦宁。","author":"《尚书·五子之歌》"},{"id":"q-03-0068","t":"农，天下之本，务莫大焉。","author":"西汉·司马迁《史记》"},{"id":"q-03-0069","t":"农者，所以根国家也。","author":"西汉·司马迁《史记》"},{"id":"q-03-0070","t":"完善利益联结机制，通过“资源变资产、资金变股金、农民变股东”，让农民更多分享产业增值收益。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-03-0071","t":"从各地实际和农民需求出发，抓住普及普惠的事，干一件、成一件。","author":"《中共中央国务院关于学习运用“千村示范、万村整治”工程经验有力有效推进乡村全面振兴的意见》"},{"id":"q-03-0072","t":"阅读是人类获取知识、启智增慧、培养道德的重要途径，可以让人得到思想启发，树立崇高理想，涵养浩然之气。","author":"习近平"},{"id":"q-03-0073","t":"希望全社会都参与到阅读中来，形成爱读书、读好书、善读书的浓厚氛围。","author":"习近平"},{"id":"q-03-0074","t":"中华民族自古提倡阅读，讲究格物致知、诚意正心，传承中华民族生生不息的精神，塑造中国人民自信自强的品格。","author":"习近平"},{"id":"q-03-0075","t":"各村（社区）、镇文服中心广泛开展广大群众喜闻乐见、鲜活生动、积极参与的阅读推广活动，提供全民阅读服务，培养人民群众阅读习惯。","author":"重庆市垫江县太平镇《2024年太平镇全民阅读月活动实施方案》"},{"id":"q-03-0076","t":"促进全民阅读，是赓续中华文脉、建设中华民族现代文明的重要举措。","author":"宁夏"},{"id":"q-03-0077","t":"送书进校园系列阅读活动。依托书刊资源、品牌活动，精准对接幼儿园、小学生阅读需求，通过送书进校园，延伸图书馆阅读服务触角。","author":"宁夏回族自治区银川市永宁县《永宁县2024年全民阅读推广活动方案》"},{"id":"q-03-0078","t":"吸引更多的群众走进图书馆，体验阅读的魅力，享受文化的滋养。","author":"宁夏回族自治区银川市永宁县《永宁县2024年全民阅读推广活动方案》"},{"id":"q-03-0079","t":"农业的出路在现代化，农业现代化的关键在科技进步和创新。","author":"习近平"},{"id":"q-03-0080","t":"我们对袁隆平同志的最好纪念，就是学习他热爱党、热爱祖国、热爱人民，信念坚定、矢志不渝，勇于创新、朴实无华的高贵品质，学习他以祖国和人民需要为己任，以奉献祖国和人民为目标，一辈子躬耕田野，脚踏实地把科技论文写在祖国大地上的崇高风范。","author":"习近平"},{"id":"q-03-0081","t":"地方特色产业发展潜力巨大，要善于挖掘和利用本地优势资源，加强地方优质品种保护，推进产学研有机结合，统筹做好产业、科技、文化这篇大文章。","author":"习近平"},{"id":"q-03-0082","t":"保证粮食安全必须把种子牢牢攥在自己手中。要坚持农业科技自立自强，从培育好种子做起，加强良种技术攻关，靠中国种子来保障中国粮食安全。","author":"习近平"},{"id":"q-03-0083","t":"要加强高标准农田、农田水利、农业机械化等现代农业基础设施建设，提升农业科技创新水平并加快推广使用，增强粮食生产能力和防灾减灾能力。","author":"习近平"},{"id":"q-03-0084","t":"种源安全关系到国家安全，必须下决心把我国种业搞上去，实现种业科技自立自强、种源自主可控。","author":"习近平"},{"id":"q-03-0085","t":"农业的根本出路在于机械化。","author":"毛泽东"},{"id":"q-03-0086","t":"工业支援农业，促进农业现代化，是工业的重大任务。","author":"邓小平"},{"id":"q-03-0087","t":"集聚创新资源，培育农业农村发展新动能，着力拓展农村创新创业、成果展示示范、成果转化推广和职业农民培训的功能。强化创新链，支撑产业链，激活人才链，提升价值链，分享利益链，努力推动园区成为农业创新驱动发展先行区、农业供给侧结构性改革试验区和农业高新技术产业集聚区，打造中国特色农业自主创新的示范区。","author":"《国家农业科"},{"id":"q-03-0088","t":"完善新时代中国特色农业农村科技创新体系，强化国家农业战略科技力量建设，优化国际农业科技合作发展格局。","author":"《“十四五”全国农业农村科技发展规划》"},{"id":"q-03-0089","t":"重点支持“从0到1”的农业原创性基础研究和应用基础研究，鼓励“无人区”领域的探索研究，掌握更多通用性、不可替代、自主可控核心专利，提供农业科技创新源头支持。","author":"《“十四五”全国农业农村科技发展规划》"},{"id":"q-03-0091","t":"中国现代化离不开农业农村现代化，农业农村现代化关键在科技、在人才。","author":"习近平"},{"id":"q-03-0092","t":"要推动乡村人才振兴，把人力资本开发放在首要位置，强化乡村振兴人才支撑。","author":"习近平"},{"id":"q-03-0093","t":"将来还要引进职业农民，让大学生甚至是海归人才主动回乡务农，使得农业成为有奔头的产业。","author":"习近平"},{"id":"q-03-0095","t":"要让愿意留在乡村、建设家乡的人留得安心，让愿意上山下乡、回报乡村的人更有信心，激励各类人才在农村广阔天地大施所能、大展才华、大显身手。","author":"习近平"},{"id":"q-03-0096","t":"发展是第一要务，人才是第一资源，创新是第一动力。","author":"习近平"},{"id":"q-03-0097","t":"实施农村实用人才培养计划，加强培训基地建设，培养造就一批能够引领一方、带动一片的农村实用人才带头人。","author":"《关于加快推进乡村人才振兴的意见》"},{"id":"q-03-0098","t":"壮大新一代乡村企业家队伍，通过专题培训、实践锻炼、学习交流等方式，完善乡村企业家培训体系，完善涉农企业人才激励机制，加强对乡村企业家合法权益的保护。","author":"《关于加快推进乡村人才振兴的意见》"},{"id":"q-03-0099","t":"依托现代农业产业技术体系、农业科技创新联盟、现代农业产业科技创新中心等平台，发现人才、培育人才、凝聚人才。加强农业企业科技人才培养。","author":"《关于加快推进"},{"id":"q-03-0100","t":"要坚持依法治国、依法执政、依法行政共同推进，法治国家、法治政府、法治社会一体建设。","author":"习近平"},{"id":"q-03-0101","t":"法治建设需要全社会共同参与，只有全体人民信仰法治、厉行法治，国家和社会生活才能真正实现在法治轨道上运行。","author":"习近平"},{"id":"q-03-0102","t":"法令者，民之命也，为治之本也。","author":"商鞅《商君书·定分》"},{"id":"q-03-0103","t":"立善法于天下，则天下治；立善法于一国，则一国治。","author":"北宋·王安石《周公》"},{"id":"q-03-0104","t":"道私者乱，道法者治。","author":"《韩非子·诡使》"},{"id":"q-03-0105","t":"盖天下之事，不难于立法，而难于法之必行。","author":"明·张居正《请稽查章奏随事考成以修实政疏》"},{"id":"q-03-0106","t":"法者，治之端也。","author":"《荀子·君道篇第十二》"},{"id":"q-03-0107","t":"发挥好各类基层普法阵地的作用，结合乡村法治建设实践，把习近平法治思想讲准讲活讲透，推进习近平法治思想进村入户、深入人心、走深走实。","author":"《司法部办公厅农业农村部办公厅关于常态化开展“乡村振兴法治同行”活动的通知》"},{"id":"q-03-0108","t":"加强农村法治宣传教育基地建设，充分利用基层综合性法治文化服务设施和各类职业院校、具备普法功能的单位机构等，因地制宜搭建农民学法用法平台。","author":"《司法部办公厅农业农村部办公厅关于常态化开展“乡村振兴法治同行”活动的通知》"},{"id":"q-03-0109","t":"加强农业综合行政执法人才队伍建设，加大执法人员培训力度，完善工资待遇和职业保障政策，培养通专结合、一专多能执法人才。","author":"《关于加快推进乡村人才振兴的意见》"}],"社会治理篇":[{"id":"q-04-0000","t":"推动公共法律服务力量下沉，通过招录、聘用、政府购买服务、发展志愿者队伍等方式，充实乡镇司法所公共法律服务人才队伍，加强乡村法律服务人才培训。","author":"《关于加快推进乡村人才振兴的意见》"},{"id":"q-04-0001","t":"要加强宪法理论研究和宣传教育，坚持知识普及、理论阐释、观念引导全面发力，在全社会大力弘扬宪法精神、社会主义法治精神，推动宪法实施成为全体人民的自觉行动。","author":"习近平"},{"id":"q-04-0002","t":"要保障和促进社会公平正义，维护国家法治统一，全面推进科学立法、严格执法、公正司法、全民守法，深化司法体制综合配套改革，全面准确落实司法责任制。","author":"习近平"},{"id":"q-04-0003","t":"要贯彻新时代中国特色社会主义法治思想，坚持宪法规定、宪法原则、宪法精神全面贯彻，坚持宪法实施、宪法解释、宪法监督系统推进，加快完善以宪法为核心的中国特色社会主义法律体系，不断提高宪法实施和监督水平。","author":"习近平"},{"id":"q-04-0004","t":"法治建设既要抓末端、治已病，更要抓前端、治未病。","author":"习近平"},{"id":"q-04-0005","t":"法治国家、法治政府、法治社会相辅相成，法治国家是法治建设的目标，法治政府是建设法治国家的重点，法治社会是构筑法治国家的基础。","author":"习近平"},{"id":"q-04-0006","t":"要研究丰富立法形式，可以搞一些“大块头”，也要搞一些“小快灵”，增强立法的针对性、适用性、可操作性。","author":"习近平"},{"id":"q-04-0007","t":"治其本，朝令而夕从；救其末，百世不改也。","author":"北宋·苏轼《关陇游民私铸钱与江淮漕卒为盗之由》"},{"id":"q-04-0008","t":"圣人能生法，不能废法而治国。","author":"战国·管子《管子·法法》"},{"id":"q-04-0009","t":"法者，治之端也。","author":"战国·荀况《荀子·君道》"},{"id":"q-04-0010","t":"建设法治中国，必须深入推进严格执法、公正司法、全民守法，健全社会公平正义法治保障制度，织密法治之网，强化法治之力，不断增强人民群众的获得感、幸福感、安全感。","author":"《法治中国建设规划（2020－2025年）》"},{"id":"q-04-0011","t":"法治政府建设是全面依法治国的重点任务和主体工程，是推进国家治理体系和治理能力现代化的重要支撑。","author":"《法治中国建设规划（2020－2025年）》"},{"id":"q-04-0012","t":"“枫桥经验”，实现扫黑除恶常态化，营造积极健康的社会生态。","author":"习近平"},{"id":"q-04-0013","t":"基层强则国家强，基层安则天下安，必须抓好基层治理现代化这项基础性工作。","author":"习近平"},{"id":"q-04-0014","t":"基层治理和民生保障事关人民群众切身利益，是促进共同富裕、打造高品质生活的基础性工程。","author":"习近平"},{"id":"q-04-0015","t":"要加强和改进乡村治理，加快构建党组织领导的乡村治理体系，深入推进平安乡村建设，创新乡村治理方式，提高乡村善治水平。","author":"习近平"},{"id":"q-04-0016","t":"基层社区事务很多很繁杂，单靠政府是干不了、也干不好的，必须充分发挥社会各方面作用，激发全社会活力。","author":"习近平"},{"id":"q-04-0017","t":"全面推进依法治国，推进国家治理体系和治理能力现代化，工作的基础在基层。要不断夯实基层基础，加强基层党的领导，引导群众积极参与，带动群众知法、尊法、守法。","author":"习近平"},{"id":"q-04-0018","t":"天下之治，有因有革，期于趋时适治而已。","author":"徐禧《宋史·卷三三四·徐禧传》"},{"id":"q-04-0019","t":"子产治郑，民不能欺；子贱治单父，民不忍欺；西门豹治邺，民不敢欺。","author":"《史记·滑稽列传》"},{"id":"q-04-0020","t":"以党建领航工程为牵引，坚持和加强党的全面领导，为加强基层治理体系和治理能力现代化建设提供坚强政治保障。","author":"《2024年黄浦区深化推进基层治理体系和治理能力现代化建设实施方案》"},{"id":"q-04-0021","t":"加强社区工作者队伍建设，事关保障人民安居乐业，事关维护社会安定有序，事关巩固党的长期执政根基，对于加强基层治理体系和治理能力现代化建设具有重要意义。","author":"《中共中央办公厅国务院办公厅关于加强社区工作者队伍建设的意见》"},{"id":"q-04-0022","t":"运用大数据、云计算、区块链、人工智能等前沿技术推动城市管理手段、管理模式、管理理念创新，从数字化到智能化再到智慧化，让城市更聪明一些、更智慧一些，是推动城市治理体系和治理能力现代化的必由之路。","author":"习近平"},{"id":"q-04-0023","t":"民自律等多主体参与，经济、法律、技术等多种手段相结合的综合治网格局。","author":"习近平"},{"id":"q-04-0024","t":"大数据是信息化发展的新阶段。随着信息技术和人类生产生活交汇融合，互联网快速普及，全球数据呈现爆发增长、海量集聚的特点，对经济发展、社会治理、国家管理、人民生活都产生了重大影响。","author":"习近平"},{"id":"q-04-0025","t":"我们提出推进国家治理体系和治理能力现代化，信息是国家治理的重要依据，要发挥其在这个进程中的重要作用。","author":"习近平"},{"id":"q-04-0026","t":"为世界经济发展增添新动能，迫切需要我们加快数字经济发展，推动全球互联网治理体系向着更加公正合理的方向迈进。","author":"习近平"},{"id":"q-04-0027","t":"要运用大数据提升国家治理现代化水平。要建立健全大数据辅助科学决策和社会治理的机制，推进政府管理和社会治理模式创新，实现政府决策科学化、社会治理精准化、公共服务高效化。","author":"习近平"},{"id":"q-04-0028","t":"大数据是信息化发展的新阶段。","author":"习近平"},{"id":"q-04-0029","t":"加强数字社会、数字政府建设，提升公共服务、社会治理等数字化智能化水平。","author":"《中共中央关于制定国民经济和社会发展第十四个五年规划和二〇三五年远景目标的建议》"},{"id":"q-04-0030","t":"探索基层一体化智慧治理体系，加快高频数据按需合规回流基层，形成基层数据可有效沉淀、可快速共享的应用服务体系，促进业务协同和上下联动。","author":"《国家发展改革委国家数据局财政部自然资源部关于深化智慧城市发展推进城市全域数字化转型的指导意见》"},{"id":"q-04-0031","t":"城市是推进数字中国建设的综合载体，推进城市数字化转型、智慧化发展，是面向未来构筑城市竞争新优势的关键之举，也是推动城市治理体系和治理能力现代化的必然要求。","author":"《国家发展改革委国家数据局财政部自然资源部关于深化智慧城市发展推进城市全域数字化转型的指导意见》"},{"id":"q-04-0032","t":"现在我国经济社会发展很快，城市建设日新月异。越是这样越要加强历史文化街区保护，在加强保护的前提下开展城市基础设施建设，有机融入现代生活气息，让古老城市焕发新的活力。","author":"习近平"},{"id":"q-04-0033","t":"城市是人民的，城市建设要贯彻以人民为中心的发展思想，让人民群众生活更幸福。金杯银杯不如群众口碑，群众说好才是真的好。","author":"习近平"},{"id":"q-04-0034","t":"人民城市人民建、人民城市为人民。城市是人集中生活的地方，城市建设必须把让人民宜居安居放在首位，把最好的资源留给人民。","author":"习近平"},{"id":"q-04-0035","t":"要提高城市治理水平，推动治理手段、治理模式、治理理念创新，加快建设智慧城市，率先构建经济治理、社会治理、城市治理统筹推进和有机衔接的治理体系。","author":"习近平"},{"id":"q-04-0036","t":"城市发展不能只考虑规模经济效益，必须把生态和安全放在更加突出的位置，统筹城市布局的经济需要、生活需要、生态需要、安全需要。","author":"习近平"},{"id":"q-04-0037","t":"推进城市治理，根本目的是提升人民群众获得感、幸福感、安全感。要着力解决人民群众最关心最直接最现实的利益问题，不断提高公共服务均衡化、优质化水平。","author":"习近平"},{"id":"q-04-0038","t":"建设人与自然和谐共生的现代化，必须把保护城市生态环境摆在更加突出的位置，科学合理规划城市的生产空间、生活空间、生态空间，处理好城市生产生活和生态环境保护的关系，既提高经济发展质量，又提高人民生活品质。","author":"习近平"},{"id":"q-04-0039","t":"保护好传统街区，保护好古建筑，保护好文物，就是保存了城市的历史和文脉。对待古建筑、老宅子、老街区要有珍爱之心、尊崇之心。","author":"习近平"},{"id":"q-04-0040","t":"提高生态环境监管治理协同水平，打造智慧高效生态环境数字化监测体系，加强跨部门生态治理业务集成和数据联动，支撑美丽城市建设。","author":"《国家发展改革委国家数据局财政部自然资源部关于深化智慧城市发展推进城市全域数字化转型的指导意见》"},{"id":"q-04-0041","t":"推进建设有韧性的城市数据可信流通体系，健全数据要素流通领域数据安全实时监测预警、数据安全事件通报和应急处理机制。","author":"《国家发展改革委国家数据局财政部自然资源部关于深化智慧城市发展推进城市全域数字化转型的指导意见》"},{"id":"q-04-0042","t":"要完善共建共治共享的社会治理制度，实现政府治理同社会调节、居民自治良性互动，建设人人有责、人人尽责、人人享有的社会治理共同体。","author":"习近平"},{"id":"q-04-0043","t":"乐业，获得感、幸福感、安全感更加充实、更有保障、更可持续。","author":"习近平"},{"id":"q-04-0044","t":"要更加注重联动融合、开放共治，更加注重民主法治、科技创新，提高社会治理社会化、法治化、智能化、专业化水平，提高预测预警预防各类风险能力。","author":"习近平"},{"id":"q-04-0045","t":"加强和创新社会治理，关键在体制创新，核心是人，只有人与人和谐相处，社会才会安定有序。","author":"习近平"},{"id":"q-04-0046","t":"社会治理是一门科学，管得太死，一潭死水不行；管得太松，波涛汹涌也不行。","author":"习近平"},{"id":"q-04-0047","t":"统筹基层党组织和群团组织资源配置，支持群团组织承担公共服务职能。培育扶持基层公益性、服务性、互助性社会组织。","author":"《中共中央国务院关于加强基层治理体系和治理能力现代化建设的意见》"},{"id":"q-04-0048","t":"搭建区域化党建平台，推行机关企事业单位与乡镇（街道）、村（社区）党组织联建共建，组织党员、干部下沉参与基层治理、有效服务群众。","author":"《中共中央国务院关于加强基层治理体系和治理能力现代化建设的意见》"},{"id":"q-04-0049","t":"支持多方主体参与乡村治理。加强妇联、团支部、残协等组织建设，充分发挥其联系群众、团结群众、组织群众参与民主管理和民主监督的作用。","author":"《关于加强和改进乡村治理的指导意见》"},{"id":"q-04-0050","t":"各地要坚持问题导向、需求导向，指导基层大胆探索实践，拓展食品药品安全社会共治路径、方法、模式，提高公众参与度和满意度。","author":"《安徽省人民政府办公厅关于印发进一步加强食品药品安全社会共治若干措施的通知》"},{"id":"q-04-0051","t":"要做诚信守法的表率，带动全社会道德素质和文明程度提升。","author":"习近平"},{"id":"q-04-0052","t":"社会主义市场经济是信用经济、法治经济。","author":"习近平"},{"id":"q-04-0053","t":"人而无信，不知其可也。","author":"《论语·为政》"},{"id":"q-04-0054","t":"人之所助者，信也。","author":"《易经》"},{"id":"q-04-0055","t":"言必诚信，行必忠正。","author":"《孔子家语•儒行解》"},{"id":"q-04-0056","t":"君子养心，莫善于诚。","author":"《荀子·不苟》"},{"id":"q-04-0057","t":"诚者，天之道也；思诚者，人之道也。","author":"《孟子·离娄上》"},{"id":"q-04-0058","t":"诚信者，天下之结也。","author":"《管子·枢言》"},{"id":"q-04-0059","t":"政务诚信是社会信用体系重要组成部分，政府在信用建设中具有表率作用，直接影响政府形象和公信力。","author":"《国家发展改革委关于完善政府诚信履约机制优化民营经济发展环境的通知》"},{"id":"q-04-0060","t":"完善信用修复机制。各级信用牵头部门要协调指导辖区内失信主体信用修复工作，经认定部门确认已纠正失信行为、完成履约的，要及时修复相关失信记录，终止对其实施失信惩戒措施。","author":"《国家发展改革委关于完善政府诚信履约机制优化民营经济发展环境的通知》"},{"id":"q-04-0061","t":"要坚持维护社会公平正义，加强教育培训，严格监督管理，规范权力运行，把严格规范公正文明执法落到实处，不断提高执法司法公信力，努力让人民群众在每一起案件办理、每一件事情处理中都能感受到公平正义。","author":"习近平"},{"id":"q-04-0062","t":"政法机关要完成党和人民赋予的光荣使命，必须严格执法、公正司法。","author":"习近平"},{"id":"q-04-0063","t":"“公生明，廉生威。”执法司法是否具有公信力，主要看两点，一是公正不公正，二是廉洁不廉洁。这两点说起来简单，要做到就不容易了。要扭住职业良知、坚守法治、制度约束、公开运行等环节，坚持不懈，持之以恒地抓。","author":"习近平"},{"id":"q-04-0064","t":"持心如衡，以理为平。","author":"明·刘伯温《郁离子》"},{"id":"q-04-0065","t":"言非法度不出于口，行非公道不萌于心。","author":"唐·杨炯《杜袁州墓志铭》"},{"id":"q-04-0066","t":"平出于公，公出于道。","author":"吕不韦《吕氏春秋·大乐》"},{"id":"q-04-0067","t":"公与平者，即国之基址也。","author":"清·何启"},{"id":"q-04-0068","t":"公则四通八达，私则一偏而隅。","author":"明·薛瑄《从政名言》"},{"id":"q-04-0069","t":"公正是施政的目的。","author":"丹·笛福"},{"id":"q-04-0070","t":"力量来自公正。","author":"林肯"},{"id":"q-04-0071","t":"要完善基层群众自治机制，调动城乡群众、企事业单位、社会组织自主自治的积极性，打造人人有责、人人尽责的社会治理共同体。","author":"习近平"},{"id":"q-04-0072","t":"采取切实有效措施，强化农村基层党组织领导作用，选好配强农村党组织书记，整顿软弱涣散村党组织，深化村民自治实践，加强村级权力有效监督。","author":"习近平"},{"id":"q-04-0073","t":"社区是基层自治的基本单元，是国家治理体系的基层基础。通过社区这个平台，办好“一老一小”等民生实事和公共事务，积极回应群众关切。","author":"习近平"},{"id":"q-04-0074","t":"从来治国者，宁不忘渔樵。","author":"明·谢榛"},{"id":"q-04-0075","t":"政之所兴，在顺民心；政之所废，在逆民心。","author":"管仲《管子·牧民》"},{"id":"q-04-0076","t":"天下顺治在民富，天下和静在民乐，天下兴行在民趋于正。","author":"明·王廷相《慎言—御民篇》"},{"id":"q-04-0077","t":"民为贵，社稷次之，君为轻。","author":"先秦·孟子《孟子四章》"},{"id":"q-04-0078","t":"在基层公共事务和公益事业中广泛实行群众自我管理、自我服务、自我教育、自我监督，拓宽群众反映意见和建议的渠道。","author":"《中共中央国务院关于加强基层治理体系和治理能力现代化建设的意见》"},{"id":"q-04-0079","t":"坚持党组织领导基层群众性自治组织的制度，建立基层群众性自治组织法人备案制度，加强集体资产管理。","author":"《中共中央国务院关于加强基层治理体系和治理能力现代化建设的意见》"},{"id":"q-04-0080","t":"以习近平新时代中国特色社会主义思想为指导，坚持“以人民为中心、群众自治、依法治理”原则，着力改进和规范基层群众性自治组织出具证明工作，从根本上改变“村（社区）万能章”“证明大本营”等现象，打通联系服务居民群众“最后一公里”，切实增强居民群众的获得感和幸福感。","author":"江苏省泰兴市曲霞镇《关于改进和规范基层群众性自治组织出具证明工作的实施意见》"},{"id":"q-04-0081","t":"各级领导班子和领导干部要树牢正确政绩观，持续整治形式主义为基层减负，引导广大党员干部真抓实干、开拓进取，全力推动党中央决策部署落实落地。","author":"习近平"},{"id":"q-04-0082","t":"党中央明确要求为基层减负，坚决整治形式主义、官僚主义问题，要精兵简政，继续把这项工作抓下去。","author":"习近平"},{"id":"q-04-0083","t":"为基层减负要明确权责，不能什么事都压给基层，基层该承担哪些工作，要把职责事项搞清楚。","author":"习近平"},{"id":"q-04-0084","t":"持续深化整治形式主义为基层减负，为基层干部干事创业创造良好条件。","author":"习近平"},{"id":"q-04-0085","t":"要巩固拓展主题教育成果，建立健全长效机制，树立和践行正确政绩观，持续深化整治形式主义为基层减负。","author":"习近平"},{"id":"q-04-0086","t":"各类应景性、应酬性活动少一点科技人员参加，不会带来什么损失！决不能让科技人员把大量时间花在一些无谓的迎来送往活动上，花在不必要的评审评价活动上，花在形式主义、官僚主义的种种活动上！","author":"习近平"},{"id":"q-04-0087","t":"对形式主义、官僚主义要毫不妥协，全面检视、靶向纠治，持续为基层松绑减负，树立重实干、重实绩的用人导向，督促全党担当尽责、干事创业。","author":"习近平"},{"id":"q-04-0088","t":"加强乡镇对县直部门派驻机构及人员的管理职责，加大编制资源向乡镇倾斜力度，县以上机关一般不得从乡镇借调工作人员，推广“街乡吹哨、部门报到”等做法，严格实行上级部门涉基层事务准入制度，健全基层职责清单和事务清单，推动解决“小马拉大车”等基层治理问题。","author":"《中共中央国务院关于学习运用“千村示范、万村整治”工程经验有力有效推进乡村全面振兴的意见》"},{"id":"q-04-0089","t":"要健全全面从严治党体系，切实改进作风，克服形式主义、官僚主义顽疾，持续为基层减负，深入推进党风廉政建设和反腐败斗争，扎实做好巡视工作。","author":"中国共产党第二十届中央委员会第三次全体会议"},{"id":"q-04-0090","t":"推进数据共享核查。各区、各单位可以依托国家数据共享交换平台、全国信用信息共享平台和本市“一网通办”等共享平台的数据，实现跨地区、跨部门、跨层级数据共享和业务协同。","author":"《上海市教育委员会关于进一步落实居村组织减负工作的通知》"},{"id":"q-04-0091","t":"为人民服务是我们党的根本宗旨，也是各级政府的根本宗旨。不论政府职能怎么转，为人民服务的宗旨都不能变。","author":"习近平"},{"id":"q-04-0092","t":"要坚持以人为本、执政为民，接地气、通下情，想群众之所想，急群众之所急，解群众之所忧，在服务中实施管理，在管理中实现服务。","author":"习近平"},{"id":"q-04-0093","t":"我们对政府职能的认识和定位，是随着改革开放和社会主义市场经济发展而发展的，从传统计划经济体制向社会主义市场经济体制转变是一个不断前进的过程。","author":"习近平"},{"id":"q-04-0094","t":"我们党的根本宗旨就是为人民群众办好事，为人民群众幸福生活拼搏、奉献、服务。","author":"习近平"},{"id":"q-04-0095","t":"居庙堂之高则忧其民，处江湖之远则忧其君。","author":"宋·范仲淹《岳阳楼记》"},{"id":"q-04-0096","t":"无取民者，民利之；无取国者，国利之；无取天下者，天下利之。","author":"《六韬·武韬·发启》"},{"id":"q-04-0097","t":"按照成熟稳定、适度超前的原则，创新开展大数据、区块链、人工智能等新技术应用，推动政务服务由人力服务型向人机交互型转变，由经验判断型向数据分析型转变。","author":"《国务院关于进一步优化政务服务提升行政效能推动“高效办成一件事”的指导意见》"},{"id":"q-04-0098","t":"聚焦企业跨区域经营和群众异地办事需求，持续推动更多政务服务事项省内通办、跨省通办，做到就近办、异地办。","author":"《国务院关于进一步优化政务服务提升行政效能推动“高效办成一件事”的指导意见》"},{"id":"q-04-0099","t":"以政务服务部门清楚告知、企业和群众诚信守诺为基础，对风险可控、纠错成本低且能够通过事中事后监管有效防范风险的政务服务事项，推行“告知承诺+容缺办理”审批服务模式。","author":"《国务院关于进一步优化政务服务提升行政效能推动“高效办成一件事”的指导意见》"},{"id":"q-04-0100","t":"加强以国家政务服务平台为总枢纽、联通各地区各部门政务服务平台的全国政务服务“一张网”建设，推动更多高频事项网上办、掌上办、一次办，实现从网上可办向好办易办转变。","author":"《国务院关于进一步优化政务服务提升行政效能推动“高效办成一件事”的指导意见》"},{"id":"q-04-0101","t":"优化政务服务、提升行政效能是优化营商环境、建设全国统一大市场的必然要求，对加快构建新发展格局、推动高质量发展具有重要意义。","author":"《国务院关于进一步优化政务服务提升行政效能推动“高效办成一件事”的指导意见》"},{"id":"q-04-0102","t":"推进国家、省、市、县、乡五级政务服务体系建设，健全一体联动、高效便捷、权责清晰的工作机制。","author":"《国务院关于进一步优化政务服务提升行政效能推动“高效办成一件事”的指导意见》"},{"id":"q-04-0103","t":"要加强省市县乡四级全覆盖的行政执法协调监督工作体系建设，强化全方位、全流程监督，提高执法质量。","author":"习近平"},{"id":"q-04-0104","t":"要坚持抓“关键少数”和管“绝大多数”相统一，既对广大党员提出普遍性要求，又对“关键少数”特别是高级干部提出更高更严的标准进行更严的管理和监督。","author":"习近平"},{"id":"q-04-0105","t":"要完善宪法监督制度，积极稳妥推进合宪性审查工作，加强备案审查制度和能力建设。","author":"习近平"},{"id":"q-04-0106","t":"金融监管要“长牙带刺”、有棱有角，关键在于金融监管部门和行业主管部门要明确责任，加强协作配合。在市场准入、审慎监管、行为监管等各个环节，都要严格执法，实现金融监管横向到边、纵向到底。","author":"习近平"},{"id":"q-04-0107","t":"领导干部严格自律，要注重自觉主动接受监督，对党忠诚老实，党员、干部决不能以任何借口而拒绝监督党组织也决不能以任何理由而放松监督。","author":"习近平"},{"id":"q-04-0108","t":"要健全精准发力、标本兼治的监管体系。","author":"习近平"},{"id":"q-04-0109","t":"必须坚持党性党风党纪一起抓、治病强身相结合，改进党员管理机制，完善从严管理监督干部机制，健全正风肃纪常态化机制，完善一体推进不敢腐、不能腐、不想腐工作机制。","author":"习近平"},{"id":"q-04-0110","t":"加强监管标准化规范化建设，依法公开监管标准和规则，增强监管制度和政策的稳定性、可预期性。","author":"《中共中央国务院关于促进民营经济发展壮大的意见》"},{"id":"q-04-0111","t":"要健全行政执法监督工作体制机制，推动行政执法监督与其他各类监督有机贯通、相互协调。","author":"《关于加强行政执法协调监督工作体系建设的意见》"},{"id":"q-04-0112","t":"行政执法监督作为上级行政机关对下级行政机关行政执法工作的内部层级监督，是党和国家监督体系的重要组成部分，是各级党委和政府统筹行政执法工作的基本方式。","author":"《关于加强行政执法协调监督工作体系建设的意见》"}],"精神文明篇":[{"id":"q-05-0000","t":"行政执法监督数字化建设，建立督促落实机制，加强协作配合，做到有部署、重落实、见成效。","author":"《关于加强行政执法协调监督工作体系建设的意见》"},{"id":"q-05-0001","t":"我国周边外交的基本方针，就是坚持与邻为善、以邻为伴，坚持睦邻、安邻、富邻，突出体现亲、诚、惠、容的理念。","author":"习近平"},{"id":"q-05-0002","t":"在5000多年的文化发展中，中华民族一直追求和传承着和平、和睦、和谐的坚定理念。以和为贵，与人为善，己所不欲、勿施于人等理念在中国代代相传，深深植根于中国人的精神中，深深体现在中国人的行为上。","author":"习近平"},{"id":"q-05-0003","t":"中华民族几千年来形成了兼爱非攻、亲仁善邻、以和为贵、和而不同的理念。","author":"习近平"},{"id":"q-05-0004","t":"人而不仁，则道义息。","author":"胡宏《胡子知言·修身》"},{"id":"q-05-0005","t":"大学之道，在明明德，在亲民，在止于至善。","author":"汉·礼记《大学之道》"},{"id":"q-05-0006","t":"亲仁善邻，国之宝也。","author":"左丘明《左传·隐公·隐公六年》"},{"id":"q-05-0007","t":"仁者爱人，有礼者敬人。爱人者，人恒爱之；敬人者，人恒敬之。","author":"孟子《孟子·离娄下》"},{"id":"q-05-0008","t":"仁为万善本，贪是诸恶根。","author":"清·史襄哉《中华谚海》"},{"id":"q-05-0009","t":"仁人无敌于天下。","author":"《孟子》"},{"id":"q-05-0010","t":"如果一切皆善，就一切皆美。","author":"列夫·尼古拉耶维奇·托尔斯泰"},{"id":"q-05-0011","t":"亲善产生幸福，文明带来和谐。","author":"维克多·雨果"},{"id":"q-05-0012","t":"书需巢，蛛需网，人需友情。","author":"英国·布莱克"},{"id":"q-05-0013","t":"全面建设社会主义现代化国家，一个民族也不能少。在中华民族大家庭中，大家只有像石榴籽一样紧紧抱在一起，手足相亲、守望相助，才能实现民族复兴的伟大梦想，民族团结进步之花才能长盛不衰。","author":"习近平"},{"id":"q-05-0014","t":"一部中国史，就是一部各民族交融汇聚成多元一体中华民族的历史，就是各民族共同缔造、发展、巩固统一的伟大祖国的历史。","author":"习近平"},{"id":"q-05-0015","t":"实现中华民族伟大复兴的中国梦，就要以铸牢中华民族共同体意识为主线，把民族团结进步事业作为基础性事业抓紧抓好。","author":"习近平"},{"id":"q-05-0016","t":"中华民族是一个大家庭，一家人都要过上好日子。","author":"习近平"},{"id":"q-05-0017","t":"实现中华民族伟大复兴，需要各民族手挽着手、肩并着肩，共同努力奋斗。","author":"习近平"},{"id":"q-05-0018","t":"铸牢中华民族共同体意识，就是要引导各族人民牢固树立休戚与共、荣辱与共、生死与共、命运与共的共同体理念。","author":"习近平"},{"id":"q-05-0019","t":"团结一致，同心同德，任何强大的敌人，任何困难的环境，都会向我们投降。","author":"毛泽东"},{"id":"q-05-0020","t":"能用众力，则无敌于天下矣；能用众智，则无畏于圣人矣。","author":"晋·陈寿《三国志·吴书》"},{"id":"q-05-0021","t":"天时不如地利，地利不如人和。","author":"先秦·《孟子》"},{"id":"q-05-0022","t":"若不团结，任何力量都是弱小的。","author":"拉封丹"},{"id":"q-05-0023","t":"共同的事业，共同的斗争，可以使人们产生忍受一切的力量。","author":"奥斯特洛夫斯基"},{"id":"q-05-0024","t":"九牛一毫莫自夸，骄傲自满必翻车。历览古今多少事，成由谦逊败由奢。","author":"陈毅《七古手莫伸》"},{"id":"q-05-0025","t":"终身让人道，曾不失寸步。","author":"清·曾国藩《不忮不求诗》"},{"id":"q-05-0026","t":"满招损，谦受益。","author":"先秦《尚书·大禹谟》"},{"id":"q-05-0027","t":"不学礼，无以立。","author":"孔子《论语·季氏篇第十六》"},{"id":"q-05-0028","t":"夫礼，天之经也，地之义也，民之行也。","author":"《左传》"},{"id":"q-05-0029","t":"礼，天之经也，地之义也，民之行也。","author":"《左传》"},{"id":"q-05-0030","t":"一个人的礼貌，就是一面照出他的肖像的镜子。","author":"歌德"},{"id":"q-05-0031","t":"礼仪是微妙的东西，它既是人们交际所不可或缺的，又是不可过于计较的。","author":"培根"},{"id":"q-05-0032","t":"怀着善意的人，是不难于表达他对人的礼貌的。","author":"卢梭"},{"id":"q-05-0033","t":"中华传统美德是中华文化精髓，是道德建设的不竭源泉。","author":"《新时代公民道德建设实施纲要》"},{"id":"q-05-0034","t":"优秀传统文化是我们民族的“根”和“魂”。要深入挖掘和阐发讲仁爱、重民本、守诚信、崇正义、尚和合、求大同的时代价值。","author":"《关于深化群众性精神文明创建活动的指导意见》"},{"id":"q-05-0035","t":"发挥先进典型示范激励作用，深入开展反面典型警示教育，以案示警、以案明纪，促进党员、干部知敬畏、守底线，纪律意识和规矩意识进一步提升，公正用权、依法用权、廉洁用权的自觉性明显增强，党群干群关系更加密切，党内政治生态持续好转。","author":"习近平"},{"id":"q-05-0036","t":"纪律是管党治党的“戒尺”，也是党员、干部约束自身行为的标准和遵循。要把纪律建设摆在更加突出位置，党规制定、党纪教育、执纪监督全过程都要贯彻严的要求，既让铁纪“长牙”、发威，又让干部重视、警醒、知止，使全党形成遵规守纪的高度自觉。","author":"习近平"},{"id":"q-05-0037","t":"不以规矩，不能成方圆。","author":"《孟子·离娄章句上》"},{"id":"q-05-0038","t":"人道经纬万端，规矩无所不贯，诱进以仁义，束缚以刑罚。","author":"司马迁《史记·礼书》"},{"id":"q-05-0039","t":"欲知平直，则必准绳；欲知方圆，则必规矩。","author":"《吕氏春秋·自知》"},{"id":"q-05-0040","t":"古器合尺度，法物应矩规。","author":"北宋·苏洵《颜书四十韵》"},{"id":"q-05-0041","t":"大矩崇规，链金烹矿。","author":"宋·黄庭坚《头陀赞》"},{"id":"q-05-0042","t":"世界上的一切都必须按照一定的规矩秩序各就各位。","author":"弗拉迪斯拉夫·莱蒙特"},{"id":"q-05-0043","t":"万事离不开方法，世界离不开秩序。","author":"乔纳森·斯威夫特"},{"id":"q-05-0044","t":"加强党规党纪教育特别是政治纪律和政治规矩教育，督促党员、干部强化组织观念，做到“四个服从”。党员领导干部要严守党的政治纪律和政治规矩，严格执行廉洁自律准则、党内政治生活若干准则、重大事项请示报告制度、领导干部个人有关事项报告制度等，知敬畏、存戒惧、守底线。","author":"《关于巩固深化“不忘初心、牢记使命”主题教育成果的意见》"},{"id":"q-05-0045","t":"违反党的优良传统和工作惯例等党的规矩，在政治上造成不良影响或者严重后果的，给予警告或者严重警告处分","author":"《中国共产党纪律处分条例》"},{"id":"q-05-0046","t":"对突出的诚信缺失问题，既要抓紧建立覆盖全社会的征信系统，又要完善守法诚信褒奖机制和违法失信惩戒机制，使人不敢失信、不能失信。","author":"习近平"},{"id":"q-05-0047","t":"要做诚信守法的表率，带动全社会道德素质和文明程度提升。","author":"习近平"},{"id":"q-05-0048","t":"推人以诚，则不言而信矣。","author":"王通《文中子·周公》"},{"id":"q-05-0049","t":"丈夫一言许人，千金不易。","author":"司马光《资治通鉴·唐纪》"},{"id":"q-05-0050","t":"伟大人格的素质，重要的是一个诚字。","author":"鲁迅"},{"id":"q-05-0051","t":"坦白是诚实和勇敢的产物。","author":"马克·吐温"},{"id":"q-05-0052","t":"生命不可能从谎言中开出灿烂的鲜花。","author":"海因里希·海涅"},{"id":"q-05-0053","t":"持续推进诚信建设。诚信是社会和谐的基石和重要特征。","author":"《新时代公民道德建设实施纲要》"},{"id":"q-05-0054","t":"大力弘扬诚信文化。将诚信文化建设摆在突出位置，以培育和践行社会主义核心价值观为根本，大力普及信用知识，制定颁布公民诚信守则，将诚信教育贯穿公民道德建设和精神文明创建全过程。","author":"《关于加强个人诚信体系建设的指导意见》"},{"id":"q-05-0055","t":"加强社会公德、职业道德、家庭美德和个人品德教育，营造“守信者荣、失信者耻、无信者忧”的社会氛围。","author":"《关于加强个人诚信体系建设的指导意见》"},{"id":"q-05-0056","t":"党员、干部特别是领导干部要清白做人、勤俭齐家、干净做事、廉洁从政，管好自己和家人，涵养新时代共产党人的良好家风","author":"习近平"},{"id":"q-05-0057","t":"所有党员、干部都要戒贪止欲、克己奉公，切实把人民赋予的权力用来造福于人民。要把家风建设摆在重要位置，廉洁修身，廉洁齐家，防止“枕边风”成为贪腐的导火索，防止子女打着自己的旗号非法牟利，防止身边人把自己“拉下水”。","author":"习近平"},{"id":"q-05-0058","t":"家风家教是一个家庭最宝贵的财富，是留给子孙后代最好的遗产。要推动全社会注重家庭家教家风建设，激励子孙后代增强家国情怀，努力成长为对国家、对社会有用之才。","author":"习近平"},{"id":"q-05-0059","t":"不论时代发生多大变化，不论生活格局发生多大变化，我们都要重视家庭建设，注重家庭、注重家教、注重家风。","author":"习近平"},{"id":"q-05-0060","t":"家风好，就能家道兴盛、和顺美满；家风差，难免殃及子孙、贻害社会。","author":"习近平"},{"id":"q-05-0061","t":"治家严家乃和；居乡恕乡乃睦。","author":"《格言联璧·齐家类》"},{"id":"q-05-0062","t":"治家以和平两字为主。","author":"清·钱泳《履园丛话·治家》"},{"id":"q-05-0063","t":"修身而家齐，家齐而后国治，国治而后天下平。","author":"先秦·曾参《修身齐家治国平天下》"},{"id":"q-05-0064","t":"天下之本在国，国之本在家。","author":"《孟子·离娄上·第五章》"},{"id":"q-05-0065","t":"要大力宣传党的优良传统、中国历代著名家训、革命先辈家风、优秀党员干部家风事迹，不断营造良好氛围，增强社会效应。","author":"《关于加强新时代家庭家教家风建设的实施意见》"},{"id":"q-05-0066","t":"将培育和践行社会主义核心价值观融入家庭家教家风建设全过程，引导家庭成员形成适应新时代要求的思想观念、精神面貌、文明风尚、行为规范。","author":"《关于加强新时代家庭家教家风建设的实施意见》"},{"id":"q-05-0067","t":"理念，自觉践行人民对美好生活的向往就是我们的奋斗目标的承诺，做到心底无私天地宽。","author":"习近平"},{"id":"q-05-0068","t":"要深入推进公民道德建设、志愿服务建设、诚信社会建设、网络文明建设，不断提高人民道德水准和文明素养。","author":"习近平"},{"id":"q-05-0069","t":"全党同志都要明大德、守公德、严私德，清清白白做人、干干净净做事，做到克己奉公、以俭修身，永葆清正廉洁的政治本色。","author":"习近平"},{"id":"q-05-0070","t":"德不广不能使人来，量不宏不能使人安。","author":"明·刘基《郁离子·德量》"},{"id":"q-05-0071","t":"善为吏者树德，不善为吏者树怨。","author":"《韩非子·外储说左下》"},{"id":"q-05-0072","t":"道德当身，故不以物惑。","author":"管仲《管子·戒》"},{"id":"q-05-0073","t":"道德能帮助人类社会升到更高的水平，使人类社会摆脱劳动剥削制。","author":"列宁"},{"id":"q-05-0074","t":"道德的基础是人类精神的自律。","author":"马克思"},{"id":"q-05-0075","t":"推进公民道德建设，大力开展社会公德、职业道德、家庭美德、个人品德建设。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-05-0076","t":"引导青少年把正确的道德认知、自觉的道德养成、积极的道德实践紧密结合起来，善于从中华民族传统美德中汲取道德滋养，从英雄人物和时代楷模身上感受道德风范，从自身内省中提升道德修为，不断修身立德，打牢道德根基。","author":"《新时代公民道德建设实施纲要》"},{"id":"q-05-0077","t":"网络空间天朗气清、生态良好，符合人民利益。网络空间乌烟瘴气、生态恶化，不符合人民利益。","author":"习近平"},{"id":"q-05-0078","t":"我们要本着对社会负责，对人民负责的态度，依法加强网络空间治理，加强网络内容建设，做强网上正面宣传。","author":"习近平"},{"id":"q-05-0079","t":"加强全媒体传播体系建设，塑造主流舆论新格局。健全网络综合治理体系，推动形成良好网络生态。","author":"习近平"},{"id":"q-05-0081","t":"各级党委（党组）要加强组织领导、强化统筹协调，确保党中央关于网信工作决策部署落到实处；各级网信部门要忠于党和人民，勇于担当作为，善于开拓创新，敢于斗争亮剑，甘于拼搏奉献，为推动网信事业高质量发展提供坚强保证。","author":"习近平"},{"id":"q-05-0082","t":"网络信息内容广泛影响着人们的思想观念和道德行为。要深入实施网络内容建设工程，弘扬主旋律，激发正能量，让科学理论、正确舆论、优秀文化充盈网络空间。","author":"《新时代公民道德建设实施纲要》"},{"id":"q-05-0083","t":"要加强网上热点话题和突发事件的正确引导、有效引导，明辨是非、分清善恶，让正确道德取向成为网络空间的主流。","author":"《新时代公民道德建设实施纲要》"},{"id":"q-05-0084","t":"为营造良好网络道德环境，将开展网络治理专项行动，加大对网上突出问题的整治力度，清理网络欺诈、造谣、诽谤、谩骂、歧视、色情、低俗等内容，反对网络暴力行为，依法惩治网络违法犯罪，促进网络空间日益清朗。","author":"《新时代公民道德建设实施纲要》"},{"id":"q-05-0085","t":"网络信息内容服务平台应当履行信息内容管理主体责任，加强本平台网络信息内容生态治理，培育积极健康、向上向善的网络文化。","author":"《网络信息内容生态治理规定》"}],"生态文明篇":[{"id":"q-06-0000","t":"网上行为主体的文明自律是网络空间道德建设的基础。要建立和完善网络行为规范，明确网络是非观念，培育符合互联网发展规律、体现社会主义精神文明建设要求的网络伦理、网络道德。","author":"《新时代公民道德建设实施纲要》"},{"id":"q-06-0001","t":"希望全社会行动起来，做生态文明理念的积极传播者和模范践行者，身体力行、真抓实干，为子孙后代留下天蓝、地绿、水清的美丽家园。","author":"习近平"},{"id":"q-06-0002","t":"我们要维持地球生态整体平衡，让子孙后代既能享有丰富的物质财富，又能遥望星空、看见青山、闻到花香。","author":"习近平"},{"id":"q-06-0003","t":"我们要敬畏自然、珍爱地球，树立绿色、低碳、可持续发展理念。","author":"习近平"},{"id":"q-06-0004","t":"人不负青山，青山定不负人。生态文明是人类文明发展的历史趋势。让我们携起手来，秉持生态文明理念，站在为子孙后代负责的高度，共同构建地球生命共同体，共同建设清洁美丽的世界！","author":"习近平"},{"id":"q-06-0005","t":"“天人合一”、“道法自然”是中华优秀传统文化的重要理念。我们身处同一个地球村，在我们有生之年可能找不到另一个星球供人类生存了。","author":"习近平"},{"id":"q-06-0006","t":"中国生态文明建设进入了快车道，天更蓝、山更绿、水更清将不断展现在世人面前。","author":"习近平"},{"id":"q-06-0007","t":"只有服从大自然，才能战胜大自然。","author":"达尔文"},{"id":"q-06-0008","t":"我们不要过分陶醉于我们对自然界的胜利，对于每一次这样的胜利，自然界都报复了我们。","author":"恩格斯"},{"id":"q-06-0009","t":"大自然是善良的慈母，同时也是冷酷的屠夫。","author":"雨果"},{"id":"q-06-0010","t":"只有顺从自然，才能驾驭自然。","author":"培根"},{"id":"q-06-0011","t":"生态保护补偿可以采取资金补偿、对口协作、产业转移、人才培训、共建园区、购买生态产品和服务等多种补偿方式。","author":"《生态保护补偿条例》"},{"id":"q-06-0012","t":"根据生态效益外溢性、生态功能重要性、生态环境敏感性和脆弱性等特点，在重点生态功能区转移支付中实施差异化补偿，加大对生态保护红线覆盖比例较高地区支持力度。","author":"《生态保护补偿条例》"},{"id":"q-06-0013","t":"促进经济社会发展全面绿色转型是解决资源环境生态问题的基础之策，要坚持全面转型、协同转型、创新转型、安全转型，以“双碳”工作为引领，协同推进降碳、减污、扩绿、增长，把绿色发展理念贯穿于经济社会发展全过程各方面。","author":"习近平"},{"id":"q-06-0014","t":"要坚定不移贯彻新发展理念，全方位全过程推行绿色规划、绿色设计、绿色投资、绿色建设、绿色生产、绿色流通、绿色生活、绿色消费。","author":"习近平"},{"id":"q-06-0015","t":"绿色发展是高质量发展的底色，新质生产力本身就是绿色生产力。必须加快发展方式绿色转型，助力碳达峰碳中和。牢固树立和践行绿水青山就是金山银山的理念，坚定不移走生态优先、绿色发展之路。","author":"习近平"},{"id":"q-06-0017","t":"加快产业结构优化调整，推动产业体系绿色转型，发展壮大林业产业、文旅产业、养老产业、大健康产业，让生态优势不断转化为发展优势","author":"习近平"},{"id":"q-06-0018","t":"只有把绿色发展的底色铺好，才会有今后发展的高歌猛进。","author":"习近平"},{"id":"q-06-0019","t":"要坚持绿色发展，一代接着一代干，久久为功，建设美丽中国，为保护好地球村作出中国贡献。","author":"习近平"},{"id":"q-06-0020","t":"加强区域绿色发展协作，统筹推进协调发展和协同转型，打造绿色低碳高质量发展的增长极和动力源。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0021","t":"推动农业农村绿色发展。实施农业农村减排固碳行动，优化种养结构，推广优良作物畜禽品种和绿色高效栽培养殖技术，推进化肥、农药等农业投入品减量增效。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0022","t":"拓展多双边对话合作渠道，加强绿色发展领域的多边合作平台建设，大力宣传中国绿色转型成效，积极借鉴国际经验。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0023","t":"持续优化支持绿色低碳发展的经济政策工具箱，发挥绿色金融的牵引作用，打造高效生态绿色产业集群。","author":"习近平"},{"id":"q-06-0024","t":"良好的生态环境蕴含着无穷的经济价值。推进生态产业化和产业生态化，培育大量生态产品走向市场，让生态优势源源不断转化为发展优势。","author":"习近平"},{"id":"q-06-0025","t":"兴绿，就是要注重质量效益，拓展绿水青山转化为金山银山的路径，推动森林“水库、钱库、粮库、碳库”夏更好联动，实现生态效益、经济效益、社会效益相统一。","author":"习近平"},{"id":"q-06-0026","t":"经济发展不能以破坏生态为代价，生态本身就是经济，保护生态就是发展生产力。","author":"习近平"},{"id":"q-06-0027","t":"推动经济高质量发展，决不能再走先污染后治理的老路。只要坚持生态优先、绿色发展，锲而不舍，久久为功，就一定能把绿水青山变成金山银山。","author":"习近平"},{"id":"q-06-0028","t":"生态环境保护和经济发展不是矛盾对立的关系，而是辩证统一的关系。把生态保护好，把生态优势发挥出来，才能实现高质量发展。","author":"习近平"},{"id":"q-06-0029","t":"生态保护补偿工作坚持中国共产党的领导，坚持政府主导、社会参与、市场调节相结合，坚持激励与约束并重，坚持统筹协同推进，坚持生态效益与经济效益、社会效益相统一。","author":"《生态保护补偿条例》"},{"id":"q-06-0030","t":"持续推进长江经济带共抓大保护，探索生态优先、绿色发展新路径。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0031","t":"大力发展循环经济。深入推进循环经济助力降碳行动，推广资源循环型生产模式，大力发展资源循环利用产业，推动再制造产业高质量发展，提高再生材料和产品质量，扩大对原生资源的替代规模。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0032","t":"支持淮河、汉江生态经济带上下游合作联动发展。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-06-0033","t":"生态环境没有替代品，用之不觉，失之难存。","author":"习近平"},{"id":"q-06-0034","t":"要着力提升生态系统多样性、稳定性、持续性，加大生态系统保护力度，切实加强生态保护修复监管，拓宽绿水青山转化金山银山的路径，为子孙后代留下山清水秀的生态空间。","author":"习近平"},{"id":"q-06-0035","t":"我国人工造林规模世界第一，而且还在继续造林。地球绿化，改善全球气候变化，中国功不可没，中国人民功不可没。","author":"习近平"},{"id":"q-06-0036","t":"面对生态环境挑战，人类是一荣俱荣、一损俱损的命运共同体，没有哪个国家能独善其身。","author":"习近平"},{"id":"q-06-0037","t":"良好的生态环境是最公平的公共产品，是最普惠的民生福祉。","author":"习近平"},{"id":"q-06-0038","t":"仓满鼠雀喜，草尽兔狐愁。","author":"宋·包拯《书端州郡斋壁》"},{"id":"q-06-0039","t":"水光山色与人亲，说不尽、无穷好。","author":"宋·李清照《怨王孙·湖上风来波浩渺》"},{"id":"q-06-0040","t":"久在樊笼里，复得返自然。","author":"魏晋·陶渊明《归园田居（其一）》"},{"id":"q-06-0041","t":"地球所提供的足以满足每个人的需要，但不足以填满每个人的欲望。","author":"莫罕达"},{"id":"q-06-0042","t":"大自然的每一个领域都是美妙绝伦的。","author":"亚里士多德"},{"id":"q-06-0043","t":"大自然不会欺骗我们，欺骗我们的往往是我们自己。","author":"卢梭"},{"id":"q-06-0044","t":"在资源利用上线方面，不仅要考虑人类和当代的需要，也要考虑大自然和后人的需要，把握好自然资源开发利用的度，不要突破自然资源承载能力。","author":"习近平"},{"id":"q-06-0045","t":"要增强全民节约意识、环保意识、生态意识，培育生态道德和行为准则，开展全民绿色行动，动员全社会都以实际行动减少能源资源消耗和污染排放，为生态环境保护作出贡献。","author":"习近平"},{"id":"q-06-0046","t":"要倡导绿色低碳生活，反对奢侈浪费，鼓励绿色出行，营造绿色低碳生活新时尚。","author":"习近平"},{"id":"q-06-0048","t":"我们土地是不少，但同14亿人口的需求一比，又是稀缺资源！建城市、搞工业、保生态都要用地，必须精打细算。","author":"习近平"},{"id":"q-06-0049","t":"取之有度，用之有节，则常足。取之无度，用之不节，则常不足。","author":"北宋·司马光《资治通鉴》"},{"id":"q-06-0050","t":"木无本必枯，水无源必竭。","author":"明·冯梦龙《东周列国志》"},{"id":"q-06-0051","t":"实施国家节水行动，建立水资源刚性约束制度。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-06-0052","t":"引导企业开展绿色设计、选择绿色材料、推行绿色制造、采用绿色包装、开展绿色运输、回收利用资源，降低产品全生命周期能源资源消耗和生态环境影响。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0053","t":"落实水资源刚性约束制度，发展节水产业，加强非常规水源利用，建设节水型社会。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0054","t":"完善资源总量管理和全面节约制度，加强水、粮食、土地、矿产等各类资源的全过程管理和全链条节约。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0055","t":"生态环境治理是一项系统工程，需要统筹考虑环境要素的复杂性、生态系统的完整性、自然地理单元的连续性、经济社会发展的可持续性。","author":"习近平"},{"id":"q-06-0057","t":"要加快划定并严守生态保护红线、环境质量底线、资源利用上线三条红线。","author":"习近平"},{"id":"q-06-0058","t":"要坚持精准治污、科学治污、依法治污，保持力度、延伸深度、拓展广度，深入推进环境污染防治，持续改善生态环境质量","author":"习近平"},{"id":"q-06-0059","t":"要下大气力抓住破坏生态环境的反面典型，释放出严加惩处的强烈信号。","author":"习近平"},{"id":"q-06-0060","t":"要严格用制度管权治吏、护蓝增绿，有权必有责、有责必担当、失责必追究，保证党中央关于生态文明建设决策部署落地生根见效。","author":"习近平"},{"id":"q-06-0061","t":"生态环境分区管控是以保障生态功能和改善环境质量为目标，实施分区域差异化精准管控的环境管理制度，是提升生态环境治理现代化水平的重要举措。","author":"《中共中央办公厅国务院办公厅关于加强生态环境分区管控的意见》"},{"id":"q-06-0062","t":"健全生态环境源头预防体系，统筹山水林田湖草沙一体化保护和系统治理，加强生物多样性保护，强化多污染物协同控制和区域协同治理。","author":"《中共中央办公厅国务院办公厅关于加强生态环境分区管控的意见》"},{"id":"q-06-0063","t":"通过生态环境分区管控，加强整体性保护和系统性治理，支撑优化重大生产力布局，服务国家重大基础设施建设，保障国家重大战略实施。","author":"《中共中央办公厅国务院办公厅关于加强生态环境分区管控的意见》"},{"id":"q-06-0064","t":"异化管控要求。","author":"《中共中央办公厅国务院办公厅关于加强生态环境分区管控的意见》"},{"id":"q-06-0065","t":"倡导环保意识、生态意识，构建全社会共同参与的环境治理体系，让生态环保思想成为社会生活中的主流文化。","author":"习近平"},{"id":"q-06-0066","t":"加快形成绿色生产方式和生活方式，厚植高质量发展的绿色底色。","author":"习近平"},{"id":"q-06-0067","t":"要推动形成绿色生活方式。大力倡导简约适度、绿色低碳、文明健康的生活理念和消费方式，让绿色出行、节水节电、“光盘行动”、垃圾分类等成为习惯，各级党政机关和国有企事业单位要走在前列。","author":"习近平"},{"id":"q-06-0068","t":"国外名言人靠自然界生活。","author":"马克思"},{"id":"q-06-0069","t":"大力推动钢铁、有色、石化、化工、建材、造纸、印染等行业绿色低碳转型，推广节能低碳和清洁生产技术装备，推进工艺流程更新升级。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0070","t":"推广低碳交通运输工具。大力推广新能源汽车，推动城市公共服务车辆电动化替代。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0071","t":"发挥数字技术在提高资源效率、环境效益、管理效能等方面的赋能作用，加速生产方式数字化绿色化协同转型。","author":"《工业和信息化部等七部门关于加快推动制造业绿色化发展的指导意见》"},{"id":"q-06-0072","t":"面向重点行业领域在生产制造全流程拓展“新一代信息技术+绿色低碳”典型应用场景，提高全要素生产率。","author":"《工业和信息化部等七部门关于加快推动制造业绿色化发展的指导意见》"},{"id":"q-06-0073","t":"紧紧围绕能源生产、交通运输、城乡建设等全社会各领域绿色消费需求，加大绿色产品供给，培育供需深度融合新模式，实现供需两侧协同发力，支撑经济社会绿色低碳转型。","author":"《工业和信息化部等七部门关于加快推动制造业绿色化发展的指导意见》"},{"id":"q-06-0074","t":"建立健全社区人居环境建设和整治制度，促进社区节能节水、绿化环卫、垃圾分类、设施维护等工作有序推进。","author":"《绿色生活创建行动总体方案》"},{"id":"q-06-0075","t":"建设好生态宜居的美丽乡村，让广大农民在乡村振兴中有更多获得感、幸福感。","author":"习近平"},{"id":"q-06-0076","t":"要加强农村生态文明建设，保持战略定力，以钉钉子精神推进农业面源污染防治，加强土壤污染、地下水超采、水土流失等治理和修复。","author":"习近平"},{"id":"q-06-0077","t":"要推动乡村生态振兴，坚持绿色发展，加强农村突出环境问题综合治理，扎实实施农村人居环境整治三年行动计划，推进农村“厕所革命”，完善农村生活设施，打造农民安居乐业的美丽家园，让良好生态成为乡村振兴支撑点。","author":"习近平"},{"id":"q-06-0078","t":"要优化镇村布局规划，统筹乡村基础设施和公共服务体系建设，深入实施农村人居环境整治提升行动，加快建设宜居宜业和美乡村。","author":"习近平"},{"id":"q-06-0079","t":"深入实施农村人居环境整治提升行动。因地制宜推进生活污水垃圾治理和农村改厕，完善农民参与和长效管护机制。","author":"《中央农办、农业农村部、国家发展改革委关于深入学习浙江“千村示范、万村整治”工程经验扎实推进农村人居环境整治工作的报告》"},{"id":"q-06-0080","t":"根据乡村振兴战略要求，美丽乡村建设需要，将村庄分类按照集聚提升类、特色保护类、城郊融合类、搬迁撤并类、其他类细化到自然村。","author":"《安徽省“十四五”美丽乡村建设规划》"},{"id":"q-06-0081","t":"继续把中心村建设作为深化美丽乡村建设的重要任务，结合自身实际，把握时序进度，充分调动农民积极性，用“绣花”功夫建设美丽乡村。","author":"《安徽省“十四五”美丽乡村建设规划》"},{"id":"q-06-0082","t":"积极争取中央财政支持，支持各地统筹用好一般公共预算、土地出让收入、政府债券等渠道资金，整合相关涉农资金，进一步引导和调动金融及社会资本支持美丽乡村建设。","author":"《安徽省“十四五”美丽乡村建设规划》"},{"id":"q-06-0083","t":"绿遍山原白满川，子规声里雨如烟。","author":"宋·翁卷《乡村四月》"},{"id":"q-06-0084","t":"牧童归去横牛背，短笛无腔信口吹。","author":"宋·雷震《村晚》"},{"id":"q-06-0085","t":"独出前门望野田，月明荞麦花如雪。","author":"唐·白居易《村夜》"},{"id":"q-06-0086","t":"要高度重视海洋生态文明建设，加强海洋环境污染防治，保护海洋生物多样性，实现海洋资源有序开发利用，为子孙后代留下一片碧海蓝天。","author":"习近平"},{"id":"q-06-0087","t":"要把海洋生态文明建设纳入海洋开发总布局之中，坚持开发和保护并重、污染防治和生态修复并举。","author":"习近平"},{"id":"q-06-0088","t":"以海湾为基本单元，“一湾一策”协同推进近岸海域污染防治、生态保护修复和岸滩环境整治，不断提升红树林等重要海洋生态系统质量和稳定性。","author":"习近平"},{"id":"q-06-0089","t":"要发挥海洋资源丰富的得天独厚优势，经略海洋、向海图强，打造世界级海洋港口群，打造现代海洋经济发展高地。","author":"习近平"},{"id":"q-06-0090","t":"海洋孕育了生命、联通了世界、促进了发展。","author":"习近平"},{"id":"q-06-0091","t":"海洋约占地球表面积的71%，是生命的摇篮、人类文明的源泉。","author":"《中国的海洋生态环境保护》"},{"id":"q-06-0092","t":"中国是海洋生态环境保护的坚定推动者和积极行动者，保护好海洋生态环境关乎美丽中国和海洋强国建设。","author":"《中国的海洋生态环境保护》"},{"id":"q-06-0093","t":"健全海洋资源开发保护制度，系统谋划海洋开发利用，推进陆海协同可持续发展。","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-06-0094","t":"庄严的大海产生蛟龙和鲸鲵，清浅的小河里只有一些供鼎俎美味的鱼虾。","author":"莎士比亚"},{"id":"q-06-0095","t":"大海能冲刷掉人类的污垢。","author":"欧里庇得斯"},{"id":"q-06-0096","t":"陆地上存在着大海所不知道的危险。","author":"艾利斯"},{"id":"q-06-0097","t":"领导讲话坚决打赢蓝天保卫战是重中之重，要以空气质量明显改善为刚性要求，强化联防联控，基本消除重污染天气，还老百姓蓝天白云、繁星闪烁。","author":"习近平"},{"id":"q-06-0098","t":"动细颗粒物（PM2.5）浓度降低，推进厨房通风改造和炉灶改造，减少室内外空气污染。","author":"《健康中国行动——慢性呼吸系统疾病防治行动实施方案（2024—2030年）》"},{"id":"q-06-0099","t":"国家加强对成渝地区、长江中游城市群、东北地区、天山北坡城市群等区域大气污染防治协作的指导，将粤港澳大湾区作为空气质量改善先行示范区。","author":"《空气质量持续改善行动计划》"},{"id":"q-06-0100","t":"建立健全省市县三级重污染天气应急预案体系，明确地方各级政府部门责任分工，规范重污染天气预警启动、响应、解除工作流程。","author":"《空气质量持续改善行动计划》"},{"id":"q-06-0101","t":"完善城市空气质量监测网络，基本实现县城全覆盖，加强数据联网共享。","author":"《空气质量持续改善行动计划》"},{"id":"q-06-0102","t":"将空气质量改善目标完成情况作为深入打好污染防治攻坚战成效考核的重要内容。","author":"《空气质量持续改善行动计划》"},{"id":"q-06-0103","t":"强化公民环境意识，推动形成简约适度、绿色低碳、文明健康的生活方式，共同改善空气质量。","author":"《空气质量持续改善行动计划》"},{"id":"q-06-0104","t":"空山新雨后，天气晚来秋。","author":"唐·王维《山居秋暝》"},{"id":"q-06-0105","t":"宿雨朝来歇，空山秋气清。","author":"唐·李端《茂陵山行陪韦金部》"},{"id":"q-06-0106","t":"秋夜凉风起，清气荡暄浊。","author":"魏晋·张协《杂诗·秋夜凉风起》"},{"id":"q-06-0107","t":"加快国家生物多样性保护立法步伐，划定生态保护红线，建立国家公园体系，实施生物多样性保护重大工程，提高社会参与和公众意识。","author":"习近平"},{"id":"q-06-0108","t":"我们要以自然之道，养万物之生，从保护自然中寻找发展机遇，实现生态环境保护和经济高质量发展双赢。","author":"习近平"},{"id":"q-06-0109","t":"全球物种灭绝速度不断加快，生物多样性丧失和生态系统退化对人类生存和发展构成重大风险。","author":"习近平"},{"id":"q-06-0110","t":"第一次工业革命以来，人类利用自然的能力不断提高，但过度开发也导致生物多样性减少，迫使野生动物迁徙，增加野生动物体内病原的扩散传播。","author":"习近平"},{"id":"q-06-0111","t":"生物多样性既是可持续发展基础，也是目标和手段。我们要以自然之道，养万物之生，从保护自然中寻找发展机遇，实现生态环境保护和经济高质量发展双赢。","author":"习近平"},{"id":"q-06-0112","t":"我们要推进生物多样性保护全球进程，将雄心转化为行动，支持发展中国家提升能力，协同应对气候变化、生物多样性丧失等全球性挑战。","author":"习近平"},{"id":"q-06-0113","t":"加强生物多样性保护基础建设，开展生物多样性本底调查与编目，完成高等植物、脊椎动物和大型真菌受威胁现状评估，发布濒危物种名录。","author":"《中国生物多样性保护战略与行动计划》（2011-2030年）"},{"id":"q-06-0114","t":"坚持以就地保护为主，迁地保护为辅，两者相互补充。","author":"《中国生物多样性保护战略与行动计划》（2011-2030年）"},{"id":"q-06-0115","t":"开展多种形式的生物多样性保护宣传教育活动，引导公众积极参与生物多样性保护，加强学校的生物多样性科普教育。","author":"《中国生物多样性保护战略与行动计划》（2011-2030年）"},{"id":"q-06-0116","t":"在经济社会发展中优先考虑生物多样性保护，采取积极措施，对重要生态系统、生物物种及遗传资源实施有效保护，保障生态安全。","author":"《中国生物多样性保护战略与行动计划》（2011-2030年）"},{"id":"q-06-0117","t":"禁止掠夺性开发生物资源，促进生物资源可持续利用技术的研发与推广，科学、合理和有序地利用生物资源。","author":"《中国生物多样性保护战略与行动计划》（2011-2030年）"},{"id":"q-06-0118","t":"要从落实城市主体责任、推动群众习惯养成、加快分类设施建设、完善配套支持政策等方面入手，加快构建以法治为基础、政府推动、全民参与、城乡统筹、因地制宜的垃圾分类长效机制，树立科学理念，分类指导，加强全链条管理。","author":"习近平"},{"id":"q-06-0119","t":"推行垃圾分类，关键是要加强科学管理、形成长效机制、推动习惯养成。","author":"习近平"},{"id":"q-06-0120","t":"要加快建立分类投放、分类收集、分类运输、分类处理的垃圾处理系统，形成以法治为基础、政府推动、全民参与、城乡统筹、因地制宜的垃圾分类制度。","author":"习近平"},{"id":"q-06-0121","t":"实行垃圾分类，关系广大人民群众生活环境，关系节约使用资源，也是社会文明水平的一个重要体现。","author":"习近平"},{"id":"q-06-0122","t":"推进农村生活污水治理。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-06-0123","t":"加快完善生活垃圾分类设施体系，合理布局建设收集点、收集站、中转压缩站等设施，健全收集运输网络。","author":"《环境基础设施建设水平提升行动（2023—2025年）》"},{"id":"q-06-0124","t":"有序推进厨余垃圾处理设施建设，提升废弃油脂等厨余垃圾能源化、资源化利用水平。","author":"《国务院办公厅关于加快构建废弃物循环利用体系的意见》"},{"id":"q-06-0125","t":"加快城镇生活垃圾处理设施建设，补齐县级地区生活垃圾焚烧处理能力短板。","author":"《国务院办公厅关于加快构建废弃物循环利用体系的意见》"},{"id":"q-06-0126","t":"修订建筑垃圾管理规定，完善建筑垃圾管理体系。","author":"《国务院办公厅关于加快构建废弃物循环利用体系的意见》"}],"文化发展篇":[{"id":"q-07-0000","t":"推进生活垃圾分类，提升资源化利用率","author":"《中共中央国务院关于加快经济社会发展全面绿色转型的意见》"},{"id":"q-07-0001","t":"只有全面深入了解中华文明的历史，才能更有效地推动中华优秀传统文化创造性转化、创新性发展，更有力地推进中国特色社会主义文化建设，建设中华民族现代文明。","author":"习近平"},{"id":"q-07-0002","t":"历史文化遗产是不可再生、不可替代的宝贵资源，要始终把保护放在第一位。","author":"习近平"},{"id":"q-07-0003","t":"要妥善处理好保护和发展的关系，注重延续城市历史文脉，像对待“老人”一样尊重和善待城市中的老建筑，保留城市历史文化记忆，让人们记得住历史、记得住乡愁，坚定文化自信，增强家国情怀。","author":"习近平"},{"id":"q-07-0004","t":"中华文明具有突出的创新性，从根本上决定了中华民族守正不守旧、尊古不复古的进取精神，决定了中华民族不惧新挑战、勇于接受新事物的无畏品格。","author":"习近平"},{"id":"q-07-0005","t":"实施中华优秀传统文化传承发展工程，研究和挖掘中华传统文化的优秀基因和时代价值，推动中华优秀传统文化创造性转化、创新性发展，繁荣发展社会主义先进文化，构建和运用中华文化特征、中华民族精神、中国国家形象的表达体系，不断增强各族群众的中华文化认同。","author":"习近平"},{"id":"q-07-0006","t":"中华优秀传统文化是我们最深厚的文化软实力，也是中国特色社会主义植根的文化沃土。","author":"习近平"},{"id":"q-07-0007","t":"非物质文化遗产是中华优秀传统文化的重要组成部分，是中华文明绵延传承的生动见证，是连结民族情感、维系国家统一的重要基础。","author":"中共中央办公厅国务院办公厅印发《关于进一步加强非物质文化遗产保护工作的意见》"},{"id":"q-07-0008","t":"支持历史文化名城、名镇、名村和街区内部历史建筑及公有建筑修缮及抗震加固、传统街巷立面路面整治改造、配套基础设施和公共服务设施建设、消防安防设施建设、数字化展示利用设施建设等整体性保护利用。","author":"《国家发展改革委等部门关于修订印发〈文化保护传承利用工程实施方案〉的通知》"},{"id":"q-07-0009","t":"突出专业化保护，正确处理保护与利用、保护与发展、保护与开发等文化遗产保护传承中的重大关系。","author":"《国家发展改革委等部门关于修订印发〈文化保护传承利用工程实施方案〉的通知》"},{"id":"q-07-0010","t":"突出特色化展示，以特色文化为基础促进传统与现代的结合，避免过度开发，杜绝拆真建假。","author":"《国家发展改革委等部门关于修订印发〈文化保护传承利用工程实施方案〉的通知》"},{"id":"q-07-0011","t":"讲好中国故事，传播好中国声音，展示真实、立体、全面的中国，是加强我国国际传播能力建设的重要任务。","author":"习近平"},{"id":"q-07-0012","t":"要拓展影响知识产权国际舆论的渠道和方式，讲好中国知识产权故事，展示文明大国、负责任大国形象。","author":"习近平"},{"id":"q-07-0013","t":"长期以来，中华文明同世界其他文明互通有无、交流借鉴，向世界贡献了深刻的思想体系、丰富的科技文化艺术成果、独特的制度创造，深刻影响了世界文明进程。","author":"习近平"},{"id":"q-07-0014","t":"要更好推动中华文化走出去，以文载道、以文传声、以文化人，向世界阐释推介更多具有中国特色、体现中国精神、蕴藏中国智慧的优秀文化。","author":"习近平"},{"id":"q-07-0015","t":"要加快构建中国话语和中国叙事体系，用中国理论阐释中国实践，用中国实践升华中国理论，打造融通中外的新概念、新范畴、新表述，更加充分、更加鲜明地展现中国故事及其背后的思想力量和精神力量。","author":"习近平"},{"id":"q-07-0016","t":"建设中文传播平台，构建中国语言文化全球传播体系和国际中文教育标准体系。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-07-0017","t":"坚持正确政治方向、舆论导向和价值取向，坚持马克思主义新闻观，坚持团结稳定鼓劲、正面宣传为主，唱响主旋律，激发正能量，发展壮大主流媒体，不断增强新闻舆论传播力、引导力、影响力、公信力。","author":"《“十四五”文化发展规划》"},{"id":"q-07-0018","t":"加快建设一批有全国影响力的文化中心城市、特色文化强市。","author":"《“十四五”文化发展规划》"},{"id":"q-07-0019","t":"统筹推进对外宣传、对外文化交流和文化贸易，增强国际传播影响力、中华文化感召力、中国形象亲和力、中国话语说服力、国际舆论引导力，促进民心相通，构建人文共同体。","author":"《“十四五”文化发展规划》"},{"id":"q-07-0020","t":"在新的历史起点上继续推动文化繁荣、建设文化强国、建设中华民族现代文明，要坚定文化自信，坚持走自己的路，立足中华民族伟大历史实践和当代实践，用中国道理总结好中国经验，把中国经验提升为中国理论，实现精神上的独立自主。","author":"习近平"},{"id":"q-07-0021","t":"要坚定文化自信的首要任务，就是立足中华民族伟大历史实践和当代实践，用中国道理总结好中国经验，把中国经验提升为中国理论，既不盲从各种教条，也不照搬外国理论，实现精神上的独立自主。","author":"习近平"},{"id":"q-07-0022","t":"中国共产党历来重视文化，新时代我们在道路自信、理论自信、制度自信的基础上增加了文化自信。文化自信就来自我们的文化主体性。","author":"习近平"},{"id":"q-07-0023","t":"各族文化交相辉映，中华文化历久弥新，这是今天我们强大文化自信的根源。","author":"习近平"},{"id":"q-07-0024","t":"文化自信，是更基础、更广泛、更深厚的自信。","author":"习近平"},{"id":"q-07-0025","t":"腹有诗书气自华。","author":"宋·苏轼《和董传留别》"},{"id":"q-07-0026","t":"自知自信融融乐，无虑无营盎盎春。","author":"袁甫《魏鸿禧叙别二首》"},{"id":"q-07-0027","t":"自信人生二百年，会当水击三千里！","author":"毛泽东《七古·残句》"},{"id":"q-07-0028","t":"我们比历史上任何时期都更加坚定文化自信，更有信心更有能力铸就中华文化新辉煌。","author":"《“十四五”文化发展规划》"},{"id":"q-07-0029","t":"健全社会心理服务体系和疏导机制、危机干预机制，塑造自尊自信、理性平和、积极向上的社会心态。","author":"《“十四五”文化发展规划》"},{"id":"q-07-0030","t":"坚定中华文化立场和文化自信，深入开展各种形式的人文交流活动，以文载道、以文传声、以文化人。面向不同国家和区域，搭建开放包容的文明对话平台，促进文明互学互鉴、共同发展。深化政府和民间对外交流。","author":"《“十四五”文化发展规划》"},{"id":"q-07-0031","t":"中华文明的包容性，从根本上决定了中华民族交往交流交融的历史取向，决定了中国各宗教信仰多元并存的和谐格局，决定了中华文化对世界文明兼收并蓄的开放胸怀。","author":"习近平"},{"id":"q-07-0032","t":"要牢牢把握舆论主动权和主导权，让互联网成为构筑各民族共有精神家园、铸牢中华民族共同体意识的最大增量。","author":"习近平"},{"id":"q-07-0033","t":"文明因交流而多彩，文明因互鉴而丰富。","author":"习近平"},{"id":"q-07-0034","t":"文明交流互鉴应该是对等的、平等的，应该是多元的、多向的，而不应该是强制的、强迫的，不应该是单一的、单向的。","author":"习近平"},{"id":"q-07-0035","t":"国与国相处，要把平等相待、互尊互信挺在前面。要弘扬和平、发展、公平、正义、民主、自由的全人类共同价值，倡导不同文明交流互鉴。","author":"习近平"},{"id":"q-07-0036","t":"积极推进网络文化交流互鉴。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-07-0037","t":"深化公共卫生、数字经济、绿色发展、科技教育、文化艺术等领域人文合作，加强议会、政党、民间组织往来，密切妇女、青年、残疾人等群体交流，形成多元互动的人文交流格局。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目"},{"id":"q-07-0038","t":"加强对外文化交流和多层次文明对话，创新推进国际传播，利用网上网下，讲好中国故事，传播好中国声音，促进民心相通。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-07-0039","t":"文化虽然不像文明那样具有地区的广泛性，但是，它相应地和各个国家的每一个人的喜、怒、哀、乐具有更深刻的联系。","author":"森谷正规"},{"id":"q-07-0040","t":"在这富有历史背景、富有高度私人秘密性的社会，人类的文化应是多彩多姿的。","author":"赫尔曼·黑塞"},{"id":"q-07-0041","t":"探索文化和科技融合的有效机制，加快发展新型文化业态，形成更多新的文化产业增长点。","author":"习近平"},{"id":"q-07-0042","t":"要推动文化产业高质量发展，健全现代文化产业体系和市场体系，推动各类文化市场主体发展壮大，培育新型文化业态和文化消费模式，以高质量文化供给增强人们的文化获得感、幸福感。","author":"习近平"},{"id":"q-07-0043","t":"文化产业既有意识形态属性，又有市场属性，但意识形态属性是本质属性。一定要牢牢把握正确导向，坚持守正创新，确保文化产业持续健康发展。","author":"习近平"},{"id":"q-07-0044","t":"文化产业是一个朝阳产业。现在文化和技术深入结合，文化产业快速发展，从业人员也在不断增长，这既是一个迅速发展的产业，也是一个巨大的人才蓄水池，必须格外重视。","author":"习近平"},{"id":"q-07-0045","t":"开展文化产业赋能乡村振兴试点，是强化以城带乡、城乡互促，推动乡村人文资源和自然资源有效保护利用的有力举措；是促进一二三产业融合发展，贯通产加销、融合农文旅的重要工程；是传承发展农耕文明，激发优秀乡土文化活力的具体行动。","author":"《关于开展文化产业赋能乡村振兴试点的通知》"},{"id":"q-07-0046","t":"积极探索推动“文化产业特派员”、文化和生态资源价值实现机制等创新发展制度，建立产业发展利益联结机制，让农民更多分享产业增值收益。","author":"《关于开展文化产业赋能乡村振兴试点的通知》"},{"id":"q-07-0047","t":"大力推动文化产业特色乡镇、特色村落建设，推动实施一批具有较强带动作用的特色产业、重点项目。","author":"《关于开展文化产业赋能乡村振兴试点的通知》"},{"id":"q-07-0048","t":"大力支持影视产业优质知识产权的应用和衍生开发。","author":"《上海市青浦区关于促进影视产业高质量发展实施细则》"},{"id":"q-07-0049","t":"深刻把握数字文化内容属性，加强原创能力建设，创造更多既能满足人民文化需求、又能增强人民精神力量的数字文化产品。","author":"《关于推动数字文化产业高质量发展的意见》"},{"id":"q-07-0050","t":"主动对接新基建，用好新基建政策、平台、技术，提升数字文化产业发展水平。","author":"《关于推动数字文化产业高质量发展的意见》"},{"id":"q-07-0051","t":"文化产业和旅游产业密不可分，要坚持以文塑旅、以旅彰文，推动文化和旅游融合发展，让人们在领略自然之美中感悟文化之美、陶冶心灵之美。","author":"习近平"},{"id":"q-07-0053","t":"让旅游成为人们感悟中华文化、增强文化自信的过程。","author":"习近平"},{"id":"q-07-0054","t":"积极推进文化和旅游深度融合发展，建设一批具有自然山水特色和历史人文内涵的滨江城市、小城镇和美丽乡村。","author":"习近平"},{"id":"q-07-0055","t":"旅游是不同国家、不同文化交流互鉴的重要渠道，是发展经济、增加就业的有效手段，也是提高人民生活水平的重要产业。","author":"习近平"},{"id":"q-07-0056","t":"实施国家旅游风景道工程，制定国家旅游风景道标准，在保障安全通行的前提下推出一批配套服务好、道路风景美、文化特色鲜明的国家旅游风景道。","author":"《关于推进旅游公共服务高质量发展的指导意见》"},{"id":"q-07-0057","t":"拓展高速公路服务区文化和旅游公共服务功能，形成一批特色主题服务区。","author":"《关于推进旅游公共服务高质量发展的指导意见》"},{"id":"q-07-0058","t":"促进文化和旅游公共服务设施功能融合。鼓励有条件的地方推动公共图书馆、文化馆（站）、基层综合性文化服务中心和旅游服务中心一体化建设。","author":"《关于推进旅游公共服务高质量发展的指导意见》"},{"id":"q-07-0059","t":"在旅游发展中，要尊重非物质文化遗产的形式和内涵，保护非物质文化遗产的传承环境和空间，保障传承群体的合法权益，为传承群体参与旅游发展提供便利条件，促进非物质文化遗产长久保护和永续利用。","author":"《文化和旅游部关于推动非物质文化遗产与旅游深度融合发展的通知》"},{"id":"q-07-0060","t":"在非物质文化遗产保护传承中，要坚持创造性转化和创新性发展，积极适应当代旅游需求和旅游所带来的生产生活方式的变化，不断提高传承发展利用水平，持续为旅游提供丰富的文化资源。","author":"《文化和旅游部关于推动非物质文化遗产与旅游深度融合发展的通知》"},{"id":"q-07-0061","t":"要推进城乡公共文化服务体系一体建设，优化城乡文化资源配置，完善农村文化基础设施网络，增加农村公共文化服务总量供给，缩小城乡公共文化服务差距。","author":"习近平"},{"id":"q-07-0062","t":"要推动公共文化服务标准化、均等化，坚持政府主导、社会参与、重心下移、共建共享，完善公共文化服务体系，提高基本公共文化服务的覆盖面和适用性。","author":"习近平"},{"id":"q-07-0063","t":"优化城乡文化资源配置，推进城乡公共文化服务体系一体建设。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-07-0064","t":"创新公共文化服务运行机制，鼓励社会力量参与公共文化服务供给和设施建设运营。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-07-0065","t":"实施文化品牌战略，打造一批有影响力、代表性的文化品牌。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-07-0066","t":"培育骨干文化企业，规范发展文化产业园区，推动区域文化产业带建设。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-07-0067","t":"坚持为人民服务、为社会主义服务的方向，坚持百花齐放、百家争鸣的方针，加强公共文化服务体系建设和体制机制创新，强化中华文化传播推广和文明交流互鉴，更好保障人民文化权益。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-07-0068","t":"搭建各类民间文化艺术团体与旅游经营场所的沟通桥梁，进一步丰富旅游场所的文化内涵。","author":"《关于推进旅游公共服务高质量发展的指导意见》"},{"id":"q-07-0069","t":"推动广场舞、村晚、村超、“村BA”、艺术节庆、群众歌咏等文化体育活动，民间文化艺术、群星奖作品、文化讲座、美术展览、优秀剧目等优质文化资源进景区等旅游场所。","author":"《关于推进旅游公共服务高质量发展的指导意见》"},{"id":"q-07-0070","t":"增强公共文化场所旅游吸引力。推动博物馆、美术馆、公共图书馆、文化馆、纪念馆、剧院、非物质文化遗产展示场所、考古遗址公园等完善旅游服务配套设施，提升旅游公共服务水平，培育主客共享的美好生活新空间。","author":"《关于推进旅游公共服务高质量发展的指导意见》"},{"id":"q-07-0071","t":"出礼入刑、隆礼重法的治国策略，民惟邦本、本固邦宁的民本理念，天下无讼、以和为贵的价值追求，德主刑辅、明德慎罚的慎刑思想，援法断罪、罚当其罪的平等观念，保护鳏寡孤独、老幼妇残的恤刑原则，等等，都彰显了中华优秀传统法律文化的智慧。","author":"习近平"},{"id":"q-07-0072","t":"中华法系源远流长，中华优秀传统法律文化蕴含丰富法治思想和深邃政治智慧，是中华文化的瑰宝。要积极推动中华优秀传统法律文化创造性转化、创新性发展，赋予中华法治文明新的时代内涵，激发起蓬勃生机。","author":"习近平"},{"id":"q-07-0073","t":"我们要坚持走中国特色社会主义法治道路，建设中国特色社会主义法治体系、建设社会主义法治国家，围绕保障和促进社会公平正义，坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设，全面推进科学立法、严格执法、公正司法、全民守法，全面推进国家各方面工作法治化。","author":"习近平"},{"id":"q-07-0074","t":"治乱决缪，绌羡齐非，一民之轨，莫如法。","author":"战国·韩非《韩非子·有度》"},{"id":"q-07-0075","t":"法者，所以兴功惧暴也；律者，所以定分止争也；令者，所以令人知事也。","author":"春秋·管仲《管子·七臣七主》"},{"id":"q-07-0076","t":"法者，国家所以布大信于天下。","author":"《资治通鉴》"},{"id":"q-07-0077","t":"为国也，观俗立法则治，察国事本则宜。不观时俗，不察国本，则其法立而民乱，事剧而功寡。","author":"《商君书》"},{"id":"q-07-0078","t":"治故事。","author":"《国务院2024年度立法工作计划》"},{"id":"q-07-0079","t":"坚持以人民为中心，做到社会主义法治文化建设为了人民、依靠人民，不断满足人民日益增长的对民主、法治、公平、正义的需要。","author":"《关于加强社会主义法治文化建设的意见》"},{"id":"q-07-0080","t":"加强中国特色新型法治智库建设，加大对重大法治理论、法治文化研究课题支持力度，加强法律实务部门和理论研究部门的交流互动，为法治实践提供高质量的决策参考。","author":"《关于加强社会主义法治文化建设的意见》"},{"id":"q-07-0081","t":"要打造精品展陈，坚持政治性、思想性、艺术性相统一，用史实说话，增强表现力、传播力、影响力，生动传播红色文化。","author":"习近平"},{"id":"q-07-0082","t":"要用好这样的红色资源，讲好红色故事，搞好红色教育，让红色基因代代相传。","author":"习近平"},{"id":"q-07-0083","t":"红色资源是我们党艰辛而辉煌奋斗历程的见证，是最宝贵的精神财富。红色血脉是中国共产党政治本色的集中体现，是新时代中国共产党人的精神力量源泉。","author":"习近平"},{"id":"q-07-0084","t":"红色是中国共产党、中华人民共和国最鲜亮的底色，在我国960多万平方公里的广袤大地上红色资源星罗棋布，在我们党团结带领中国人民进行百年奋斗的伟大历程中红色血脉代代相传。","author":"习近平"},{"id":"q-07-0085","t":"要教育引导全党大力发扬红色传统、传承红色基因，赓续共产党人精神血脉，始终保持革命者的大无畏奋斗精神，鼓起迈进新征程、奋进新时代的精气神。","author":"习近平"},{"id":"q-07-0086","t":"红色江山来之不易，守好江山责任重大。","author":"习近平"},{"id":"q-07-0087","t":"红色资源保护利用专项规划应当与生态环境保护规划、历史文化名城名镇名村保护规划、乡村振兴规划、文化和旅游发展规划以及大运河国家文化公园建设保护、长江国家文化公园建设保护等其他专项规划相衔接。","author":"《江苏省红色资源保护利用条例（2024）》"},{"id":"q-07-0088","t":"县级以上地方人民政府应当推进红色资源传承利用与旅游融合发展，依托红色资源发展红色旅游，加强红色旅游景区建设，完善道路、通讯等基础设施和公共文化服务设施，优化提升红色旅游服务，打造红色文化旅游品牌。","author":"《江苏省红色资源保护利用条例"},{"id":"q-07-0089","t":"红色资源主题展览应当以史实为基础，坚持政治性、思想性、艺术性相统一，做到主题突出、导向鲜明、内涵丰富。","author":"《江苏省红色资源保护利用条例（2024）》"},{"id":"q-07-0090","t":"红色资源主题展览应当坚持节俭办展、绿色办展，不断丰富陈列展览内容，创新载体形式，运用现代科技手段，增强互动性、体验感。","author":"《江苏省红色资源保护利用条例"},{"id":"q-07-0091","t":"统筹推进革命老区振兴，因地制宜发展特色产业，传承弘扬红色文化。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-07-0092","t":"文化文艺工作者、哲学社会科学工作者都肩负着启迪思想、陶冶情操、温润心灵的重要职责，承担着以文化人、以文育人、以文培元的使命。","author":"习近平"},{"id":"q-07-0093","t":"反映时代是文艺工作者的使命。广大文艺工作者要把握时代脉搏，承担时代使命，聆听时代声音，勇于回答时代课题。","author":"习近平"},{"id":"q-07-0094","t":"社会主义文艺，从本质上讲，就是人民的文艺。","author":"习近平"},{"id":"q-07-0095","t":"文化文艺工作者要走进实践深处，观照人民生活，表达人民心声，用心用情用功抒写人民、描绘人民、歌唱人民。","author":"习近平"},{"id":"q-07-0096","t":"广大文艺工作者要紧跟时代步伐，从时代的脉搏中感悟艺术的脉动，把艺术创造向着亿万人民的伟大奋斗敞开，向着丰富多彩的社会生活敞开，从时代之变、中国之进、人民之呼中提炼主题、萃取题材，展现中华历史之美、山河之美、文化之美，抒写中国人民奋斗之志、创造之力、发展之果，全方位全景式展现新时代的精神气象。","author":"习近平"},{"id":"q-07-0097","t":"汝果欲学诗，工夫在诗外。","author":"宋·陆游《示子聿》"},{"id":"q-07-0098","t":"清水出芙蓉，天然去雕饰。","author":"唐·李白《论诗》"},{"id":"q-07-0099","t":"艺术是生活的点缀，是引向生命的一种诱惑。","author":"《托尔斯泰传》"},{"id":"q-07-0100","t":"把提高质量作为文艺作品的生命线，提高文艺原创能力。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"}],"民生保障篇":[{"id":"q-08-0000","t":"精品。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-08-0001","t":"要切实保障和改善民生，尽力而为、量力而行，多办顺民意、惠民生、暖民心的实事，扎实解决群众急难愁盼问题。","author":"习近平"},{"id":"q-08-0002","t":"要加强普惠性、基础性、兜底性民生事业建设，着力解决人民群众急难愁盼问题，扎实推进各族人民共同富裕。","author":"习近平"},{"id":"q-08-0003","t":"中国式现代化，民生为大。党和政府的一切工作，都是为了老百姓过上更加幸福的生活。希望各级党委和政府都能为解决民生问题投入更多的财力物力，每年办一些民生实事，不断增强人民群众的获得感幸福感安全感。","author":"习近平"},{"id":"q-08-0004","t":"国泰民安，民安才能国泰，党中央和各级党委、政府时刻记挂着大家的安危冷暖，也希望乡亲们依靠自己的双手重建美好家园，创造幸福生活。","author":"习近平"},{"id":"q-08-0005","t":"老百姓的幸福生活是干出来的。我们要靠实干奋斗，实现中华民族伟大复兴，使人民群众生活越来越好。","author":"习近平"},{"id":"q-08-0006","t":"要从人民的整体利益、根本利益、长远利益出发谋划和推进改革，走好新时代党的群众路线，注重从就业、增收、入学、就医、住房、办事、托幼养老以及生命财产安全等老百姓急难愁盼中找准改革的发力点和突破口，多推出一些民生所急、民心所向的改革举措，多办一些惠民生、暖民心、顺民意的实事，使改革能够让人民群众有更多获得感、幸福感、安全感。","author":"习近平"},{"id":"q-08-0007","t":"我们的目标很宏伟，也很朴素，归根到底就是让老百姓过上更好的日子。孩子的抚养教育，年轻人的就业成才，老年人的就医养老，是家事也是国事，大家要共同努力，把这些事办好。","author":"习近平"},{"id":"q-08-0008","t":"凡治国之道，必先富民。","author":"《管子·治国第四十八》"},{"id":"q-08-0009","t":"治国有常，而利民为本。","author":"《淮南子·汜论训》"},{"id":"q-08-0010","t":"统筹城乡、公平统一、可持续的多层次社会保障体系。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-08-0011","t":"健全为民办事长效机制和政策体系，将目标清单化、清单行动化、行动项目化，统筹需求与可能，一件事一件事办好、办出实效。","author":"《广东省“民生十大工程”五年行动计划（2023—2027年）》"},{"id":"q-08-0012","t":"医疗卫生服务直接关系人民身体健康。要推动医疗卫生工作重心下移、医疗卫生资源下沉，推动城乡基本公共服务均等化，为群众提供安全有效方便价廉的公共卫生和基本医疗服务。","author":"习近平"},{"id":"q-08-0013","t":"看大病在本省解决，一般的病在市县解决，日常的头疼脑热在乡村解决。这个工作要在‘十四五’期间起步。研究改革的堵点在哪里，结合本地实际继续探索。","author":"习近平"},{"id":"q-08-0014","t":"要从保护人民健康、保障国家安全、维护国家长治久安的高度，把生物安全纳入国家安全体系，系统规划国家生物安全风险防控和治理体系建设，全面提高国家生物安全治理能力。","author":"习近平"},{"id":"q-08-0015","t":"广大医务工作者要恪守医德医风医道，修医德、行仁术，怀救苦之心、做苍生大医，努力为人民群众提供更加优质高效的健康服务。","author":"习近平"},{"id":"q-08-0016","t":"要继续加大医保改革力度，常态化制度化开展药品集中带量采购，健全重特大疾病医疗保险和救助制度，深化医保基金监管制度改革，守好人民群众的“保命钱”“救命钱”。","author":"习近平"},{"id":"q-08-0017","t":"人民的幸福生活，一个最重要的指标就是健康。健康是1，其他的都是后边的0，1没有了什么都没有了。我们在过去成绩的基础上，还是继续把卫生健康事业朝前发展。","author":"习近平"},{"id":"q-08-0018","t":"要把医药卫生体制改革纳入全面深化改革中同部署、同要求、同考核，支持地方因地制宜、差别化探索。","author":"习近平"},{"id":"q-08-0019","t":"凡为医之道，必先正己，然后正物。","author":"《医工论》"},{"id":"q-08-0020","t":"进则救世，退则救民；不能为良相，亦当为良医。","author":"东汉·张仲景《伤寒杂病论》"},{"id":"q-08-0021","t":"加快建设符合行业特点的科技创新体系，加强科技攻关，促进成果应用推广，助力开辟生命科学等未来产业新赛道。","author":"2024年全国卫生健康工作会议"},{"id":"q-08-0022","t":"以基层为重点推进服务能力建设。持续加强县医院能力建设，深入推进“千县工程”。","author":"2024年全国卫生健康工作会议"},{"id":"q-08-0023","t":"全面实施中医药振兴发展重大工程，加强国家中医优势专科建设，充分发挥中医药在治未病、康复以及儿童青少年近视、肥胖防治等方面的独特优势。","author":"2024年全国卫生健康工作会议"},{"id":"q-08-0024","t":"要坚持传统服务方式和智能化服务创新并行，针对老年人、残疾人等群体的特点，提供更加贴心暖心的社会保障服务。","author":"习近平"},{"id":"q-08-0025","t":"一个社会幸福不幸福，很重要的是看老年人幸福不幸福。","author":"习近平"},{"id":"q-08-0026","t":"老吾老，以及人之老；幼吾幼，以及人之幼。","author":"先秦·孟子及弟子《齐桓晋文之事》"},{"id":"q-08-0027","t":"使老有所终，壮有所用，幼有所长，鳏寡孤独废疾者，皆有所养。","author":"先秦·《礼记》"},{"id":"q-08-0028","t":"至庶无故，唯于孝。","author":"《诗经·小雅》"},{"id":"q-08-0029","t":"发展农村养老服务事关亿万农村老年人幸福生活，事关积极应对人口老龄化国家战略和乡村振兴战略顺利实施","author":"《关于加快发展农村养老服务的指导意见》"},{"id":"q-08-0030","t":"支持县域公办养老机构或其他管理服务水平高的民办养老机构、区域养老服务中心、村级邻里互助点、农村幸福院等依法组成服务联合体，连锁化、品牌化、集约化运营。","author":"《关于加快发展农村养老服务的指导意见》"},{"id":"q-08-0031","t":"应急管理部门、消防部门负责指导做好农村养老服务应急管理和消防安全工作，提升火灾防范和应急救援能力。","author":"《关于加快发展农村养老服务的指导意见》"},{"id":"q-08-0032","t":"推广“党建+农村养老服务”模式，依托村级党组织落实政府投放农村基层的养老服务资源。","author":"《关于加快发展农村养老服务的指导意见》"},{"id":"q-08-0033","t":"设是实施积极应对人口老龄化国家战略，实现基本公共服务均等化的重要任务。","author":"《关于推进基本养老服务体系建设的意见》"},{"id":"q-08-0034","t":"加强对大龄、残疾、较长时间失业等就业困难群体的帮扶，统筹用好公益性岗位，确保零就业家庭动态清零。","author":"习近平"},{"id":"q-08-0035","t":"要加快塑造素质优良、总量充裕、结构优化、分布合理的现代化人力资源，解决好人力资源供需不匹配这一结构性就业矛盾。","author":"习近平"},{"id":"q-08-0036","t":"健全劳动法律法规，规范新就业形态劳动基准，完善社会保障体系，维护劳动者合法权益。","author":"习近平"},{"id":"q-08-0037","t":"坚持把高校毕业生等青年群体就业作为重中之重，开发更多有利于发挥所学所长的就业岗位，鼓励青年投身重点领域、重点行业、城乡基层和中小微企业就业创业，拓宽市场化社会化就业渠道。","author":"习近平"},{"id":"q-08-0038","t":"要坚持以人民为中心的发展思想，全面贯彻劳动者自主就业、市场调节就业、政府促进就业和鼓励创业的方针，持续促进就业质的有效提升和量的合理增长，不断增强广大劳动者的获得感幸福感安全感，为以中国式现代化全面推进强国建设、民族复兴伟业提供有力支撑。","author":"习近平"},{"id":"q-08-0039","t":"要把稳就业工作摆在更加突出的位置，不断提高劳动者收入水平，构建多层次社会保障体系，改善劳动安全卫生条件，使广大劳动者共建共享改革发展成果，以更有效的举措不断推进共同富裕。","author":"习近平"},{"id":"q-08-0040","t":"深入分析一些行业出现用工缺口的原因，从破解“有活没人干”入手，解决“有人没活干”的问题。","author":"习近平"},{"id":"q-08-0041","t":"要坚定不移贯彻新发展理念，更加自觉地把高质量充分就业作为经济社会发展的优先目标，使高质量发展的过程成为就业提质扩容的过程，提高发展的就业带动力。","author":"习近平"},{"id":"q-08-0042","t":"要切实保障和改善民生，突出就业优先导向，促进中低收入群体增收，织密扎牢社会保障网。","author":"中共中央政治局会议"},{"id":"q-08-0043","t":"批优秀创业投资机构，支持中小型创业投资机构提升发展水平。","author":"《促进创业投资高质量发展的若干政策措施》"},{"id":"q-08-0044","t":"发展创业投资是促进科技、产业、金融良性循环的重要举措。","author":"《促进创业投资高质量发展的若干政策措施》"},{"id":"q-08-0045","t":"建设体育强国、健康中国，最根本的是增强人民体质、保障人民健康。这是全面建设社会主义现代化国家的一个重要方面。","author":"习近平"},{"id":"q-08-0046","t":"人民健康是社会文明进步的基础，是民族昌盛和国家富强的重要标志，也是广大人民群众的共同追求。","author":"习近平"},{"id":"q-08-0047","t":"现在孩子普遍眼镜化，这是我的隐忧。还有身体的健康程度，由于体育锻炼少，有所下降。文明其精神，野蛮其体魄，我说的‘野蛮其体魄’就是强身健体。","author":"习近平"},{"id":"q-08-0048","t":"忽略健康的人，就是等于在与自己的生命开玩笑。","author":"陶行知"},{"id":"q-08-0049","t":"人的健全，不但靠饮食，尤靠运动。","author":"蔡元培"},{"id":"q-08-0050","t":"欲文明其精神，先自野蛮其体魄；苟野蛮其体魄矣，则文明之精神随之。","author":"毛泽东《体育之研究》"},{"id":"q-08-0051","t":"提高健身设施适老化程度，研究推广适合老年人的体育健身休闲项目，组织开展适合老年人的赛事活动。","author":"《全民健身计划（2021—2025年）》"},{"id":"q-08-0052","t":"鼓励保险公司开发慢性呼吸系统疾病相关商业健康保险产品，与病前、病中、病后的健康管理深度融合，有效提高人民群众的健康水平。","author":"《健康中国行动——慢性呼吸系统疾病防治行动实施方案（2024—2030年）》"},{"id":"q-08-0053","t":"倡导健康生活方式，提倡科学运动与合理膳食。","author":"《健康中国行动——慢性呼吸系统疾病防治行动实施方案（2024—2030年）》"},{"id":"q-08-0054","t":"把满足群众健身需求作为工作出发点，广泛征询群众意见。","author":"《全民健身场地设施提升行动工作方案（2023-2025年）》"},{"id":"q-08-0055","t":"中央财政统筹利用现有资金渠道，发挥示范引领作用，支持健身设施建设和使用，推动广泛开展全民健身活动。","author":"《全民健身场地设施提升行动工作方案（2023-2025年）》"},{"id":"q-08-0056","t":"我牵挂受灾的地方。在咱们中国，人民群众遇到困难，还是要发挥我们社会主义优越性，就是一方有难，八方支援，国家全力支持。希望救灾重建工作圆满顺利。","author":"习近平"},{"id":"q-08-0057","t":"社会保障是保障和改善民生、维护社会公平、增进人民福祉的基本制度保障，是促进经济社会发展、实现广大人民群众共享改革发展成果的重要制度安排，是治国安邦的大问题。","author":"习近平"},{"id":"q-08-0058","t":"对困难群众，我们要格外关注、格外关爱、格外关心，时刻把他们的安危冷暖放在心上，关心他们的疾苦，千方百计帮助他们排忧解难。","author":"习近平"},{"id":"q-08-0059","t":"要深化社会救助制度改革，形成以基本生活救助、专项社会救助、急难社会救助为主体，社会力量参与为补充，覆盖全面、分层分类、综合高效的社会救助格局。","author":"习近平"},{"id":"q-08-0060","t":"要针对特困人员的特点和需求精准施策，按时足额发放各类救助金，强化临时救助，确保兜住底、兜准底、兜好底；要实现经济发展和民生改善良性循环。","author":"习近平"},{"id":"q-08-0061","t":"社会救助事关困难群众基本生活和衣食冷暖，是保障基本民生、促进社会公平、维护社会稳定的兜底性、基础性制度安排，也是我们党全心全意为人民服务根本宗旨的集中体现。","author":"《关于改革完善社会救助制度的意见》"},{"id":"q-08-0062","t":"坚持以人民为中心，把维护困难群众基本权益作为社会救助的根本出发点和落脚点，确保困难群众共享改革发展成果。","author":"《关于改革完善社会救助制度的意见》"},{"id":"q-08-0063","t":"构建综合救助格局。以增强社会救助及时性、有效性为目标，加快构建政府主导、社会参与、制度健全、政策衔接、兜底有力的综合救助格局。","author":"《关于改革完善社会救助制度的意见》"},{"id":"q-08-0064","t":"创新社会救助方式。积极发展服务类社会救助，形成“物质+服务”的救助方式。","author":"《关于改革完善社会救助制度的意见》"},{"id":"q-08-0065","t":"畅通急难社会救助申请和急难情况及时报告、主动发现渠道，建立健全快速响应、个案会商“救急难”工作机制。","author":"《关于改革完善社会救助制度的意见》"},{"id":"q-08-0067","t":"强教必先强师。要把加强教师队伍建设作为建设教育强国最重要的基础工作来抓，健全中国特色教师教育体系，大力培养造就一支师德高尚、业务精湛、结构合理、充满活力的高素质专业化教师队伍。","author":"习近平"},{"id":"q-08-0068","t":"纵观人类历史，教育兴则国家兴，教育强则国家强。世界强国无一不是教育强国，教育始终是强国兴起的关键因素。","author":"习近平"},{"id":"q-08-0069","t":"浇花浇根，育人育心。要坚持不懈用新时代中国特色社会主义思想铸魂育人，着力加强社会主义核心价值观教育，引导学生树立坚定的理想信念，永远听党话、跟党走，矢志奉献国家和人民。","author":"习近平"},{"id":"q-08-0070","t":"要在全社会树立科学的人才观、成才观、教育观，加快扭转教育功利化倾向，形成健康的教育环境和生态。","author":"习近平"},{"id":"q-08-0071","t":"教育公平是社会公平的重要基础，也是建设教育强国的内在要求。要把促进教育公平融入到深化教育领域综合改革的各方面各环节，缩小教育的城乡、区域、校际、群体差距，努力让每个孩子都能享有公平而有质量的教育，更好满足群众对“上好学”的需要。","author":"习近平"},{"id":"q-08-0072","t":"要根据国际形势发展变化，完善教育对外开放战略策略，统筹做好“引进来”和“走出去”两篇大文章，有效利用世界一流教育资源和创新要素，使我国成为具有强大影响力的世界重要教育中心。","author":"习近平"},{"id":"q-08-0073","t":"父母养其子而不教，是不爱其子也。","author":"宋·柳永《劝学文》"},{"id":"q-08-0074","t":"教育为公，以达天下为公。","author":"陶行知"},{"id":"q-08-0075","t":"要把教育和知识变成空气一样，弥漫于宇宙，洗荡于乾坤，普及众生，人人有得呼吸。","author":"陶行知"},{"id":"q-08-0076","t":"知教育者，与其守成法，毋宁尚自然；与其求划一，毋宁展个性。","author":"蔡元培"},{"id":"q-08-0077","t":"普及教育是人类最伟大的发现。","author":"霍勒斯·曼"},{"id":"q-08-0078","t":"使教育过程成为一种艺术的事业","author":"约翰·弗里德里希·赫尔巴特"},{"id":"q-08-0079","t":"农村基础设施建设滞后，是影响农业农村发展的主要制约因素，也是城乡差距的重要体现。","author":"习近平"},{"id":"q-08-0080","t":"要创新投入方式，调动政府和市场两个积极性，发挥财政资金“四两拨千斤”的作用，引导和鼓励各类社会资本投入农村基础设施建设。","author":"习近平"},{"id":"q-08-0081","t":"要科学规划布局前瞻引领型、战略导向型、应用支撑型重大科技基础设施，强化设施建设事中事后监管，完善全生命周期管理，全面提升开放共享水平和运行效率。","author":"习近平"},{"id":"q-08-0082","t":"要继续加快推进交通等基础设施建设，深入推进区域内部协同。","author":"习近平"},{"id":"q-08-0083","t":"要加快建设现代化基础设施体系，提升对内对外开放合作水平。","author":"习近平"},{"id":"q-08-0084","t":"落实好公共基础设施、固定资产加速折旧、资源综合利用等税收优惠政策。","author":"《住房城乡建设部关于印发推进建筑和市政基础设施设备更新工作实施方案的通知》"},{"id":"q-08-0085","t":"坚持标准引领，结合行业发展实际，实施建筑和市政基础设施领域标准提升行动。","author":"《住房城乡建设部关于印发推进建筑和市政基础设施设备更新工作实施方案的通知》"},{"id":"q-08-0086","t":"各地要以大规模设备更新为契机，加快行业领域补齐短板、升级换代、提质增效，提升建筑和市政基础设施设备整体水平。","author":"《住房城乡建设部关于印发推进建筑和市政基础设施设备更新工作实施方案的通知》"},{"id":"q-08-0087","t":"完善污水、生活垃圾、危险废物、医疗废物处置价格形成和收费机制，推动提升环境基础设施可持续运营能力。","author":"《环境基础设施建设水平提升行动（2023—2025年）》"},{"id":"q-08-0088","t":"各地区、各有关部门要充分认识提升环境基础设施建设水平重要意义，建立健全工作机制，上下联动、左右协同，形成工作合力，在切实防范各类风险情况下，分类施策，着力推动环境基础设施建设水平提升行动取得实效。","author":"《环境基础设施建设水平提升行动（2023—2025年）》"},{"id":"q-08-0089","t":"确保国家安全和人民安居乐业。","author":"习近平"},{"id":"q-08-0090","t":"坚持依法防控，要始终把人民群众生命安全和身体健康放在第一位，从立法、执法、司法、守法各环节发力，切实推进依法防控、科学防控、联防联控。","author":"习近平"},{"id":"q-08-0091","t":"要抓好安全生产，进一步做好安全隐患排查，强化预警监测，落实应急措施，保障人民群众生命财产安全。","author":"习近平"},{"id":"q-08-0092","t":"要构建网络空间防御体系，提高维护国家网络安全能力。","author":"习近平"},{"id":"q-08-0093","t":"要贯彻总体国家安全观，坚持底线思维，统筹好发展和安全，盯住关系国家和区域安全的科技、产业、金融等领域和重大基础设施，加强风险防控体系和能力建设，夯实安全发展的基础。","author":"习近平"},{"id":"q-08-0094","t":"居安思危，思则有备，有备无患。","author":"左丘明《左传·襄公十一年》"},{"id":"q-08-0095","t":"故祸几始作，当杜其萌；疾证方形，当绝其根。","author":"南宋·何坦《西畴常言》"},{"id":"q-08-0096","t":"不困在于早虑，不穷在于早豫。","author":"西汉·刘向《说苑·谈丛》"},{"id":"q-08-0097","t":"不乱离，不知太平之难；不疾痛，不知无病之福；故君子于安思危，于治忧乱。","author":"清·魏源《默觚·学篇七》"},{"id":"q-08-0098","t":"正确处理新形势下人民内部矛盾，加强社会治安防控，编织全方位、立体化、智能化社会安全网。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-08-0099","t":"国家矿山安全监察机构必须坚持严的基调，坚持多约谈、多通报、多发督促函、多暗访、多曝光，将责任、压力层层传递到基层末梢。","author":"《关于防范遏制矿山领域重特大生产安全事故的硬措施》"},{"id":"q-08-0100","t":"要树立大农业观、大食物观，农林牧渔并举，构建多元化食物供给体系。","author":"习近平"},{"id":"q-08-0101","t":"高质量推进粮食生产功能区、重要农产品生产保护区和特色农产品优势区建设，打造一批绿色农产品生产加工供应基地，确保粮食等重要农产品稳定安全供给。","author":"习近平"},{"id":"q-08-0102","t":"稳定粮食生产，确保粮食安全，必须保护和调动农民种粮和地方抓粮积极性，健全种粮农民收益保障机制和粮食主产区利益补偿机制，提高政策精准性、实效性，夯实粮食安全根基。","author":"习近平"},{"id":"q-08-0103","t":"粮食安全是“国之大者”，耕地是粮食生产的命根子。","author":"习近平"},{"id":"q-08-0104","t":"我国有14亿多人口，粮食安全必须靠我们自己保证，中国人的饭碗应该主要装中国粮。","author":"习近平"},{"id":"q-08-0105","t":"要未雨绸缪，始终绷紧粮食安全这根弦，始终坚持以我为主、立足国内、确保产能、适度进口、科技支撑。","author":"习近平"},{"id":"q-08-0106","t":"采取有效措施切实把黑土地这个“耕地中的大熊猫”保护好、利用好，使之永远造福人民。","author":"习近平"},{"id":"q-08-0107","t":"王者以民人为天，而民人以食为天。","author":"《史记·郦生陆贾列传》"},{"id":"q-08-0108","t":"谁知盘中餐，粒粒皆辛苦。","author":"唐·李绅《悯农》"},{"id":"q-08-0109","t":"粮食安全是“国之大者”，保障粮食和重要农产品稳定安全供给始终是建设农业强国的头等大事。","author":"《农业农村部关于开展2024年“绿剑护粮安”执法行动的通知》"}],"党的建设篇":[{"id":"q-09-0000","t":"锚定建设农业强国目标，聚焦保障粮食和重要农产品稳定安全供给，突出重点领域和重大专项，集中力量严厉打击坑农害农、危害粮食安全违法行为，抓好办成群众可感可及实事，增强人民群众获得感、幸福感、安全感，为保障国家粮食安全贡献农业执法力量。","author":"《农业农村部关于开展2024年“绿剑护粮安”执法行动的通知》"},{"id":"q-09-0001","t":"组织是“形”，思想是“魂”。加强党的组织建设，既要“造形”，更要“铸魂”。","author":"习近平"},{"id":"q-09-0002","t":"要健全上下贯通、执行有力的组织体系。","author":"习近平"},{"id":"q-09-0003","t":"坚持和完善党建工作领导体制和组织管理体制，形成一级抓一级、抓好本级带下级、大抓基层强基础的工作格局，推动各层级各领域党组织全面过硬。","author":"习近平"},{"id":"q-09-0004","t":"织领导基层治理能力。","author":"习近平"},{"id":"q-09-0005","t":"探索加强新经济组织、新社会组织、新就业群体党建工作，创新党组织设置和活动方式。","author":"习近平"},{"id":"q-09-0006","t":"善于运用互联网技术和信息化手段开展党建工作，努力实现党的组织和党的工作线下线上全覆盖。","author":"习近平"},{"id":"q-09-0007","t":"完善党中央对各级各类组织设立和运行的领导制度，强化对机构改革的顶层设计和谋篇布局。","author":"《中央党内法规制定工作规划纲要（2023－2027年）》"},{"id":"q-09-0008","t":"严密的组织体系是党的优势所在、力量所在。","author":"《中央党内法规制定工作规划纲要（2023－2027年）》"},{"id":"q-09-0009","t":"加大党际交往力度，健全党际交往制度，完善社会组织参与国际非政府组织活动等民间外交的制度。","author":"《中央党内法规制定工作规划纲要（2023－2027年）》"},{"id":"q-09-0010","t":"以制度推动完善上下贯通、执行有力的组织体系，把党的组织优势巩固好、发展好、发挥好。","author":"《中央党内法规制定工作规划纲要（2023－2027年）》"},{"id":"q-09-0011","t":"健全党组织的组织生活、组织运行、组织管理、组织监督等制度，推动党组织认真履行党章党规赋予的职责，从组织上保证党的基本理论、基本路线、基本方略的贯彻落实。","author":"《中央党内法规制定工作规划纲要（2023－2027年）》"},{"id":"q-09-0012","t":"持续推进反腐败国家立法，与时俱进修改监察法，以学习贯彻新修订的纪律处分条例为契机，在全党开展一次集中性纪律教育。","author":"习近平"},{"id":"q-09-0013","t":"要大兴务实之风、清廉之风、俭朴之风，发扬自我革命精神，在全党组织开展好集中性纪律教育。","author":"习近平"},{"id":"q-09-0014","t":"组织开展好党纪学习教育，引导党员干部学纪、知纪、明纪、守纪，督促领导干部树立正确权力观，公正用权、依法用权、为民用权、廉洁用权。","author":"习近平"},{"id":"q-09-0015","t":"要牢固树立正确政绩观，既要做让老百姓看得见、摸得着、得实惠的实事，也要做为后人作铺垫、打基础、利长远的好事，既要做显功，也要做潜功。","author":"习近平"},{"id":"q-09-0016","t":"要加强新时代廉洁文化建设。深入开展党性党风党纪教育，传承党的光荣传统和优良作风，激发共产党员崇高理想追求，把以权谋私、贪污腐败看成是极大的耻辱。","author":"习"},{"id":"q-09-0017","t":"新征程反腐败斗争，必须在铲除腐败问题产生的土壤和条件上持续发力、纵深推进。","author":"习近平"},{"id":"q-09-0018","t":"面对依然严峻复杂的形势，反腐败绝对不能回头、不能松懈不能慈悲，必须永远吹冲锋号。","author":"习近平"},{"id":"q-09-0019","t":"要建立腐败预警惩治联动机制，加强廉洁风险隐患动态监测，强化对新型腐败和隐性腐败的快速处置。","author":"习近平"},{"id":"q-09-0020","t":"清心为治本，直道是身谋。","author":"宋·包拯《书端州郡斋壁》"},{"id":"q-09-0021","t":"粉骨碎身全不怕，要留清白在人间。","author":"明·于谦《石灰吟》"},{"id":"q-09-0022","t":"钱财如粪土，仁义值千金。","author":"《醒世恒言·卷十七》"},{"id":"q-09-0023","t":"人民，只有人民，才是创造世界历史的动力。","author":"习近平"},{"id":"q-09-0024","t":"我们党深刻认识到中国式现代化是亿万人民自己的事业，人民是中国式现代化的主体，必须紧紧依靠人民，尊重人民创造精神，汇集全体人民的智慧和力量，才能推动中国式现代化不断向前发展。","author":"习近平"},{"id":"q-09-0025","t":"我们共产党人干事业、创政绩，为的是造福人民，不是为了个人升迁得失。","author":"习近平"},{"id":"q-09-0026","t":"我不到16岁就在陕北的一个小村子里同农民住在一起、干在一起，知道人民愁什么、盼什么。从那时到现在，半个世纪过去了，在人民中间让我觉得踏实，同人民在一起让我有力量。我将无我、不负人民，这就是我终生的信念。","author":"习近平"},{"id":"q-09-0027","t":"要求真务实、真抓实干，做工作自觉从人民利益出发，决不能为了树立个人形象，搞华而不实、劳民伤财的“形象工程”、“政绩工程”。","author":"习近平"},{"id":"q-09-0028","t":"政之所兴在顺民心，政之所废在逆民心。","author":"《管子·牧民》"},{"id":"q-09-0029","t":"为民贵，社稷次之，君为轻。","author":"先秦·孟子《孟子四章》"},{"id":"q-09-0030","t":"德为善政，政在养民。","author":"《尚书》"},{"id":"q-09-0031","t":"为国者以民为基。","author":"《三国志》"},{"id":"q-09-0032","t":"最高的道德就是不断地为人服务，为人类的爱而工作。","author":"甘地"},{"id":"q-09-0033","t":"谁为时代的伟大目标服务，并把自己的一生献给了为人类兄弟而进行的斗争，谁才是不朽的。","author":"涅克拉索夫"},{"id":"q-09-0034","t":"人生最美好的，就是在你停止生存时，也还能以你所创造的一切为人们服务。","author":"奥斯特洛夫斯基"},{"id":"q-09-0035","t":"治国必先治党，治党务必从严。","author":"习近平"},{"id":"q-09-0036","t":"党要管党，才能管好党；从严治党，才能治好党。","author":"习近平"},{"id":"q-09-0037","t":"面对新征程上的新挑战新考验，我们必须高度警省，永远保持赶考的清醒和谨慎，驰而不息推进全面从严治党，使百年大党在自我革命中不断焕发蓬勃生机，始终成为中国人民最可靠、最坚强的主心骨。","author":"习近平"},{"id":"q-09-0038","t":"坚持严的主基调不动摇，提高纪律建设的政治性、时代性、针对性。必须执行政治纪律，带动各项纪律全面从严、一严到底，坚持纪严于法、执纪执法贯通，深化运用“四种形态”政策策略，执纪必严、违纪必究，以严明的纪律确保全党目标一致、团结一致、步调一致。","author":"习近平"},{"id":"q-09-0039","t":"要坚持内容上全涵盖，党的建设推进到哪里，全面从严治党体系就要构建到哪里，无论党的政治建设、思想建设、组织建设、作风建设、纪律建设，还是制度建设、反腐败斗争，都要自觉贯彻全面从严治党战略方针，不能把全面从严治党局限于正风、肃纪、反腐。","author":"习近平"},{"id":"q-09-0040","t":"夫为政者，莫善于清其吏也。","author":"唐·魏征等人《群书治要》"},{"id":"q-09-0041","t":"是则圣贤之意较然著明，惟以改过为能，不以无过为贵。","author":"《资治通鉴》"},{"id":"q-09-0042","t":"禁微则易，救末者难。","author":"南北朝·范晔《后汉书·桓荣丁鸿列传》"},{"id":"q-09-0043","t":"善禁者，先禁其身而后人；不善禁者，先禁人而后身。","author":"东汉·荀悦《申鉴·政体》"},{"id":"q-09-0044","t":"改落实。","author":"《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》"},{"id":"q-09-0045","t":"要持续整治群众身边腐败和不正之风，推动全面从严治党向基层延伸。","author":"四川省《关于推进2024年全面从严治党、党风廉政建设和反腐败工作的意见》"},{"id":"q-09-0046","t":"干部素质培养是一个长期过程，不是朝夕之功。","author":"习近平"},{"id":"q-09-0047","t":"要自觉做党的创新理论的笃信笃行者，坚持不懈用新时代中国特色社会主义思想凝心铸魂，不断筑牢信仰之基、补足精神之钙、把稳思想之舵，切实提升马克思主义理论水平和运用能力。","author":"习近平"},{"id":"q-09-0048","t":"要自觉做矢志为民造福的无私奉献者，始终把人民放在心中最高位置，树立和践行正确政绩观，走好新时代党的群众路线，提高做群众工作的本领，用心用情用力解决群众急难愁盼问题，不断增强人民群众的获得感、幸福感、安全感。","author":"习近平"},{"id":"q-09-0049","t":"要自觉做对党忠诚老实的模范践行者，旗帜鲜明讲政治，着力提高政治判断力、政治领悟力、政治执行力，严守党的政治纪律和政治规矩，说老实话、办老实事、做老实人，始终同党中央保持高度一致。","author":"习近平"},{"id":"q-09-0050","t":"要自觉做勇于担当作为的不懈奋斗者，锐意改革创新，敢于善于斗争，愿挑最重的担子、能啃最硬的骨头、善接烫手的山芋，在直面问题、破解难题中不断打开工作新局面。","author":"习近平"},{"id":"q-09-0051","t":"要自觉做良好政治生态的有力促进者，发扬彻底的自我革命精神，节俭朴素、谦逊低调，坚决反对形式主义、官僚主义，坚决反对特权思想和特权行为，永葆共产党人清正廉洁的政治本色。","author":"习近平"},{"id":"q-09-0052","t":"干部教育培训是建设高素质干部队伍的先导性、基础性、战略性工程，在推进中国特色社会主义伟大事业和党的建设新的伟大工程中具有不可替代的重要地位和作用。","author":"《全国干部教育培训规划（2023－2027年）》"},{"id":"q-09-0053","t":"完善干部理论教育培训长效机制，落实党的创新理论学习教育计划，组织实施习近平新时代中国特色社会主义思想教育培训计划，系统谋划、持续用力，不断把思想铸魂、理论武装工作引向深入。","author":"《全国干部教育培训规划（2023－2027年）》"},{"id":"q-09-0054","t":"改进理论教学，开展集体备课，坚持历史和现实相贯通、国际和国内相关联、理论和实际相结合，推行课堂讲授、案例解析、现场感悟相结合的教学方式，增强理论教育的吸引力感染力说服力。","author":"《全国干部教育培训规划（2023－2027年）》"},{"id":"q-09-0055","t":"坚持把政治训练贯穿干部成长全周期，使干部的政治素养、政治能力与担负的领导职责相匹配。","author":"《全国干部教育培训规划（2023－2027年）》"},{"id":"q-09-0056","t":"党的事业伟大而艰巨、任重而道远，有人走着走着就忘记了为什么出发，忘记了共产主义远大理想和中国特色社会主义共同理想，忘记了我是谁、为了谁、依靠谁，从而丧失了共产党人的本色。","author":"习近平"},{"id":"q-09-0057","t":"我们必须坚守奠基创业时的初心，坚守党的理想信念宗旨，始终为中国人民谋幸福、为中华民族谋复兴，始终保持党同人民群众的血肉联系，永葆党的先进性和纯洁性。","author":"习近平"},{"id":"q-09-0058","t":"不忘初心、牢记使命要靠全党共同努力来实现，每一个党员、干部特别是领导干部必须常怀忧党之心、为党之责、强党之志。","author":"习近平"},{"id":"q-09-0059","t":"我们党始终坚守为中国人民谋幸福、为中华民族谋复兴这个初心和使命，义无反顾向着这个目标前进，从而赢得了人民衷心拥护和坚定支持。","author":"习近平"},{"id":"q-09-0060","t":"坚定信念，就是坚持不忘初心、不移其志，以坚忍执着的理想信念，以对党和人民的赤胆忠心，把对党和人民的忠诚和热爱牢记在心目中、落实在行动上，为党和人民事业奉献自己的一切乃至宝贵生命，为党的理想信念顽强奋斗、不懈奋斗。","author":"习近平"},{"id":"q-09-0061","t":"守其初心，始终不变。","author":"宋·苏轼《杭州召还乞郡状》"},{"id":"q-09-0062","t":"立志不坚，终不济事。","author":"宋·朱熹《朱子语类》"},{"id":"q-09-0063","t":"穷且益坚，不坠青云之志。","author":"唐·王勃《滕王阁序》"},{"id":"q-09-0064","t":"来时是赤子，归时莫忘仍怀一颗初心。","author":"史铁生"},{"id":"q-09-0065","t":"一种理想，就是一种力！","author":"罗曼·罗兰"},{"id":"q-09-0066","t":"有信念的人经得起任何风暴。","author":"奥维德"},{"id":"q-09-0067","t":"我们党历来重视党史学习教育，注重用党的奋斗历程和伟大成就鼓舞斗志、明确方向，用党的光荣传统和优良作风坚定信念、凝聚力量，用党的实践创造和历史经验启迪智慧、砥砺品格。","author":"习近平"},{"id":"q-09-0068","t":"我们党的历史就是我们党与人民心心相印、与人民同甘共苦、与人民团结奋斗的历史，一定要一块过、一块干，始终保持同人民群众的血肉联系。","author":"习近平"},{"id":"q-09-0069","t":"我们要在学好党史的基础上，学好中国近代史，学好中国历史，弄清楚我们从哪里来、要到哪里去，弄清楚中国共产党人是干什么的、已经干了什么、还要干什么，弄清楚过去我们为什么能够成功、未来怎样才能继续成功。","author":"习近平"},{"id":"q-09-0070","t":"推动全党学好党史、用好党史，靠一次集中学习教育是不够的，必须把党史学习教育融入日常、抓在经常。","author":"习近平"},{"id":"q-09-0071","t":"要巩固拓展党史学习教育成果，建立常态化长效化制度机制，教育引导广大党员、干部把学党史、用党史作为终身必修课，不断坚定历史自信、增强政治自觉，弘扬伟大建党精神，更加信心满怀地奋进新征程、建功新时代。","author":"习近平"},{"id":"q-09-0072","t":"学习党史是每一位党员的义务。要推动党史学习教育常态化长效化，引导广大党员、干部把学习党史作为必修课和常修课。","author":"习近平"},{"id":"q-09-0073","t":"自从有了中国共产党，中国革命的面目就焕然一新了。","author":"毛泽东"},{"id":"q-09-0074","t":"活到老，学到老，改造到老。","author":"周恩来"},{"id":"q-09-0075","t":"推动党史学习教育进机关、进企事业单位、进城乡社区、进校园、进军营、进新经济组织和新社会组织、进网站。","author":"《党史学习教育工作条例》"},{"id":"q-09-0076","t":"弘扬伟大建党精神，坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民，为强国建设、民族复兴提供精神力量。","author":"《党史学习教育工作条例》"},{"id":"q-09-0077","t":"学史崇德。教育引导党员涵养高尚道德品质，崇尚对党忠诚的大德、造福人民的公德、严于律己的品德，做到始终忠于党、忠于人民。","author":"《党史学习教育工作条例》"}],"人生哲学篇":[{"id":"q-10-0001","t":"我们要大力倡导这种爱国奉献精神，使之成为新时代奋斗者的价值追求。","author":"习近平"},{"id":"q-10-0002","t":"广大党员干部和青年同志要以黄文秀同志为榜样，不忘初心、牢记使命，勇于担当、甘于奉献，在新时代的长征路上做出新的更大贡献。","author":"习近平"},{"id":"q-10-0003","t":"追梦需要激情和理想，圆梦需要奋斗和奉献。","author":"习近平"},{"id":"q-10-0004","t":"每一个平凡的人都作出了不平凡的贡献！","author":"习近平"},{"id":"q-10-0005","t":"我是炎黄子孙，理所当然地要把学到的知识全部奉献给我亲爱的祖国。","author":"李四光"},{"id":"q-10-0006","t":"光明的中国，让我的生命为你燃烧吧。","author":"钱三强"},{"id":"q-10-0007","t":"有一分热，发一分光。","author":"鲁迅"},{"id":"q-10-0008","t":"我们必须奉献于生命，才能获得生命。","author":"泰戈尔"},{"id":"q-10-0009","t":"奉献乃生活的真正意义。","author":"阿德勒"},{"id":"q-10-0010","t":"要重返生活就须有所奉献。","author":"高尔基"},{"id":"q-10-0011","t":"我们应当在不同的岗位上，随时奉献自己。","author":"海塞"},{"id":"q-10-0012","t":"领导讲话只要我们坚持道不变、志不改，一以贯之、勠力同心，就一定能够战胜前进中的各种艰难险阻，不断迈向成功的彼岸！","author":"习近平"},{"id":"q-10-0013","t":"长风破浪会有时，直挂云帆济沧海。","author":"唐·李白《行路难·其一》"},{"id":"q-10-0014","t":"天生我材必有用，千金散尽还复来。","author":"唐·李白《将进酒·君不见》"},{"id":"q-10-0015","t":"山重水复疑无路，柳暗花明又一村。","author":"宋·陆游《游山西村》"},{"id":"q-10-0016","t":"风力掀天浪打头，只须一笑不须愁。","author":"宋·杨万里《闷歌行十二首其一》"},{"id":"q-10-0017","t":"如果人是乐观的，一切都有抵抗，一切都能抵抗，一切都会增强抵抗力。","author":"瞿秋白"},{"id":"q-10-0018","t":"人生要有意义只有发扬生命，快乐就是发扬生命的最好方法。","author":"张闻天"},{"id":"q-10-0019","t":"真正的快乐，是对生活的乐观，对工作的愉快，对事业的热心。","author":"爱因斯坦"},{"id":"q-10-0020","t":"生活的美妙就在于它的丰富多彩，要使生活变得有趣，就不断地充实它。","author":"高尔基"},{"id":"q-10-0021","t":"乌云后面依然是灿烂的晴天。","author":"朗弗罗"},{"id":"q-10-0022","t":"新征程上，我们的前途一片光明，但脚下的路不会是一马平川。团结就是力量，信心赛过黄金。我们要坚定信心，振奋精神，团结奋斗，继续爬坡过坎、攻坚克难，坚定不移朝着强国建设、民族复兴的宏伟目标奋勇前进！","author":"习近平"},{"id":"q-10-0023","t":"全党同志要大力弘扬自力更生、艰苦奋斗精神，无论我们将来物质生活多么丰富，自力更生、艰苦奋斗的精神一定不能丢，脚踏实地、苦干实干，集中精力办好自己的事情，把国家和民族发展放在自己力量的基点上。","author":"习近平"},{"id":"q-10-0024","t":"历史长河波澜壮阔，一代又一代人接续奋斗创造了今天的中国。","author":"习近平"},{"id":"q-10-0025","t":"时间不等人！历史不等人！时间属于奋进者！历史属于奋进者！","author":"习近平"},{"id":"q-10-0026","t":"解决发展不平衡不充分问题、缩小城乡区域发展差距、实现人的全面发展和全体人民共同富裕仍然任重道远。我们没有任何理由骄傲自满、松劲歇脚，必须乘势而上、再接再厉、接续奋斗。","author":"习近平"},{"id":"q-10-0027","t":"必须在奋斗中求生存，求发展。","author":"茅盾"},{"id":"q-10-0028","t":"守其初心，始终不变。","author":"宋·苏轼《杭州召还乞郡状》"},{"id":"q-10-0029","t":"功崇惟志，业广惟勤。","author":"《尚书·周书·周官》"},{"id":"q-10-0030","t":"发明的秘诀在不断的努力。","author":"牛顿"},{"id":"q-10-0031","t":"一个人必须经过一番刻苦奋斗，才会有所成就。","author":"汉斯·克里斯汀·安徒生"},{"id":"q-10-0032","t":"空谈误国、实干兴邦，一分部署、九分落实。不注重抓落实，不认真抓好落实，再好的规划和部署都会沦为空中楼阁。","author":"习近平"},{"id":"q-10-0033","t":"“知”是基础、是前提，“行”是重点、是关键，必须以“知”促“行”、以“行”促“知”，做到知行合一。","author":"习近平"},{"id":"q-10-0034","t":"培育和践行社会主义核心价值观，贵在坚持知行合一、坚持行胜于言，在落细、落小、落实上下功夫。","author":"习近平"},{"id":"q-10-0035","t":"学到的东西，不能停留在书本上，不能只装在脑袋里，而应该落实到行动上，做到知行合一、以知促行、以行求知，正所谓‘知者行之始，行者知之成’。","author":"习近平"},{"id":"q-10-0036","t":"圣贤先觉之人，知而能之，知行合一，后觉所以效之。","author":"金履祥《论语集注考证》"},{"id":"q-10-0037","t":"非知之实难，将在行之。","author":"《左传·昭公十年》"},{"id":"q-10-0038","t":"论先后，知为先；论轻重，行为重。","author":"宋·朱熹《语类》"},{"id":"q-10-0039","t":"纸上得来终觉浅，绝知此事要躬行。","author":"宋·陆游《冬夜读书示子聿》"},{"id":"q-10-0040","t":"不登高山，不知天之高也；不临深溪，不知地之厚也","author":"战国·荀子《劝学》"},{"id":"q-10-0041","t":"理论是军官，实践是士兵。","author":"达·芬奇"},{"id":"q-10-0042","t":"理论在变为实践，理论由实践赋予活力，由实践来修正，由实践来检验。","author":"列宁"},{"id":"q-10-0043","t":"当青年犯了错误、做了错事时要及时指出并帮助他们纠正，对一些青年思想上的一时冲动或偏激要多教育引导，能包容要包容，多给他们一点提高自我认识的时间和空间，不要过于苛责。","author":"习近平"},{"id":"q-10-0044","t":"坚持包容共济，进一步促进社会和谐稳定。","author":"习近平"},{"id":"q-10-0046","t":"泰山不让土壤，故能成其大；河海不择细流，故能就其深。","author":"秦国·李斯《谏逐客书》"},{"id":"q-10-0047","t":"上不宽大包容臣下，则不能居圣位。","author":"《汉书·五行志下》"},{"id":"q-10-0048","t":"海纳百川，有容乃大。","author":"林则徐总督府衙堂联"},{"id":"q-10-0049","t":"以大度兼容，则万物兼济。","author":"《宋朝事实类苑·祖宗圣训》"},{"id":"q-10-0050","t":"心狭为祸之根，心旷为福之门。","author":"王阳明《传习录》"},{"id":"q-10-0051","t":"严于律己，出而见之事功；心乎爱民，动必关天治道。","author":"宋·陈亮《谢曾察院君》"},{"id":"q-10-0052","t":"世界上最宽阔的是海洋，比海洋更宽阔的是天空，比天空更宽阔的是人的胸怀。","author":"雨果"},{"id":"q-10-0053","t":"宽宏精神是一切事物中最伟大的。","author":"欧文"},{"id":"q-10-0054","t":"节俭朴素，力戒奢靡，是我们党的传家宝。现在，我们生活条件好了，但艰苦奋斗的精神一点都不能少，必须坚持以俭修身、以俭兴业，坚持厉行节约、勤俭办一切事情。","author":"习近平"},{"id":"q-10-0055","t":"不论我们国家发展到什么水平，不论人民生活改善到什么地步，艰苦奋斗、勤俭节约的思想永远不能丢。","author":"习近平"},{"id":"q-10-0056","t":"要坚持勤俭办一切事业，坚决反对讲排场比阔气，坚决抵制享乐主义和奢靡之风。要大力弘扬中华民族勤俭节约的优秀传统，大力宣传节约光荣、浪费可耻的思想观念，努力使厉行节约、反对浪费在全社会蔚然成风。","author":"习近平"},{"id":"q-10-0057","t":"要加强立法，强化监管，采取有效措施，建立长效机制，坚决制止餐饮浪费行为。要进一步加强宣传教育，切实培养节约习惯，在全社会营造浪费可耻、节约为荣的氛围。","author":"习近平"},{"id":"q-10-0058","t":"历览前贤国与家，成由勤俭败由奢。","author":"唐·李商隐《咏史二首·其二》"},{"id":"q-10-0059","t":"俭，德之共也；侈，恶之大也。","author":"《左传·庄公·庄公二十四年》"},{"id":"q-10-0060","t":"克勤于邦，克俭于家。","author":"《尚书·大禹谟》"},{"id":"q-10-0061","t":"一粥一饭，当思来处不易。","author":"朱柏庐《治家格言》"},{"id":"q-10-0062","t":"国外名言节约与勤勉是人类两个名医。","author":"卢梭"},{"id":"q-10-0063","t":"政策理论大力提倡健康饮食，健全部门监管、行业自律、社会监督相结合的监管体系，坚决制止餐饮浪费行为。","author":"《中共中央国务院关于学习运用“千村示范、万村整治”工程经验有力有效推进乡村全面振兴的意见》"},{"id":"q-10-0064","t":"为者常成，行者常至，历史不会辜负实干者。","author":"习近平"},{"id":"q-10-0065","t":"要脚踏实地，埋头苦干，不驰于空想，不骛于虚声。","author":"习近平"},{"id":"q-10-0066","t":"只要有愚公移山的志气、滴水穿石的毅力，脚踏实地，埋头苦干，积跬步以至千里，就一定能够把宏伟目标变为美好现实。","author":"习近平"},{"id":"q-10-0067","t":"要脚踏实地，埋头苦干，不驰于空想，不骛于虚声；要笃实好学，尊重实际，不违背规律，不盲目蛮干；要求真务实，注重实效，不做表面文章，不要花拳绣腿。","author":"习近平"},{"id":"q-10-0068","t":"为者常成，行者常至，历史不会辜负实干者。我们靠实干创造了辉煌的过去，还要靠实干开创更加美好的未来。","author":"习近平"},{"id":"q-10-0069","t":"合抱之木，生于毫末；九层之合，起于垒土；千里之行，始于足下。","author":"春秋·老子《道德经·第六十四章》"},{"id":"q-10-0070","t":"古今中外，凡成就事业，对人类有所作为的，无一不是脚踏实地、艰苦攀登的结果。","author":"钱三强"},{"id":"q-10-0071","t":"不积跬步，无以至千里；不积小流，无以成江海。骐骥一跃，不能十步；驽马十驾，功在不舍。","author":"荀子•《劝学》"},{"id":"q-10-0072","t":"世上无难事，只要肯攀登。","author":"毛泽东《水调歌头·重上井冈山》"},{"id":"q-10-0073","t":"要成就一件大事业，必须从小事做起。","author":"列宁"},{"id":"q-10-0074","t":"我们对真理所能表示的最大崇拜，就是要脚踏实地地去履行它。","author":"爱默生"},{"id":"q-10-0075","t":"穷则变，变则通，通则久。","author":"《周易·系辞下》"},{"id":"q-10-0076","t":"变则新，不变则腐；变则活，不变则板。","author":"李渔《闲情偶寄》"},{"id":"q-10-0077","t":"变通革弊，与时宜之。","author":"《辽史.礼志一》"},{"id":"q-10-0078","t":"治国无法则乱，守法而弗变则悖，悖乱不可以持国。","author":"《吕氏春秋·察今》"},{"id":"q-10-0079","t":"既有师法，又有变通。","author":"宋·刘道醇《圣朝名画评》"},{"id":"q-10-0080","t":"情况是在不断地变化，要使自己的思想适应新的情况，就得学习。","author":"毛泽东"},{"id":"q-10-0081","t":"周失之弱，秦失之强，不变之患也。","author":"司马迁《史记》"},{"id":"q-10-0082","t":"变或可存，不变则削，全变乃存，小变仍削。","author":"康有为《政论集》"},{"id":"q-10-0083","t":"别妄想世界永恒不变。","author":"塞万提斯"},{"id":"q-10-0084","t":"一个能思想的人，才真是一个力量无边的人。","author":"巴尔扎克"},{"id":"q-10-0085","t":"打造忠诚干净担当的高素质专业化干部队伍，建立健全考核激励制度，关心关爱基层干部特别是条件艰苦地区干部，激励干部锐意进取、大胆开拓、担当作为。","author":"习近平"},{"id":"q-10-0086","t":"青年一代有理想、有本领、有担当，国家就有前途，民族就有希望。","author":"习近平"},{"id":"q-10-0087","t":"干部敢于担当作为，这既是政治品格，也是从政本分。","author":"习近平"},{"id":"q-10-0088","t":"广大青年用行动证明，新时代的中国青年是好样的，是堪当大任的！","author":"习近平"},{"id":"q-10-0089","t":"担当和作为是一体的，不作为就是不担当，有作为就要有担当。做事总是有风险的。正因为有风险，才需要担当。","author":"习近平"},{"id":"q-10-0090","t":"知责任者，大丈夫之始也；行责任者，大丈夫之终也。","author":"梁启超《呵旁观者文》"},{"id":"q-10-0091","t":"苟利国家生死以，岂因祸福避趋之。","author":"清·林则徐《赴戍登程口占示家人二首》"},{"id":"q-10-0092","t":"为中华之崛起而读书。","author":"周恩来"},{"id":"q-10-0093","t":"一个人越敢于担当大任，他的意气就越风发。","author":"班斯腾·班生"},{"id":"q-10-0094","t":"尽管责任有时使人厌烦，但不履行责任，只能是懦夫，不折不扣的废物。","author":"刘易斯"}]};
